BEGIN;
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '340669ca-680b-585c-b20f-421b1d648aef','Prosodic transfer','The carrying-over of suprasegmental features — intonation contour, stress placement, rhythm and tempo — from the source performance into the target-language dub, so the dubbed line reproduces the melody and emphasis of the original. It can involve preserving, approximating or deliberately re-mapping these features to the target line.','This carries the speech melody of the original into the new language. The dubbed line keeps a similar stress, rhythm, and rise and fall in pitch.','It helps the dub reproduce the emotion and intent the original conveyed through its melody, not just its words. Prosody often carries sarcasm, doubt or urgency that would otherwise be lost.','An adapter and voice actor reproduce the original''s rising questioning tone or clipped angry rhythm on the equivalent target words.','Dialogue Adaptation',ARRAY['Prosodic adaptation','Prosodic alignment','Prosodic resegmentation','Pragmatic stress','Prefabricated orality','Speech-rate compensation']::text[],ARRAY['Transferring the exact source intonation so literally that it sounds foreign in the target language.','Copying only the words and dropping the melody, so sarcasm or emphasis is lost.','Assuming the same pitch pattern means the same thing across languages.']::text[],ARRAY['Reproducing an ironic rising tone that signals sarcasm in a dubbed comedy.','Keeping a character''s fast, clipped delivery when dubbing an argument.','Carrying a hesitant, uncertain rhythm across into the target performance.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='340669ca-680b-585c-b20f-421b1d648aef' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prosodic transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '340669ca-680b-585c-b20f-421b1d648aef','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='340669ca-680b-585c-b20f-421b1d648aef' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '95988954-d3ca-5a90-9012-97cb16dbd97f','Rounded-vowel correspondence','A phonetic-synchrony technique in which visibly rounded or protruded vowels in the source (for example English /uː/, /oʊ/, /ɔː/, /ʊ/) are matched in the dubbed line with target-language phonemes that produce a visually equivalent lip position, especially in close-ups. It relies on viseme grouping rather than identical sounds.','Some vowels round the lips, like the sounds in oo and oh. On close-ups we clearly see that shape. The dubbed word should use a rounded vowel there too.','It preserves lip-sync credibility at the most visible points, because a rounded mouth shape is conspicuous and viewers easily spot a mismatch. It exists because the eye catches lip shape even when sounds differ.','A dialogue writer chooses a target word with a rounded vowel to coincide with a close-up where the actor''s lips are clearly pursed.','Phonetic Synchrony',ARRAY['Lip synchrony','Bilabial matching','Viseme','Isochrony','Segment-duration matching','Dialogue adaptation']::text[],ARRAY['Trying to match the exact same phoneme instead of any phoneme sharing the rounded viseme.','Ignoring rounded vowels in close-ups where the lip shape is most visible.','Over-constraining wide shots where lip shape is not clearly seen, sacrificing meaning needlessly.']::text[],ARRAY['Choosing a target word ending in an ''oo'' shape to match a visible pucker on a close-up.','Dubbing an animated film where exaggerated rounded mouth shapes are prominent.','Reworking a line so a rounded vowel falls on the frame where the actor''s lips round.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='95988954-d3ca-5a90-9012-97cb16dbd97f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rounded-vowel correspondence'),'[^a-z0-9]','','g'));
