SELECT '95988954-d3ca-5a90-9012-97cb16dbd97f','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='95988954-d3ca-5a90-9012-97cb16dbd97f' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '95656e88-2432-53ee-adbc-b5c6226d0ef4','Segment-duration matching','The practice, central to isochrony, of making each dubbed utterance or phrase occupy the same duration as the corresponding source segment, so the target speech starts and ends with the on-screen character''s mouth activity. It governs how many syllables and words a line can carry in the available time.','Each spoken bit must last about as long as the original. If the actor speaks for two seconds, the new line should fill that same time.','It keeps the dubbed voice locked to the visible start and stop of the character''s speech, preserving the illusion that the actor is speaking the target words. Mismatched duration breaks that illusion.','An adapter counts beats and trims or pads a line so it fills exactly the span between the actor opening and closing their mouth.','Sync & Timing',ARRAY['Isochrony','Segmentation mismatch','Prosodic resegmentation','Speech-rate compensation','Silence accommodation','Lip synchrony']::text[],ARRAY['Writing a line that is accurate but too long or too short for the visible mouth activity.','Padding with filler that fits the time but sounds unnatural or off-character.','Measuring only the whole scene instead of each individual utterance''s duration.']::text[],ARRAY['Trimming a wordy translation so it ends when the character closes their mouth.','Padding a short target line so it fills the full length of the on-screen speech.','Timing a dubbed take against the picture to confirm each phrase fits its slot.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='95656e88-2432-53ee-adbc-b5c6226d0ef4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Segment-duration matching'),'[^a-z0-9]','','g'));
