SELECT '95656e88-2432-53ee-adbc-b5c6226d0ef4','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='95656e88-2432-53ee-adbc-b5c6226d0ef4' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ed1bbbf7-3b2a-5ae6-81d5-aaeab21c340e','Segmentation mismatch','A sync problem in which the way a target-language line divides an utterance into phrases, pauses or takes fails to line up with the source and the on-screen delivery, causing breaks, breaths or take boundaries to fall in the wrong places. It is the failure state that prosodic resegmentation aims to prevent.','Languages split a sentence into chunks in different ways. A mismatch is when those chunks do not line up, so breaks fall in the wrong spots.','Naming it helps adapters spot and fix places where phrasing or pause structure clashes with the picture. Unresolved, it makes the dub feel out of step with the character.','An adapter notices a dubbed pause landing mid-gesture and rechunks the line so its breaks match the on-screen phrasing.','Sync & Timing',ARRAY['Prosodic resegmentation','Segment-duration matching','Isochrony','Silence accommodation','Prosodic alignment','Dialogue adaptation']::text[],ARRAY['Keeping the source segmentation and forcing pauses where the target language would not pause.','Placing a breath or take break where the character is clearly still speaking on screen.','Fixing word choice while ignoring that the phrase boundaries no longer match the picture.']::text[],ARRAY['A dubbed line pauses mid-sentence while the actor keeps talking on screen.','Take boundaries in the script split a phrase the target language treats as one unit.','Reviewing a dub where breaths fall in unnatural places relative to the picture.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ed1bbbf7-3b2a-5ae6-81d5-aaeab21c340e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Segmentation mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ed1bbbf7-3b2a-5ae6-81d5-aaeab21c340e','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ed1bbbf7-3b2a-5ae6-81d5-aaeab21c340e' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '471f0a51-c024-5a09-af9b-5903b795d55d','Silence accommodation','The handling of pauses and silent gaps so the dubbed line reproduces the source''s moments of non-speech, leaving quiet where the character is silent on screen and not letting target words spill into those gaps. Dubbing scripts mark such pauses with conventional symbols tied to their length.','The original has quiet gaps where no one speaks. The dubbed line must leave those same gaps, so words do not spill into the silence.','It preserves the dramatic timing and realism of the scene, since silences carry meaning and must coincide with the character''s closed mouth. Filling them with speech breaks sync and changes the mood.','An adapter marks pauses in the script and writes the line so speech stops and resumes exactly where the character does on screen.','Sync & Timing',ARRAY['Isochrony','Segment-duration matching','Prosodic alignment','Segmentation mismatch','Prosodic resegmentation','Lip synchrony']::text[],ARRAY['Filling a silent beat with added words because the target line felt too short.','Ignoring pause markers, so dubbed speech continues while the character''s mouth is shut.','Misjudging the length of a pause and mistiming when speech should resume.']::text[],ARRAY['Keeping a tense dramatic pause silent instead of adding a line to fill time.','Marking a two-to-three-second gap in the script so no dialogue is written over it.','Timing a resumed line to start exactly when the character speaks again on screen.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='471f0a51-c024-5a09-af9b-5903b795d55d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Silence accommodation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '471f0a51-c024-5a09-af9b-5903b795d55d','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='471f0a51-c024-5a09-af9b-5903b795d55d' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ccf5f99f-9b4b-524c-9fa2-3347d39b500f','Source-language calque','A translation procedure, in Vinay and Darbelnet''s taxonomy, in which a source-language expression or structure is transferred into the target text by translating its component elements literally, one by one, preserving the source construction. In dubbing it often surfaces as an unintended interference that makes a line sound foreign.','A calque copies a phrase word for word from the first language. It can sound odd or wrong in the new language if the phrase does not really fit.','As a deliberate device it can introduce a needed new expression; as an accidental one it flags source-language interference the adapter should remove. Recognizing it helps writers keep the dub idiomatic.','A reviewer spots a dubbed idiom translated word-for-word from the source and replaces it with a natural target-language equivalent.','Dialogue Adaptation',ARRAY['Prefabricated orality','Dialogue adaptation','Dubbese','Naturalness','Speakability','Adaptation loss','Calque','Structural calque']::text[],ARRAY['Translating an idiom element by element so it becomes meaningless or unnatural in the target language.','Confusing a calque with borrowing, which keeps the source word unchanged rather than translating its parts.','Leaving accidental calques in the dub, producing the stilted quality known as dubbese.']::text[],ARRAY['A dubbed line reads as an English idiom translated literally, sounding wrong in the target language.','A reviewer replaces a calqued phrase with an idiomatic equivalent.','Deciding whether to keep a calque deliberately for a foreign or comic effect.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ccf5f99f-9b4b-524c-9fa2-3347d39b500f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Source-language calque'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ccf5f99f-9b4b-524c-9fa2-3347d39b500f','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ccf5f99f-9b4b-524c-9fa2-3347d39b500f' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3b7f4595-6b13-5d60-8ad7-cf385e6d7611','Speakability','The quality of a written line being easy and natural to say aloud and perform, so a voice actor can deliver it smoothly at the required pace, phrasing and breath without stumbling. In dubbing it is a core criterion of a good adapted script, distinct from mere semantic accuracy.','Speakability means a line is easy to say out loud. A voice actor should be able to speak it smoothly, at the right speed, without tripping.','It ensures adapted dialogue is written to be spoken, recited and recorded, not just read, so takes go smoothly and sound natural. Unspeakable lines waste booth time and break performance.','A dialogue writer reads each line aloud, reworking tongue-twisters, awkward consonant clusters and over-long clauses before the recording session.','Dialogue Adaptation',ARRAY['Prefabricated orality','Prosodic adaptation','Isochrony','Speech-rate compensation','Segment-duration matching','Dialogue adaptation']::text[],ARRAY['Judging a line only by meaning on the page and never testing whether it can be said aloud.','Writing dense consonant clusters or tongue-twisters that trip the actor in the booth.','Packing so many words into the duration that the line cannot be spoken at a natural pace.']::text[],ARRAY['Reading a dubbed line aloud in the studio and reworking it because it is hard to say.','Simplifying an awkward phrase before a recording session to keep takes clean.','Balancing a wordy but accurate line against one that performs smoothly.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3b7f4595-6b13-5d60-8ad7-cf385e6d7611' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Speakability'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3b7f4595-6b13-5d60-8ad7-cf385e6d7611','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3b7f4595-6b13-5d60-8ad7-cf385e6d7611' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c4b3f14a-db3f-52cf-857e-cfbb5cc20ccb','Speech-rate compensation','Adjusting a dubbed line — by condensing or expanding wording, or by modulating delivery tempo — to offset differences in how many syllables a language needs to express the same content, so the target speech still fits the source''s duration and rhythm. It addresses the fact that languages differ in syllable rate and information density.','Some languages need more words to say the same thing. Speech-rate compensation adjusts the line or its pace so it still fits the original timing.','It reconciles a target language''s natural length with the fixed on-screen timing, keeping isochrony without cramming or dragging. It exists because a faithful translation is often longer or shorter than the source.','An adapter condenses a language that runs long, or slightly slows delivery of one that runs short, so the line still matches the character''s mouth activity.','Sync & Timing',ARRAY['Isochrony','Segment-duration matching','Condensation','Speakability','Prosodic transfer','Segmentation mismatch']::text[],ARRAY['Forcing too many syllables into the time, making the actor rush and lose clarity.','Over-condensing so meaning or tone is stripped away just to hit the timing.','Relying on tempo changes alone when the wording itself needs to be reworked.']::text[],ARRAY['Condensing a target language that expresses the same idea in more syllables than the source.','Slightly stretching delivery of a short line so it fills the on-screen duration.','Rewriting a dense line so a voice actor can speak it at a natural, clear pace.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c4b3f14a-db3f-52cf-857e-cfbb5cc20ccb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Speech-rate compensation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c4b3f14a-db3f-52cf-857e-cfbb5cc20ccb','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c4b3f14a-db3f-52cf-857e-cfbb5cc20ccb' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c5619d04-b4ab-52d5-a27a-7ad5b70f7197','Stress relocation','In dubbing adaptation, the deliberate shifting of prosodic stress from the word or syllable it falls on in the source utterance to a different position in the target-language line, so that emphasized syllables coincide with visible mouth movements, on-screen gestures, or the beats the actor stresses. It is a prosodic synchronization technique used when a literal rendering would place emphasis where the picture or timing does not support it.','Every spoken line has words we say with extra force. When a line is dubbed, those stressed words may not line up with the picture. Stress relocation moves the emphasis to a better word. This helps the new voice match the actor''s mouth and gestures.','It keeps the dubbed performance''s emphasis aligned with the actor''s visible articulation and body language, preserving natural rhythm and meaning when word order changes between languages.','A dialogue adaptor rewrites a line so the stressed word lands on a close-up mouth movement or a gesture, rather than leaving emphasis on a word the picture does not support.','Dialogue Adaptation',ARRAY['Isochrony','Prosody','Tonal contour matching','Kinesic synchrony','Lip sync','Dialogue adaptation']::text[],ARRAY['Keeping the source language''s stress pattern even when target word order has moved the key word.','Forcing emphasis onto a syllable that clashes with a visible gesture or mouth movement.','Relocating stress so far that the line''s focus or meaning changes.']::text[],ARRAY['Adapting a line so the emphasized word falls on an on-screen nod or point.','Rewriting a translated question so the stressed syllable matches a close-up.','Shifting emphasis in a dubbed line to keep natural target-language rhythm.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c5619d04-b4ab-52d5-a27a-7ad5b70f7197' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stress relocation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c5619d04-b4ab-52d5-a27a-7ad5b70f7197','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c5619d04-b4ab-52d5-a27a-7ad5b70f7197' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '898f014a-cd2b-51d9-9e27-5cf686ef8089','Structural calque','A calque in which the imported source expression carries over a grammatical pattern that is new to the target language, changing its sentence construction. This differs from a lexical calque, where only a fresh turn of phrase is introduced and the target language''s normal grammar is left intact. The lexical/structural split is drawn from Vinay and Darbelnet''s model of translation procedures.','A calque is a phrase copied from another language by translating it word for word. A structural calque goes further. It brings a new sentence pattern or word order into the target language, not just new words. Over time such copied structures can start to sound normal.','It names a translation procedure where borrowing a source expression literally imports a foreign grammatical pattern, helping adaptors recognize and, in dubbing, avoid unnatural target-language constructions.','A dubbing translator spots a structural calque when a rendered line mirrors source syntax that is odd or ungrammatical in the target language, and reworks it into a natural construction unless the calque is intended.','Dialogue Adaptation',ARRAY['Calque','Translationese','Literal translation','Borrowing','Dialogue adaptation']::text[],ARRAY['Confusing a structural calque with a lexical calque, which keeps the target language''s own structure.','Treating every calque as an error, when some become accepted target-language expressions.','Leaving an unintended structural calque in a dubbed line, producing awkward, foreign-sounding syntax.']::text[],ARRAY['Reviewing a translated script for constructions copied straight from the source grammar.','Deciding whether to keep or rework a borrowed expression in a dub.','Explaining why a dubbed line sounds foreign because its structure was calqued.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='898f014a-cd2b-51d9-9e27-5cf686ef8089' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Structural calque'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '898f014a-cd2b-51d9-9e27-5cf686ef8089','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='898f014a-cd2b-51d9-9e27-5cf686ef8089' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9c7f91bb-da9b-56ee-a292-eebfd9c9ade3','Syllabic expansion','An adaptation technique in dubbing whereby the target-language line is lengthened by adding syllables — through fuller wording, added particles, or longer synonyms — so its spoken duration matches a source utterance that is longer than a literal translation would produce. It is one of the strategies used to achieve isochrony.','Sometimes a translated line is shorter than the original the actor speaks. That leaves a gap where the mouth still moves. Syllabic expansion adds extra syllables or words to fill the time. This keeps the new voice matched to the actor''s mouth.','It lets an adaptor stretch a too-short translation to fill the original''s on-screen speaking time, maintaining isochrony without leaving the mouth moving in silence.','When a literal translation ends before the character''s lips stop moving, the adaptor pads the line with natural extra words or syllables so speech and picture end together.','Dialogue Adaptation',ARRAY['Isochrony','Temporal expansion','Time-slot occupancy','Lip sync','Dialogue adaptation']::text[],ARRAY['Padding a line with filler that sounds unnatural or changes the meaning.','Adding syllables without checking they fall on the right mouth movements.','Confusing syllabic expansion, which adds words, with time expansion of the audio itself.']::text[],ARRAY['Filling out a short translated line so it lasts as long as the original.','Adding a natural particle so a dubbed reply covers the actor''s full mouth movement.','Balancing a scene where the target language is more compact than the source.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9c7f91bb-da9b-56ee-a292-eebfd9c9ade3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Syllabic expansion'),'[^a-z0-9]','','g'));
