WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9c7f91bb-da9b-56ee-a292-eebfd9c9ade3' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '15aeee70-465d-5844-adf0-e42b3e85654d','Sync envelope','The bounded time window — defined by the start and end of a character''s on-screen speech and the pauses within it — inside which a dubbed line must begin, unfold, and finish to stay synchronized. The adapted utterance must fit within this envelope to satisfy isochrony and lip sync.','Think of each spoken line as having a start and stop time set by the actor''s mouth. That time window is the sync envelope. The dubbed line must begin and end inside it. If the new line spills past those edges, the sync breaks.','It gives adaptors and mixers a clear temporal boundary for each line, so the target-language dialogue stays locked to the picture rather than running long or short.','An adaptor writes and times each line to open and close within the character''s speech window, and a mixer nudges or time-adjusts a take that overruns the envelope.','Synchronization',ARRAY['Isochrony','Sync latitude','Time-slot occupancy','Lip sync','Temporal compression']::text[],ARRAY['Writing a line that starts on time but runs past the end of the mouth movement.','Ignoring internal pauses that split the envelope into separate segments.','Treating the envelope as flexible when a close-up demands exact boundaries.']::text[],ARRAY['Timing a translated line to fit exactly between the first and last mouth movements.','Checking that a dubbed reply does not overrun its speech window.','Splitting a long line around an on-screen pause inside the envelope.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='15aeee70-465d-5844-adf0-e42b3e85654d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync envelope'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '15aeee70-465d-5844-adf0-e42b3e85654d','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='15aeee70-465d-5844-adf0-e42b3e85654d' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5a757656-8633-5dc4-9e3d-4ec83f70ebe4','Sync latitude','The permissible margin of deviation from perfect synchronization — in timing or lip articulation — that still reads as acceptable to viewers, giving the adaptor and mixer freedom in how closely a dubbed line must match the original. Off-screen lines, long shots, and non-labial articulation allow greater latitude than lip-visible close-ups, and broadcast standards define tolerance limits for sound-to-picture timing.','Sync does not have to be perfect to look right. There is a small margin where the mouth and voice can drift and viewers still accept it. That margin is the sync latitude. Close-ups allow very little; far shots and off-screen lines allow much more.','It tells the team how much timing or lip mismatch they can tolerate on a given shot, so effort goes to the shots that need tightening and freedom is used where a mismatch will not show.','An adaptor takes more wording freedom on off-screen or wide shots and tightens lines only where a close-up leaves little latitude for error.','Synchronization',ARRAY['Sync envelope','Isochrony','Lip sync','Kinesic synchrony','Phonetic synchrony']::text[],ARRAY['Assuming every line needs frame-perfect sync, wasting effort where latitude is wide.','Using loose sync on a tight close-up, where the mismatch is obvious.','Confusing broadcast sound-to-picture timing tolerance with the creative sync freedom of adaptation.']::text[],ARRAY['Judging how much wording freedom an off-screen line allows.','Tightening a close-up where there is little room for sync error.','Deciding acceptable drift when a line cannot be shortened any further.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5a757656-8633-5dc4-9e3d-4ec83f70ebe4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync latitude'),'[^a-z0-9]','','g'));
