SELECT '5a757656-8633-5dc4-9e3d-4ec83f70ebe4','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5a757656-8633-5dc4-9e3d-4ec83f70ebe4' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '521e1dd5-a36a-57b9-94e7-32a639f9e54b','Sync pass','A dedicated review-and-revision pass through an adapted or recorded dub in which the sole focus is synchronization — checking and correcting timing (isochrony), lip and phonetic match, and gesture alignment — as distinct from passes concerned with translation accuracy or performance.','Making a dub takes several rounds of checking. A sync pass is the round that looks only at timing and lip matching. The reviewer watches each line against the picture. They fix any line that starts late, runs long, or misses the mouth.','It isolates synchronization as its own quality-control step, so timing and lip-match problems are caught and fixed systematically rather than missed among other concerns.','After translation and recording, an adaptor or supervisor does a sync pass, marking lines that drift off the mouth or overrun their window for retiming or re-recording.','Synchronization',ARRAY['Isochrony','Lip sync','Sync envelope','Dialogue adaptation','Automated dialogue replacement']::text[],ARRAY['Skipping a dedicated sync pass and hoping timing issues surface during the mix.','Reworking translation wording during the sync pass and losing focus on timing.','Passing lines that sound right in the booth but drift when checked against picture.']::text[],ARRAY['Reviewing a recorded dub line by line only for timing and lip match.','Marking overrunning lines for retiming before the final mix.','Doing a sync pass on a close-up-heavy scene after recording.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='521e1dd5-a36a-57b9-94e7-32a639f9e54b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync pass'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '521e1dd5-a36a-57b9-94e7-32a639f9e54b','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='521e1dd5-a36a-57b9-94e7-32a639f9e54b' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ea429b7f-8d79-5fa6-8050-6496891a2c8a','Temporal accommodation','The general process of adjusting the timing of a target-language utterance — its onset, pacing, internal pauses, and overall duration — so it accommodates the temporal constraints of the on-screen original, covering both shortening and lengthening as required for isochrony.','The dubbed voice must fit the timing the actor set on screen. Temporal accommodation means shaping the new line''s pace and length to fit that timing. The line may need to speed up, slow down, or pause. The goal is speech that starts and ends with the picture.','It is the umbrella goal behind isochrony: making the translated delivery share the original''s temporal shape so voice and picture stay together.','An adaptor and voice actor adjust pacing, breaths, and pauses so each line tracks the original''s rhythm, neither rushing ahead of nor lagging the picture.','Synchronization',ARRAY['Isochrony','Temporal compression','Temporal expansion','Sync envelope','Time-slot occupancy']::text[],ARRAY['Matching only the start of a line and ignoring how its pacing drifts by the end.','Rushing the delivery to fit instead of reshaping the wording.','Ignoring internal pauses that must line up with the picture.']::text[],ARRAY['Reshaping a dubbed line''s pacing to fit the actor''s rhythm.','Adding a pause so a translated line tracks an on-screen beat.','Adjusting delivery speed so speech ends with the mouth movement.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ea429b7f-8d79-5fa6-8050-6496891a2c8a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Temporal accommodation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ea429b7f-8d79-5fa6-8050-6496891a2c8a','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ea429b7f-8d79-5fa6-8050-6496891a2c8a' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd5096c90-a550-5719-a1d5-9b8e0f08aebb','Temporal compression','The shortening of a target-language utterance''s duration to fit within a shorter original speech window — achieved by condensing the wording, tightening delivery, or applying audio time-compression, a time-stretching process that reduces length without changing pitch. It is used to satisfy isochrony when a literal translation would run longer than the original.','Sometimes a translated line takes longer to say than the original. To fit, its time must be cut down. Temporal compression shortens the line. The team may trim words, speak faster, or shrink the audio''s length while keeping the same pitch.','It brings an over-long target utterance back inside the original''s timing, so the dubbed line does not run past the character''s mouth movement.','An adaptor condenses wordy lines, and a mixer may apply time-compression to a recorded take that still runs slightly long, keeping the pitch natural.','Synchronization',ARRAY['Isochrony','Temporal expansion','Temporal accommodation','Condensation','Sync envelope']::text[],ARRAY['Cutting so many words that meaning or nuance is lost.','Over-compressing the audio until the voice sounds unnatural or rushed.','Confusing audio time-compression with pitch-shifting, which changes the voice.']::text[],ARRAY['Trimming a wordy translation so it fits a short original line.','Time-compressing a recorded take that runs a few frames long.','Fitting a dense target language into a compact source utterance.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d5096c90-a550-5719-a1d5-9b8e0f08aebb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Temporal compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd5096c90-a550-5719-a1d5-9b8e0f08aebb','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d5096c90-a550-5719-a1d5-9b8e0f08aebb' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '90e90891-4a72-5303-8e0e-3983979f5999','Temporal expansion','The lengthening of a target-language utterance''s duration to fill a longer original speech window — achieved by fuller wording, added syllables, slower delivery, or audio time-expansion, a time-stretching process that increases length without changing pitch. It is the counterpart of temporal compression and serves isochrony when a literal translation would be too short.','Sometimes a translated line is shorter than the original the actor speaks. That leaves the mouth moving with no sound. Temporal expansion stretches the line to fill the time. The team may add words, slow the delivery, or lengthen the audio while keeping the pitch.','It fills the gap left when a target utterance is shorter than the original, so speech covers the full duration of the character''s mouth movement.','An adaptor adds natural wording, or the mixer time-expands a short take, so the dubbed line lasts as long as the on-screen speech.','Synchronization',ARRAY['Isochrony','Temporal compression','Syllabic expansion','Temporal accommodation','Sync envelope']::text[],ARRAY['Padding a line with filler that sounds unnatural.','Over-stretching the audio until the voice sounds slurred or slow.','Leaving the mouth moving in silence rather than expanding the line.']::text[],ARRAY['Lengthening a short translation to cover a long original line.','Time-expanding a recorded take that ends too early.','Filling a mouth movement that outlasts the translated words.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='90e90891-4a72-5303-8e0e-3983979f5999' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Temporal expansion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
