INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '65e7a855-c0d5-5e5c-b45a-e398d79149c1','Time-slot occupancy','The degree to which a dubbed line fills the available on-screen speech slot — the proportion of the source utterance''s duration actually occupied by target-language speech rather than left as silence or pause. Correct occupancy means the translated dialogue neither underfills, leaving the mouth moving silently, nor overfills, spilling past the slot.','Each spoken moment gives the dub a fixed slot of time. Time-slot occupancy is how much of that slot the new speech fills. If it fills too little, the mouth moves in silence. If it fills too much, the line runs over. The aim is a good match.','It gives adaptors a way to judge whether a line''s length matches its time slot, guiding decisions to expand or compress the wording for isochrony.','An adaptor checks that speech fills each slot from the first to the last mouth movement, adding or trimming words where occupancy is too low or too high.','Synchronization',ARRAY['Isochrony','Sync envelope','Temporal expansion','Temporal compression','Syllabic expansion']::text[],ARRAY['Underfilling a slot so the character''s lips keep moving with no sound.','Overfilling a slot so speech continues after the mouth stops.','Counting only total length and ignoring pauses inside the slot.']::text[],ARRAY['Checking that a dubbed line fills its speech slot end to end.','Spotting a line that leaves silent mouth movement at the tail.','Deciding to expand a line whose occupancy is too low.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='65e7a855-c0d5-5e5c-b45a-e398d79149c1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Time-slot occupancy'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '65e7a855-c0d5-5e5c-b45a-e398d79149c1','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='65e7a855-c0d5-5e5c-b45a-e398d79149c1' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ce78d26d-c53a-572b-aa4f-f0edeb409b70','Tonal contour matching','Shaping the intonation (pitch) contour of the dubbed delivery so it follows the rising and falling pitch pattern of the original performance, a form of prosodic synchronization. It preserves the melodic shape that signals emotion, emphasis, and sentence type, such as questions versus statements, across languages.','When we speak, our pitch rises and falls in a pattern. That pattern is the tonal contour. Tonal contour matching means the dubbed voice follows the same rise and fall as the original. This keeps the feeling and the emphasis, and it keeps a question still sounding like a question.','It carries the original''s emotional and grammatical melody into the dub, so the target-language performance feels like the same delivery rather than a flat or differently shaped reading.','A voice director guides the actor to rise and fall in pitch like the original — especially on questions, emphasis, and emotional peaks — checking takes against the source.','Synchronization',ARRAY['Prosody','Stress relocation','Isochrony','Kinesic synchrony','Intonation']::text[],ARRAY['Copying words and timing but delivering them with flat or wrong intonation.','Turning a question''s rising pitch into a statement, changing the meaning.','Matching pitch so literally that the target language sounds unnatural.']::text[],ARRAY['Directing an actor to follow the original''s rising pitch on a question.','Matching an emotional pitch peak in a dubbed line.','Fixing a take whose intonation does not follow the original''s melody.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ce78d26d-c53a-572b-aa4f-f0edeb409b70' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tonal contour matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ce78d26d-c53a-572b-aa4f-f0edeb409b70','39203cec-660c-4a27-972c-21f7a63623b9',true
