INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '566b4f16-49fc-5a05-871d-017f791eeb8e','Translationese','The set of features that make translated language recognizably different from spontaneously produced target-language text — such as source-language interference, unusual collocations, over-explicitness, and unnatural phrasing. In dubbing it describes dialogue that sounds translated rather than like natural target-language speech; the term is often used pejoratively but is also studied neutrally in corpus translation studies.','Translationese is language that sounds translated, not natural. It still carries bits of the original language, like odd word choices or stiff phrasing. In a dub, it makes characters sound stilted. They seem to read a script, not really talk.','Naming it helps translators and adaptors recognize and remove source-language traces, so dubbed dialogue reads as authentic target-language speech.','A dubbing adaptor edits out translationese — stiff calques, foreign word order, over-literal idioms — rewriting lines the way a native speaker would actually say them.','Dialogue Adaptation',ARRAY['Structural calque','Calque','Literal translation','Dialogue adaptation','Domestication']::text[],ARRAY['Leaving over-literal, source-flavored phrasing in the dub because it is technically accurate.','Assuming translationese is only about vocabulary, not word order and rhythm.','Confusing an intentional foreignizing choice with accidental translationese.']::text[],ARRAY['Editing a dubbed script to remove stiff, translated-sounding lines.','Spotting source-language word order that survived into the target dialogue.','Rewriting an over-literal idiom so it sounds like natural speech.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='566b4f16-49fc-5a05-871d-017f791eeb8e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Translationese'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '566b4f16-49fc-5a05-871d-017f791eeb8e','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='566b4f16-49fc-5a05-871d-017f791eeb8e' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bd730895-220e-5e4c-8632-d950092292b3','Undipped M&E','A Music & Effects (M&E) deliverable in which the music and effects are carried at their full, continuous level and are not attenuated (dipped or ducked) beneath where the original dialogue sat. Because levels are not pulled down under speech, a localization team can lay in target-language dialogue of any length without exposing audible dips that reveal where the source dialogue used to be.','M&E stands for music and effects. It is the film sound with the voices taken out. Undipped means the music and effects stay at a full, steady level. They are not turned down where the original talking was. This lets a dubbing team drop in new voices of any length.','It gives the dubbing mixer a clean, evenly leveled bed so foreign dialogue can be placed freely, without ducking artifacts betraying the timing of the original speech.','A re-recording mixer prepares the M&E from undipped stems so music and effects run at full level throughout, then delivers it alongside the dipped mix for the localization houses.','Deliverables',ARRAY['Music and effects track','Fully-filled M&E','Optional dialogue','Stem','Dialogue editing','Vocal-bearing ambience']::text[],ARRAY['Delivering M&E built from the dipped mix, so the music audibly drops where the original dialogue was and the dub reveals those gaps.','Modifying music or effects levels for the M&E beyond what a proper fill requires, changing the creative balance.','Confusing an undipped M&E with a fully-filled M&E; one is about level, the other about replacing effects that sat under dialogue.']::text[],ARRAY['Preparing music and effects for international versioning so any language length fits cleanly.','Delivering both dipped and undipped stems to meet a distributor''s M&E spec.','Fixing a dub where music dips under the missing original dialogue give the fill away.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bd730895-220e-5e4c-8632-d950092292b3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Undipped M&E'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
