INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cb9e6380-6568-5ec4-bf39-1ef1426bcc38','Utterance segmentation','The division of continuous source speech into discrete utterance units — bounded stretches of speech typically delimited by pauses, breaths, or turn boundaries — so each unit can be transcribed, timed, translated, and adapted as a self-contained line for dubbing.','An utterance is a single stretch of speech, like one spoken line. Utterance segmentation means cutting the dialogue into these units. Each unit can then be timed, translated, and recorded on its own.','It breaks a continuous soundtrack into workable, timed pieces so translators and adapters can match each target line to the duration and screen action of its source utterance.','In dubbing script prep, an editor or automatic-dubbing system marks utterance boundaries and their time codes, producing the line-by-line units the adapter writes against.','Dialogue Adaptation',ARRAY['Isochrony','Utterance-duration matching','Dialogue adaptation','Take','Time code','Lip sync']::text[],ARRAY['Segmenting on grammar alone and ignoring the pauses and breaths that actually bound spoken utterances.','Cutting units so long they cannot be timed or recorded cleanly against the picture.','Splitting a single continuous utterance across two units, breaking its natural timing.']::text[],ARRAY['Marking utterance boundaries and time codes when preparing a dubbing script.','Feeding segmented utterances into an automatic-dubbing pipeline for timing and translation.','Breaking a long monologue into recordable units for the voice actor.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cb9e6380-6568-5ec4-bf39-1ef1426bcc38' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Utterance segmentation'),'[^a-z0-9]','','g'));
