INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4bc77e7e-aa8d-561c-a46a-f24244079767','Utterance-duration matching','The practice, a component of isochrony, of writing and timing each target-language utterance so its spoken duration matches that of the corresponding source utterance, so the dubbed line begins and ends with the character''s on-screen speech and fills the same interval between pauses.','This means making the new line last as long as the old one. If a character speaks for two seconds, the dubbed line should too. It helps the new voice fit the picture.','It keeps the dub in time with the picture, so speech starts when the mouth starts and stops when it stops, preserving the rhythm of the original performance.','An adapter lengthens or shortens the translated line — adding or cutting words, or changing phrasing — until it can be spoken in the same time the source line occupies.','Synchronization',ARRAY['Isochrony','Utterance segmentation','Lip sync','Kinesic synchrony','Dialogue adaptation','Time code']::text[],ARRAY['Translating for meaning only, producing a line too long or too short to fit the source timing.','Matching total length but ignoring internal pauses, so the dub drifts within the utterance.','Speeding up or slowing the delivery unnaturally to force a badly timed line to fit.']::text[],ARRAY['Trimming a wordy translation so it fits the seconds the character is speaking.','Adding syllables to a short target line so it does not end before the mouth stops.','Aligning pauses in the dubbed line with the pauses in the original delivery.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4bc77e7e-aa8d-561c-a46a-f24244079767' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Utterance-duration matching'),'[^a-z0-9]','','g'));
