INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b34e6498-65b0-544e-a71f-0c5a5d0362d5','Viseme','The visual counterpart of a phoneme: the characteristic shape or pose of the lips, jaw, and visible articulators produced when a speech sound is made. The mapping is many-to-one — several phonemes that look alike on the mouth (for example the bilabials /p/, /b/, and /m/) belong to a single viseme — which is why lip-readers cannot always tell them apart.','A viseme is the mouth shape you see for a speech sound. Many sounds share one shape. For example, p, b, and m all look the same on the lips. Visemes are what a lip-reader watches.','Visemes give dubbing and animation a unit for describing what the mouth looks like, so target dialogue and animated faces can be matched to visible articulation rather than only to sound.','An adapter or animator identifies the visemes visible on screen — especially closed-lip and rounded shapes — and chooses words or poses that reproduce them.','Synchronization',ARRAY['Phoneme','Lip sync','Phonetic synchrony','Bilabial','Viseme matching','Visual prosody']::text[],ARRAY['Treating the phoneme-to-viseme mapping as one-to-one, when many distinct sounds share one mouth shape.','Assuming every sound is visible, when tongue-only consonants leave the lips largely unconstrained.','Ignoring that context and co-articulation change a sound''s viseme from one word to the next.']::text[],ARRAY['Choosing a translated word so its visemes match the lips in a close-up.','Building an animated character''s mouth library from a viseme set.','Scoring a dub by comparing the visemes of the new audio against the on-screen mouth.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b34e6498-65b0-544e-a71f-0c5a5d0362d5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Viseme'),'[^a-z0-9]','','g'));
