INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c1ba4093-f24f-56e8-ac40-658b33701fe9','Viseme collision','A lip-sync conflict at a visually salient articulation, where the viseme the picture shows — such as a full bilabial lip closure or a strongly rounded vowel — cannot be reconciled with the viseme produced by the target-language dialogue placed at that moment, yielding a perceptible mismatch between the mouth and the dubbed sound.','A viseme collision is a clash between the mouth on screen and the new words. The picture may show lips closing for a p or b. If the dubbed word has no such sound there, viewers notice the mismatch.','Naming the clash helps adapters spot the points where lip sync will break if left unaddressed, so they can rework the line before it reaches the booth.','When a translated line puts an open sound where the image shows lips closing, the adapter rewrites or reorders words to remove the collision, or accepts it if the shot is not a close-up.','Synchronization',ARRAY['Viseme','Viseme substitution','Phonetic synchrony','Bilabial','Viseme tolerance','Lip sync']::text[],ARRAY['Leaving an open-mouthed word where the picture clearly shows the lips closing on a bilabial.','Fixing a collision in one word but pushing the clash onto the next salient viseme.','Treating every viseme as equally strict, when only close-up salient shapes truly collide.']::text[],ARRAY['Rewriting a line where the dub lacks a lip closure the close-up demands.','Deciding a viseme clash is acceptable because the shot is wide or the face is turned.','Auditing an adapted script for salient mismatches before recording.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c1ba4093-f24f-56e8-ac40-658b33701fe9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Viseme collision'),'[^a-z0-9]','','g'));
