SELECT 'c1ba4093-f24f-56e8-ac40-658b33701fe9','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c1ba4093-f24f-56e8-ac40-658b33701fe9' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ea2a4d2b-e43d-5fe8-8e71-9438aa972930','Viseme matching','The lip-sync practice of choosing and arranging target-language dialogue so its visemes align with the visible mouth shapes of the on-screen actor, prioritizing the most salient articulations — bilabial and labiodental closures and rounded vowels — especially in close-up shots.','Viseme matching means picking words whose mouth shapes fit the picture. The new voice should look like it belongs to the moving lips. It matters most in close-up shots.','It delivers phonetic synchrony, keeping the dubbed voice believable by making the sounds the audience hears agree with the mouth shapes they see.','The adapter reads the source for salient visemes and writes target lines that reproduce them at the same moments, testing the fit against the picture.','Synchronization',ARRAY['Viseme','Phonetic synchrony','Viseme substitution','Bilabial','Visemic synchrony','Lip sync']::text[],ARRAY['Chasing an exact match on every sound, when only salient visemes in close-ups need it.','Matching visemes so rigidly that the target line becomes stilted or unnatural.','Overlooking rounded vowels while focusing only on lip closures.']::text[],ARRAY['Writing a close-up line so its lip closures land on the on-screen closures.','Selecting among synonyms for the one whose mouth shapes fit best.','Checking an adapted line against the picture for viseme fit.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ea2a4d2b-e43d-5fe8-8e71-9438aa972930' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Viseme matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ea2a4d2b-e43d-5fe8-8e71-9438aa972930','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ea2a4d2b-e43d-5fe8-8e71-9438aa972930' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '564769d7-87dd-563a-8d5f-fe14709a1379','Viseme substitution','An adaptation strategy in which a translated word or sound that would break lip sync is replaced by an alternative that preserves the meaning while producing a viseme matching the visible mouth shape — for example choosing a synonym containing a bilabial to align with an on-screen lip closure.','Sometimes a translated word does not fit the lips on screen. Viseme substitution means swapping it for another word that does. The writer keeps the meaning but changes the sounds to match the mouth.','It lets the adapter honor lip sync without losing the sense of the line, by trading one wording for another whose mouth shapes fit the picture.','Facing a visible bilabial the literal translation misses, the adapter substitutes a near-synonym or rephrasing that puts a matching closed-lip sound at that instant.','Dialogue Adaptation',ARRAY['Viseme','Viseme matching','Phonetic synchrony','Bilabial','Dialogue adaptation','Viseme collision']::text[],ARRAY['Substituting a word that fits the lips but drifts from the original meaning or tone.','Forcing a substitution in a wide shot where the viseme was never visible.','Picking an awkward synonym that hits the viseme but reads unnaturally aloud.']::text[],ARRAY['Swapping a synonym so a bilabial lands on a visible lip closure.','Rephrasing a line to place a rounded vowel where the picture shows rounded lips.','Resolving a viseme collision by substituting a matching word.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='564769d7-87dd-563a-8d5f-fe14709a1379' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Viseme substitution'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '564769d7-87dd-563a-8d5f-fe14709a1379','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='564769d7-87dd-563a-8d5f-fe14709a1379' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7e7ee802-97d1-587c-ab9b-38623f429632','Viseme tolerance','The degree of mismatch between the on-screen viseme and the dubbed sound that a viewer will accept before lip sync reads as wrong. Tolerance is very low for salient, unambiguous shapes such as bilabial closures and rounded vowels, and much higher for tongue-only or hidden articulations that leave the lips largely unconstrained, and it rises as shots move away from close-up.','Some mouth-shape mismatches are easy to spot; others are not. Viseme tolerance is how much mismatch viewers will accept. Closed-lip sounds like p and b allow almost none. Hidden tongue sounds allow much more. Viewers also accept more mismatch in wide shots than in close-ups.','It tells the adapter where lip sync must be exact and where there is freedom, so effort is spent on the shapes an audience would actually notice.','An adapter matches salient visemes tightly and relaxes on hidden ones, and eases matching further as the shot widens or the face turns from camera.','Synchronization',ARRAY['Viseme','Phonetic synchrony','Bilabial','Viseme collision','Visemic compatibility','Lip sync']::text[],ARRAY['Spending effort matching tongue-only sounds the audience cannot see anyway.','Assuming a wide shot allows the same looseness on a visible lip closure as a close-up.','Treating tolerance as fixed, when it changes with sound, shot size, and face angle.']::text[],ARRAY['Deciding a hidden consonant need not match because the audience cannot see it.','Insisting on an exact match for a bilabial held in extreme close-up.','Relaxing viseme constraints on a line delivered off-camera or in a wide shot.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7e7ee802-97d1-587c-ab9b-38623f429632' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Viseme tolerance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7e7ee802-97d1-587c-ab9b-38623f429632','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7e7ee802-97d1-587c-ab9b-38623f429632' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '52d3ab2f-7ec6-5d3a-928d-22ef0c017e93','Visemic compatibility','The condition in which a target-language phoneme shares, or is visually confusable with, the viseme of the sound visible on screen at the same moment, so that substituting it does not break lip sync. Because the phoneme-to-viseme mapping is many-to-one, sounds within the same viseme class are compatible even when they differ acoustically.','Two sounds are visemically compatible when they make the same mouth shape. A compatible word will match the lips on screen. The writer looks for words that share the shape the picture shows.','It defines which sounds an adapter may freely swap in without disturbing lip sync, exploiting the fact that many different sounds look identical on the mouth.','An adapter selects target words built from sounds in the same viseme class as the visible articulation, so the line matches the mouth without an exact phoneme match.','Synchronization',ARRAY['Viseme','Phoneme','Viseme substitution','Bilabial','Viseme tolerance','Phonetic synchrony']::text[],ARRAY['Assuming only the identical sound fits, when any sound in the same viseme class is compatible.','Treating acoustically similar sounds as visually compatible when their mouth shapes differ.','Ignoring co-articulation, which can shift a sound''s viseme between words.']::text[],ARRAY['Choosing a compatible consonant from the same viseme class as the visible closure.','Judging whether a target sound will pass as the on-screen mouth shape.','Building a shortlist of visemically compatible words for a tricky close-up line.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='52d3ab2f-7ec6-5d3a-928d-22ef0c017e93' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Visemic compatibility'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '52d3ab2f-7ec6-5d3a-928d-22ef0c017e93','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='52d3ab2f-7ec6-5d3a-928d-22ef0c017e93' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd405a5cf-d41f-5eee-8af6-aef59dd80bea','Visemic synchrony','Synchrony achieved at the level of visemes — the alignment of the dubbed dialogue''s visible mouth shapes with those of the on-screen actor. It is the operational core of phonetic (lip) synchrony, concentrating on the salient articulations, chiefly bilabial and labiodental closures and rounded vowels, that the audience can actually see.','Visemic synchrony means the dubbed sounds match the mouth shapes on screen. The lips and the new voice seem to agree. It matters most for closed-lip sounds and rounded vowels.','It is what makes a dub look convincing in close-up, tying the new voice to the visible articulation so the mouth and sound do not contradict each other.','The adapter and dubbing director check that salient visemes in the target line fall on the same frames as the source articulations, adjusting wording where they do not.','Synchronization',ARRAY['Phonetic synchrony','Viseme','Viseme matching','Isochrony','Kinesic synchrony','Lip sync']::text[],ARRAY['Confusing visemic synchrony with isochrony; one matches mouth shapes, the other matches duration.','Chasing viseme alignment in shots where the mouth is not clearly visible.','Matching lip shapes but neglecting the line''s overall timing and rhythm.']::text[],ARRAY['Aligning the dub''s lip closures with the actor''s on a close-up.','Reviewing a take for visible mouth-shape agreement before approving it.','Balancing viseme fit against natural delivery during recording.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d405a5cf-d41f-5eee-8af6-aef59dd80bea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Visemic synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd405a5cf-d41f-5eee-8af6-aef59dd80bea','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d405a5cf-d41f-5eee-8af6-aef59dd80bea' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2e29b9b8-2cb7-53ac-8474-ea1a05c14b13','Visual prosody','The visible facial and head movements — chiefly head motion and eyebrow raises — that accompany and correlate with the acoustic prosody of speech, such as pitch, stress, and intonation. Research shows a large share of a talker''s pitch variation co-varies with head motion, and these movements help signal emphasis, prominence, and question-versus-statement contrasts.','Prosody is the tune of speech, like stress and rising or falling pitch. Visual prosody is how the face and head show it. People raise their eyebrows or nod on stressed words. These moves must fit the new voice too.','It carries emphasis and sentence melody visually, so in dubbing the target delivery must place its stresses where the original''s head and brow movements already fall on screen.','A dubbing director coaches the actor to stress the words the on-screen head nods and eyebrow raises land on, so the new voice agrees with the visible prosody.','Synchronization',ARRAY['Kinesic synchrony','Prosody','Isochrony','Viseme','Dialogue adaptation','Lip sync']::text[],ARRAY['Placing the dubbed stress on a different word than the one the head and brows emphasize.','Treating visual prosody as only lip movement, when head and eyebrow motion carry it.','Ignoring an on-screen eyebrow raise that marks a question or emphasis in the target line.']::text[],ARRAY['Coaching an actor to stress the word the character''s eyebrow raise falls on.','Adapting a line so its emphasis matches the visible head nods.','Checking that a question''s rising delivery agrees with the on-screen brow movement.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2e29b9b8-2cb7-53ac-8474-ea1a05c14b13' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Visual prosody'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2e29b9b8-2cb7-53ac-8474-ea1a05c14b13','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2e29b9b8-2cb7-53ac-8474-ea1a05c14b13' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ece0e274-8c13-592f-aa34-6d573d1e09dc','Vocal contamination','The presence of unwanted voice or dialogue content in an audio element that is required to be speech-free — most often residual source-language dialogue, vocalizations, or intelligible walla left in the Music & Effects or effects stems. If not removed, this contamination surfaces beneath the localized mix, exposing source-language speech in the dubbed version.','The music and effects track should have no talking in it. Vocal contamination is leftover voice that stays in it by mistake. If it is not removed, the old language can be heard under the new dub.','Flagging vocal contamination protects the integrity of dialogue-free deliverables, ensuring no source-language voice survives to conflict with the target-language dialogue.','During M&E preparation and quality control, an editor listens for stray voice or intelligible crowd lines in the effects and removes or re-covers them before delivery.','Localization Prep',ARRAY['Music and effects track','Vocal-bearing ambience','Undipped M&E','Optional dialogue','Walla','Dialogue editing']::text[],ARRAY['Leaving intelligible crowd or background lines in the M&E, so source-language words remain in the dub.','Assuming a rough dialogue mute is enough, when residual voice still bleeds through under effects.','Missing off-mic or overlapping voice captured in production effects during quality control.']::text[],ARRAY['Quality-checking an M&E and finding leftover source dialogue under a music cue.','Removing an intelligible background line that contaminates an otherwise clean effects stem.','Re-covering a scene where production effects carry unwanted voice.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ece0e274-8c13-592f-aa34-6d573d1e09dc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal contamination'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
