INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9da7029-a0d4-5342-b95c-d2b35af5174a','Vowel anchor','A prominent vowel — typically an open or stressed one that produces a large, clearly visible mouth opening — used as a fixed reference point for aligning a dubbed or animated line to the picture, because such vowels are the most salient and stable articulations to synchronize against.','Open vowels, like ah and oh, make big, clear mouth shapes. A vowel anchor is one of these used as a sync point. The writer lines the new line up so its open vowels land on the same spot.','It gives the adapter or animator a dependable landmark for timing and lip sync, since open, stressed vowels are easy to see and hard to fake if misaligned.','An adapter positions the target line so its open, stressed vowels fall on the frames where the on-screen mouth opens widest, then fits the surrounding consonants around them.','Synchronization',ARRAY['Viseme','Phonetic synchrony','Isochrony','Lip sync','Visual prosody','Kinesic synchrony']::text[],ARRAY['Anchoring on an unstressed or closed vowel that gives no clear mouth opening to align to.','Fitting consonants first and letting the open vowels drift off their on-screen openings.','Ignoring the anchor vowel''s stress, so the dubbed emphasis lands on the wrong syllable.']::text[],ARRAY['Aligning a line so its stressed ''ah'' lands on the character''s widest mouth opening.','Using an open vowel as the sync landmark for an animated mouth pose.','Building a target line''s rhythm around its open, stressed vowels.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9da7029-a0d4-5342-b95c-d2b35af5174a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vowel anchor'),'[^a-z0-9]','','g'));
