INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c72c1d76-0d18-5989-970d-bdd6618ce726','Added value','In Michel Chion''s audiovisual theory, the way a sound layered onto an image shapes how that image is understood and felt, while viewers instinctively credit the resulting meaning or emotion to the picture rather than to the sound. The effect lets sound guide a scene''s reading of time, space, and feeling without drawing attention to itself.','Added value is the meaning that sound gives to a picture. The sound changes how we see the shot. But we think the feeling came from the picture, not the sound. Music under a face can make it look sad on its own.','It names how sound and image work together so sound enriches the image''s meaning and feeling while staying perceptually hidden, explaining why a scene''s impact often comes from the soundtrack rather than the picture alone.','A composer or sound editor uses added value by scoring or layering sound so a neutral shot reads as tense, tender, or ominous, knowing the audience will credit the effect to the image.','Audiovisual Theory',ARRAY['Anempathetic music','Audiovisual counterpoint','Audiovisual dissonance','Synchresis','Empathetic music','Diegetic sound']::text[],ARRAY['Assuming the emotional impact of a scene comes from the picture, when the soundtrack is doing much of the work.','Treating added value as mere background, rather than as sound actively shaping the image''s meaning.','Confusing added value with simple redundancy; the point is that sound adds information the image did not carry alone.']::text[],ARRAY['Adding music to a neutral close-up so the character reads as grieving.','Analyzing why a silent shot feels different once ambient sound is laid under it.','Deciding how a cue will color a scene the picture leaves ambiguous.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c72c1d76-0d18-5989-970d-bdd6618ce726' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Added value'),'[^a-z0-9]','','g'));
