INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '48679b82-9e05-5162-b4db-a20a9d4fc8b8','Agitato','An Italian musical direction meaning ''agitated'' or ''restless'', calling for an excited, hurried, and turbulent manner of performance. It functions as an expression mark, used alone or combined with a tempo term (for example Allegro agitato), and typically implies driving, nervous motion rather than a fixed metronome value.','Agitato is an Italian word meaning ''agitated''. It tells players to sound restless and excited. The music feels hurried and tense. Composers often add it to a tempo mark, like Allegro agitato.','It signals the performer to convey unrest and urgency, giving the composer shorthand for a driving, anxious character that suits tense or dramatic moments on screen.','A film composer marks a cue Agitato so the orchestra plays with nervous, propulsive energy under a chase or a scene of rising panic.','Tempo & Expression',ARRAY['Andante misterioso','Tempo marking','Expression marking','Con moto','Underscore']::text[],ARRAY['Reading agitato as a precise tempo, when it is chiefly an expressive direction for an agitated character.','Playing merely faster without the nervous, unsettled quality the mark asks for.','Ignoring it when it modifies a tempo word, losing the intended restlessness.']::text[],ARRAY['Scoring a chase sequence with an Allegro agitato cue.','Directing an ensemble to add tension to a passage marked agitato.','Choosing agitato phrasing to underscore a character''s mounting panic.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='48679b82-9e05-5162-b4db-a20a9d4fc8b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Agitato'),'[^a-z0-9]','','g'));
