SELECT '48679b82-9e05-5162-b4db-a20a9d4fc8b8','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='48679b82-9e05-5162-b4db-a20a9d4fc8b8' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '23633c4e-5d1f-5f17-9961-acd9f60727ad','Alternate cue','A different version of a film music cue, written or edited as an option alongside the primary cue for the same scene. Alternates may vary the mood, instrumentation, length, or intensity, letting the director, music editor, or filmmakers choose the version that best fits the picture in the final mix.','A cue is a piece of music written for a scene. An alternate cue is a second version of it. It might be softer, shorter, or use different instruments. The team picks the one that works best.','It gives the filmmakers choices without a new writing session, so a scene can be re-scored in tone or length late in post without recalling the composer.','A composer delivers an alternate cue, such as a quieter no-drums version, so the music editor can swap it in if the director finds the original too heavy.','Scoring Workflow',ARRAY['Button alternate','Cue','Music editor','Spotting session','Bookend scoring','Stem']::text[],ARRAY['Delivering an alternate that is not conformed to the same timings, so it will not drop cleanly into the scene.','Treating an alternate as a rough draft rather than a finished, mixable option.','Failing to label alternates clearly, so the wrong version is cut into the picture.']::text[],ARRAY['Providing a softer alternate in case the director wants less intensity.','Cutting an alternate cue into a scene during a temp or final mix.','Offering a shorter alternate to fit a re-edited scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='23633c4e-5d1f-5f17-9961-acd9f60727ad' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Alternate cue'),'[^a-z0-9]','','g'));
