SELECT '23633c4e-5d1f-5f17-9961-acd9f60727ad','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='23633c4e-5d1f-5f17-9961-acd9f60727ad' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '00ca2628-a2e8-5cf1-85b6-4c79ab3f0c6b','Andante misterioso','A compound tempo-and-expression marking combining Andante, a moderate ''walking'' tempo, with misterioso, ''mysterious''. It directs a moderately paced performance played in a hushed, mysterious, suspenseful character.','Andante means a medium ''walking'' speed. Misterioso means ''mysterious''. Together they ask for music that moves steadily but sounds mysterious. It fits a quiet, suspenseful scene.','It tells performers to hold a steady moderate pace while shading the music with mystery and suspense, useful for underscoring tension without hurry.','A composer marks a cue Andante misterioso so a scene of cautious searching moves at a walking pace with an eerie, unresolved feel.','Tempo & Expression',ARRAY['Agitato','Tempo marking','Expression marking','Underscore','Con moto']::text[],ARRAY['Playing andante too slowly, closer to adagio, and losing the steady walking motion.','Ignoring the misterioso and delivering a plain, un-atmospheric reading.','Treating the two words as a fixed metronome mark rather than a tempo plus a mood.']::text[],ARRAY['Underscoring a character creeping through a dark house.','Setting a moderate, eerie pace for a mystery''s investigation scene.','Marking a cue so the orchestra plays steadily but with suspense.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='00ca2628-a2e8-5cf1-85b6-4c79ab3f0c6b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Andante misterioso'),'[^a-z0-9]','','g'));
