SELECT '00ca2628-a2e8-5cf1-85b6-4c79ab3f0c6b','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='00ca2628-a2e8-5cf1-85b6-4c79ab3f0c6b' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '514f66fa-1a28-5e69-b628-943625e6189a','Anempathetic music','Music or sound that continues without reacting to the on-screen drama, rolling forward in an even, detached, machine-like way as though unaware of the events it accompanies -- for example, cheerful dance music playing on through a violent or tragic moment. Coined by Michel Chion, it contrasts with empathetic music, which openly mirrors and expresses a scene''s emotion.','Anempathetic music ignores what is happening on screen. It keeps playing calmly through a sad or violent moment. The gap between the happy music and the awful scene can make the scene feel worse. Michel Chion named this idea.','By refusing to react to the drama, it can heighten emotion through contrast and suggest the world''s indifference, giving filmmakers an alternative to music that simply mirrors the mood.','A composer or music supervisor scores a brutal scene with breezy, upbeat music so its cold indifference intensifies the horror.','Audiovisual Theory',ARRAY['Added value','Empathetic music','Audiovisual dissonance','Audiovisual counterpoint','Diegetic sound','Source music']::text[],ARRAY['Confusing anempathetic music with dramatic irony alone; the point is music''s mechanical indifference to the scene.','Assuming it weakens emotion, when the mismatch often makes a scene more disturbing.','Labeling any sad scene with happy music as anempathetic without the sense of detached, unbroken continuation.']::text[],ARRAY['Playing a jaunty song over a massacre so the calm feels chilling.','Letting radio music keep going, unmoved, during a character''s death.','Choosing indifferent source music to underline a world that does not care.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='514f66fa-1a28-5e69-b628-943625e6189a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Anempathetic music'),'[^a-z0-9]','','g'));
