SELECT '514f66fa-1a28-5e69-b628-943625e6189a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='514f66fa-1a28-5e69-b628-943625e6189a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd6fa144f-b094-54fd-a6d5-36a9b09423bc','Associative orchestration','The use of orchestration, specific instruments, timbres, and instrumental combinations, to associate a recurring musical color with a particular character, place, idea, or emotion, so the sound itself carries dramatic meaning across a score. It applies orchestral color referentially, much as a leitmotif uses melody, letting timbre signal who or what is present.','This means giving a character or idea its own instrument sound. Every time you hear that sound, you think of them. For example, a low clarinet might always mean the villain. The color of the music tells part of the story.','It lets a composer signal characters, themes, or moods through timbre alone, adding a layer of storytelling that works even when the melody changes.','A composer assigns a solo instrument or distinctive blend to a character and reuses that color whenever the character appears or is evoked.','Orchestration',ARRAY['Leitmotif','Orchestration','Timbre','Instrumentation','Underscore','Added value']::text[],ARRAY['Assigning so many instrumental associations that the audience cannot track them.','Changing a character''s established color without dramatic reason, breaking the association.','Confusing it with leitmotif; one links meaning to a tune, the other to instrumental color.']::text[],ARRAY['Giving the hero a solo horn color that returns whenever they act bravely.','Using a specific percussion timbre to signal an approaching threat.','Reorchestrating a theme so a new instrument marks a character''s change.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d6fa144f-b094-54fd-a6d5-36a9b09423bc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Associative orchestration'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd6fa144f-b094-54fd-a6d5-36a9b09423bc','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d6fa144f-b094-54fd-a6d5-36a9b09423bc' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '826b4668-b4f0-54a9-ac3a-304641ce421f','Atmospheric stem','A stem, a submixed group of score elements bounced as its own track, that carries the atmospheric, textural, or ambient layer of the music, such as pads, drones, and washes, kept separate from melodic, rhythmic, or percussion stems. Delivering it on its own lets the atmosphere be balanced or removed independently in the final mix.','A stem is one grouped layer of the music, saved on its own. An atmospheric stem holds the background textures. Think of soft pads, drones, and washes. Keeping it separate lets the mixer raise or drop just the atmosphere.','It gives the re-recording mixer independent control over the score''s ambient bed, so the mood layer can sit under dialogue or be pulled without touching the rest of the music.','A composer delivers score stems split by function, such as rhythm, melody, and atmosphere, so the dub mixer can lower the atmospheric stem when dialogue needs room.','Stems & Deliverables',ARRAY['Stem','Music and effects track','Alternate cue','Underscore','Dubbing','Button alternate']::text[],ARRAY['Bouncing the atmospheric stem with processing that stops it from summing back to the full mix.','Letting melodic or rhythmic content leak into the atmospheric stem, defeating its purpose.','Delivering stems that do not line up in time, so they will not recombine cleanly.']::text[],ARRAY['Splitting a cue into rhythm, melody, and atmosphere stems for the dub stage.','Lowering just the atmospheric stem so a line of dialogue stays clear.','Reusing an atmospheric stem alone under a quiet transition.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='826b4668-b4f0-54a9-ac3a-304641ce421f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Atmospheric stem'),'[^a-z0-9]','','g'));
