SELECT '826b4668-b4f0-54a9-ac3a-304641ce421f','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='826b4668-b4f0-54a9-ac3a-304641ce421f' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7785c441-b4e8-5712-9e57-5169e0c0e1b9','Audiovisual consonance','A relationship in which sound and image agree or reinforce one another, the soundtrack matching the mood, rhythm, or meaning of the picture so the two are perceived as harmonious. In audiovisual theory it is the complementary opposite of audiovisual dissonance, in which sound and image conflict.','Audiovisual consonance is when the sound and the picture agree. The music matches what you see. Calm music plays over a calm scene. The sound and image feel like they belong together.','It describes the common case where music and image pull the same way, reinforcing a scene''s intended mood and making the storytelling feel unified.','A composer writes warm, gentle music for a tender reunion so the score is consonant with the picture and the emotion reads clearly.','Audiovisual Theory',ARRAY['Audiovisual dissonance','Audiovisual counterpoint','Empathetic music','Added value','Anempathetic music','Synchresis']::text[],ARRAY['Assuming consonance is always the right choice, when contrast can be more powerful.','Equating consonance with redundancy; well-judged agreement still adds value.','Matching only mood while ignoring rhythm, so image and sound drift apart.']::text[],ARRAY['Scoring a triumphant finale with rising, major-key music.','Matching musical accents to a scene''s cutting rhythm.','Choosing calm underscore to agree with a peaceful landscape.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7785c441-b4e8-5712-9e57-5169e0c0e1b9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Audiovisual consonance'),'[^a-z0-9]','','g'));
