SELECT '7785c441-b4e8-5712-9e57-5169e0c0e1b9','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7785c441-b4e8-5712-9e57-5169e0c0e1b9' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9f19a4e-0358-5393-8e83-763830e86dba','Audiovisual counterpoint','A relationship in which the soundtrack runs on an independent track from the image rather than merely duplicating it, so sound and picture carry different, complementary lines of meaning. Borrowed from musical counterpoint and advocated by Soviet filmmakers such as Eisenstein, the term is critiqued by Michel Chion, who argues that true audiovisual counterpoint registers only where sound and image are set in clear opposition on a specific point of meaning.','In counterpoint, the sound and picture do not just repeat each other. They go their own ways and add different meanings. The idea comes from music, where two tunes play at once. Some theorists say real film counterpoint is rare.','It gives filmmakers a way to add meaning by letting sound comment on or contrast the image instead of echoing it, broadening what the soundtrack can say.','A director scores a violent scene with tender music, or lays unrelated sound against the picture, so the two tracks say different things at once.','Audiovisual Theory',ARRAY['Audiovisual consonance','Audiovisual dissonance','Anempathetic music','Added value','Synchresis','Empathetic music']::text[],ARRAY['Calling any sound-image mismatch counterpoint, when the term implies a meaningful opposition, not mere difference.','Assuming counterpoint is common; theorists argue genuine cases are rare.','Confusing it with dissonance; counterpoint is about independent lines, not only clash.']::text[],ARRAY['Setting gentle music against a brutal image to comment on it.','Analyzing a scene where sound tells a different story than the picture.','Debating whether a mismatch is true counterpoint or just contrast.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9f19a4e-0358-5393-8e83-763830e86dba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Audiovisual counterpoint'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b9f19a4e-0358-5393-8e83-763830e86dba','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b9f19a4e-0358-5393-8e83-763830e86dba' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd39a42d2-ee61-59cd-bad8-936242758cdd','Audiovisual dissonance','A relationship in which the soundtrack conflicts with or contradicts the image, its mood, meaning, or expectation clashing with what is seen, for example incongruous sounds set against unrelated pictures. It is the opposite of audiovisual consonance and is often used deliberately for irony, unease, or critical distance.','Audiovisual dissonance is when the sound and picture clash. What you hear does not fit what you see. Happy music over a sad scene is one example. The mismatch can feel strange, ironic, or unsettling.','It lets filmmakers create tension, irony, or discomfort by making the soundtrack disagree with the image, so the clash itself carries meaning.','A composer or editor scores a grim scene with cheerful music so the dissonance unsettles the audience or comments on the action.','Audiovisual Theory',ARRAY['Audiovisual consonance','Audiovisual counterpoint','Anempathetic music','Added value','Empathetic music','Synchresis']::text[],ARRAY['Confusing dissonance with a technical mistake, when it is a deliberate, meaningful clash.','Overusing it, so the contrast loses its shock.','Assuming every clash reads as irony; context decides how a dissonance is felt.']::text[],ARRAY['Playing a lullaby over a horror image for unease.','Setting upbeat music against a bleak scene for irony.','Using clashing sound to distance the viewer from the action.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d39a42d2-ee61-59cd-bad8-936242758cdd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Audiovisual dissonance'),'[^a-z0-9]','','g'));
