SELECT 'd39a42d2-ee61-59cd-bad8-936242758cdd','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d39a42d2-ee61-59cd-bad8-936242758cdd' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7a963ea1-dab2-5a6d-ae27-1f3f040e5b95','Avoided synchronization','The deliberate practice of not aligning a musical or sound accent with a prominent visual event, so an expected synch point is withheld. Rather than hitting the action, the composer or editor lets sound and picture stay out of lockstep to keep the relationship fluid, ambiguous, or understated.','A synch point is where a sound lines up with an on-screen action, like a hit. Avoided synchronization means choosing not to line them up. The music does not hit the action on purpose. This keeps the scene loose or subtle.','It gives the composer a way to resist obvious mickey-mousing, keeping the score from underlining every move and leaving the sound-image relationship open.','A composer deliberately places accents off the cut or the action, letting the music flow past events instead of striking each one.','Synchronization',ARRAY['Beat mapping to picture','Synch point','Mickey-mousing','Anempathetic music','Audiovisual counterpoint','Spotting session']::text[],ARRAY['Confusing avoided synchronization with sloppy timing, when it is a chosen effect.','Assuming a score must hit every action, missing the value of holding back.','Avoiding all sync so the music feels disconnected rather than deliberately loose.']::text[],ARRAY['Letting a cue flow past a door slam instead of hitting it.','Keeping music steady through a cut rather than accenting it.','Choosing not to catch an action to avoid an obvious effect.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7a963ea1-dab2-5a6d-ae27-1f3f040e5b95' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Avoided synchronization'),'[^a-z0-9]','','g'));
