INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7608925d-423a-550f-b54d-911400693e8f','Beat mapping to picture','The process of aligning a project''s musical grid, its bars, beats, and tempo, to a film''s timeline by anchoring beats to specific frame positions, so the digital audio workstation calculates the tempo required between chosen points. It lets a composer write in meter while landing downbeats and accents on visual hit points or edits.','Beat mapping lines up the music''s beats with the picture. You pin beats to exact moments in the film. The software then works out the tempo between them. This lets you write in normal bars and still hit the action.','It reconciles a fixed musical meter with the irregular timing of picture events, so a composer can catch specific frames without abandoning bars and beats.','In a DAW, a composer drags beat markers onto scene hit points so the tempo map flexes to make downbeats fall exactly where the action lands.','Synchronization',ARRAY['Avoided synchronization','Synch point','Tempo map','Click track','Spotting session','Time code']::text[],ARRAY['Beat mapping without locking material to time code, so items drift off the grid.','Forcing tempos so extreme that the music becomes unplayable or unnatural.','Mapping to a rough cut and not reconforming when the picture is re-edited.']::text[],ARRAY['Pinning a downbeat to a punch so it lands on the exact frame.','Building a tempo map that flexes to catch several hit points in a scene.','Reconforming the beat map after the editor changes the cut.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7608925d-423a-550f-b54d-911400693e8f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Beat mapping to picture'),'[^a-z0-9]','','g'));
