INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '71ea56a4-2a40-5fd5-a932-4a634562ff2b','Bookend scoring','A scoring approach in which music is placed mainly at the opening and closing of a film, scene, or episode, framing it like bookends, while the middle is left largely or entirely without score. The two musical statements set up and pay off the section and often share thematic material.','Bookend scoring puts music at the start and the end. The middle has little or no music. Like bookends holding books, the two cues frame the scene. They often share the same theme.','It lets music frame a section and mark its emotional arc while keeping the middle clear, so the return of the theme at the end feels like a payoff.','A composer scores a film''s opening and finale with a shared theme, leaving the body of the picture unscored so the ending lands harder.','Scoring Technique',ARRAY['Alternate cue','Underscore','Leitmotif','Spotting session','Main title','End credits']::text[],ARRAY['Making the opening and closing cues so different that they no longer feel like a frame.','Leaving the middle unscored by default rather than by dramatic choice.','Forgetting that the closing bookend usually needs to answer the opening.']::text[],ARRAY['Scoring only a show''s cold open and closing tag with a shared theme.','Framing a film with a main-title and end-credit statement of one melody.','Leaving a tense middle act unscored between two musical bookends.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='71ea56a4-2a40-5fd5-a932-4a634562ff2b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bookend scoring'),'[^a-z0-9]','','g'));
