WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='71ea56a4-2a40-5fd5-a932-4a634562ff2b' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fb599105-4c47-51c4-b35a-c9c2e97a0c57','Button alternate','An alternate version of a cue''s button, the short, definite musical ending that punctuates and closes a scene or cue. The alternate offers a different final gesture, such as a softer resolution or a harder accent, so the filmmakers can choose how the cue lands in the final cut.','A button is a short, clear ending to a piece of film music. A button alternate is a second version of that ending. One might finish softly, another with a punch. The team picks which ending fits the scene.','It gives the director and music editor a choice of endings without rewriting the cue, so a scene can close on the gesture that best fits the picture and the cut.','A composer records the cue with two buttons, a gentle one and a punchy one, so the music editor can drop in whichever ending the final edit calls for.','Scoring Workflow',ARRAY['Alternate cue','Cue','Music editor','Bookend scoring','Stem','Spotting session']::text[],ARRAY['Recording a button alternate that does not match the cue''s key or tempo, so it cannot be swapped in cleanly.','Confusing a button with a full alternate cue; a button is only the ending gesture.','Failing to conform the alternate to the same out-point, so the ending no longer lands on the cut.']::text[],ARRAY['Providing a soft and a hard button so the editor can pick the ending.','Swapping in a button alternate when the scene''s out-point changes.','Choosing a punchier button to end a cue on an action beat.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fb599105-4c47-51c4-b35a-c9c2e97a0c57' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Button alternate'),'[^a-z0-9]','','g'));
