INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ac9c989a-e2df-58df-9c0b-770e02350685','Cadential synchronization','The scoring technique of timing a musical cadence -- a point of harmonic and melodic arrival or resolution -- so that it lands on a specific picture synchronization point, causing the music to resolve at the exact frame of a cut, action, or dramatic beat.','A cadence is where a piece of music comes to rest. This means making that resting point land on a moment in the film. The music resolves at the same instant as a cut or an action on screen.','It ties the music''s sense of closure to the picture, so a phrase ends where a shot or gesture ends and the resolution reinforces the edit.','A composer places the final chord of a phrase on the frame of a hard cut or a key action, using a marked sync point or a click track to hit it precisely.','Synchronization',ARRAY['Catch point','Catch beat','Click track','Hit point','Spotting','Cadence']::text[],ARRAY['Confusing a cadence (a musical point of rest) with the final note of a cue; a cadence can occur mid-cue.','Forcing every phrase ending onto a picture cut, which makes the score feel mechanical and over-synchronized.','Rushing or dragging the harmonic rhythm just to hit the frame, distorting the music''s natural pacing.']::text[],ARRAY['Ending a love-theme phrase exactly on a lingering close-up.','Resolving a suspense cue''s harmony on the frame where a door finally opens.','Aligning a final chord with a scene''s fade to black.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ac9c989a-e2df-58df-9c0b-770e02350685' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cadential synchronization'),'[^a-z0-9]','','g'));
