INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ebf90adb-b309-5675-9506-465cf33fb420','Catch beat','A beat in the music deliberately positioned so that a downbeat or accent coincides with -- ''catches'' -- a specific on-screen action, producing a precise musical hit on the visual event.','A catch beat is a musical beat lined up with an action on screen. The strong beat hits at the exact moment something happens. It is like a drum hit landing right when a door slams.','It lets the composer mark a screen event with a single rhythmic accent, so music and picture strike together without a continuous stream of hits.','When spotting a scene, the composer sets the tempo so a bar line or accented beat falls on the action, then confirms it against streamers, punches, or a click track on the scoring stage.','Synchronization',ARRAY['Catch point','Hit point','Click track','Streamer','Punch','Downbeat']::text[],ARRAY['Assuming any beat will do; the accent must fall on the exact frame of the action to read as a hit.','Setting a tempo that makes the catch beat land a beat early or late, so the sync looks sloppy.','Overloading a cue with catch beats until the music becomes a string of stingers.']::text[],ARRAY['Landing an orchestral accent on a punch thrown in a fight scene.','Placing a downbeat on the frame a title card appears.','Hitting a cymbal crash as a character turns to face the camera.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ebf90adb-b309-5675-9506-465cf33fb420' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Catch beat'),'[^a-z0-9]','','g'));
