INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bc6eb328-90a6-5ed7-8f6e-531c63ed91f1','Catch point','A specific point in the picture -- a single frame or moment -- where the music is required to synchronize with an on-screen action or event; a sync point the composer aims to ''catch'' with a musical accent or change.','A catch point is an exact moment in the film that the music must hit. It might be a punch, a cut, or a look. The composer writes the music so something lands right there.','It defines where picture and music must align, giving the composer and music editor a fixed target to build tempo and structure around.','During spotting, catch points are logged with their timecodes, then the music editor prepares streamers, punches, or a click track so the players hit each one on the stage.','Synchronization',ARRAY['Catch beat','Hit point','Sync point','Click track','Streamer','Spotting']::text[],ARRAY['Treating a catch point as approximate; it is tied to a specific frame.','Confusing a catch point (a place in the picture) with a catch beat (the musical beat that hits it).','Planning so many catch points that the cue cannot flow musically between them.']::text[],ARRAY['Marking the frame where a spaceship jumps to hyperspace as a catch point.','Logging a character''s first entrance as a catch point during spotting.','Building a cue''s tempo map around three catch points in an action sequence.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bc6eb328-90a6-5ed7-8f6e-531c63ed91f1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Catch point'),'[^a-z0-9]','','g'));
