INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9099f08c-1fda-536e-bf3d-8c4be6371e71','Characteristic piece','A short instrumental composition, historically most often for piano, that depicts a single specific mood, character, scene, or extramusical idea; also called a character piece (Ger. Charakterstueck). In silent-film practice, ''characteristic'' numbers were light descriptive pieces used to accompany eccentric, comic, or picturesque scenes.','A characteristic piece is a short piece of music built around one mood or idea. Think of a tune that paints a single picture, like a march or a sad song. Silent-film players used these short mood pieces to match scenes.','It packages a clear, self-contained mood into a brief form, which made such pieces ideal building blocks for illustrating a scene or a character.','A silent-film accompanist picked characteristic pieces from photoplay albums to fit each scene''s mood, stitching them into a compiled accompaniment.','Musical Form',ARRAY['Compiled accompaniment','Compilation score','Comic hurry','Comic misterioso','Photoplay music']::text[],ARRAY['Confusing a characteristic piece with large-scale program music; it is short and captures one mood, not a whole narrative.','Assuming ''characteristic'' always means comic; it can depict any single mood or scene.','Treating it as a strict fixed form; the term describes content and mood, not a set structure.']::text[],ARRAY['Selecting a stormy characteristic piece for a shipwreck scene in a silent film.','A pianist choosing a pastoral character piece for a countryside sequence.','Programming short character pieces to build a live silent-film accompaniment.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9099f08c-1fda-536e-bf3d-8c4be6371e71' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Characteristic piece'),'[^a-z0-9]','','g'));
