INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ba59245-c701-5bec-b26c-0f373bbe2bcf','Chromatic mediant network','The interconnected system of harmonic relationships between triads or keys whose roots lie a third apart but which are chromatically altered, so a chromatic mediant shares fewer common tones (typically one, or none) than a diatonic mediant. Composers move through this web of third-related, largely non-functional harmonies to create colorful, unexpected shifts characteristic of film underscore.','A mediant chord has its root a third away from the home chord. A chromatic mediant is one shifted with notes from outside the key. A network is the web of these third-apart chords a composer can slide between. Film music uses them for a grand or magical feeling.','It gives composers a palette of smooth yet surprising harmonic moves that sidestep ordinary key relationships, useful for wonder, scale, or unease.','A film composer shifts, for example, from C major to E major or A-flat major to lift a reveal, chaining such moves to travel far from the home key and back.','Harmony',ARRAY['Leitmotif','Underscore','Modulation','Neo-Riemannian theory','Cadence','Chromaticism']::text[],ARRAY['Calling any third-related chord a chromatic mediant; a diatonic mediant stays within the key and is not chromatic.','Assuming chromatic mediants must function like dominants; they are usually valued for color, not for pulling to a resolution.','Confusing a chromatic mediant with a plain key change, ignoring the shared common tone that makes the move smooth.']::text[],ARRAY['Scoring a fantasy vista by sliding between major chords a third apart.','Building a heroic theme that leaps up by a chromatic third for lift.','Analyzing a film cue''s harmony using mediant relationships.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ba59245-c701-5bec-b26c-0f373bbe2bcf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Chromatic mediant network'),'[^a-z0-9]','','g'));
