SELECT '8ba59245-c701-5bec-b26c-0f373bbe2bcf','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8ba59245-c701-5bec-b26c-0f373bbe2bcf' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '48fce6f7-7c83-5281-8f49-727933f9d24a','Clean tail','A recorded take or cue whose ending is free of extraneous sound: the final note and its reverberant decay stop cleanly, with no talkback, page turns, chair or breath noise, or overlap, so the end can be edited, faded, or cross-faded without capturing unwanted sound.','A clean tail is a tidy ending on a recording. The last note fades out with no extra noise after it. That makes it easy to trim or fade the end without catching coughs or talking.','It gives the editor a usable, noise-free ending, which is essential when cues must be trimmed, faded, or joined in the mix.','On a scoring stage the mixer holds the recorder until the reverb fully decays and the room is quiet, capturing a clean tail before anyone speaks or moves.','Recording & Editing',ARRAY['Clean top','Cue','Reverb tail','Editing','Crossfade','Room tone']::text[],ARRAY['Cutting the recorder before the reverb decays, chopping the tail and leaving no room to fade.','Letting players relax and make noise the instant the last note ends, ruining the tail.','Confusing the reverb tail of the sound with a clean tail of the recording; one is the decay, the other is the noise-free capture of it.']::text[],ARRAY['Recording a sustained final chord and holding for its decay before cutting.','Editing two cues together and needing a clean tail to cross-fade.','Delivering a cue with a clean tail so the dub mixer can fade it under dialogue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='48fce6f7-7c83-5281-8f49-727933f9d24a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Clean tail'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '48fce6f7-7c83-5281-8f49-727933f9d24a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='48fce6f7-7c83-5281-8f49-727933f9d24a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7e2dd8bf-1f90-5442-8919-c9f83df44727','Clean top','A recorded take or cue whose beginning is free of extraneous sound: no count-off, talkback, pickup notes, chair or breath noise, or bleed before the first intended note, so the start can be edited or triggered cleanly.','A clean top is a tidy start on a recording. Nothing extra is heard before the first note. No counting in, no chatter, no chair squeaks, just silence and then the music.','It gives the editor a precise, noise-free downbeat to cut to, which matters when a cue must start exactly on a picture point.','The recordist starts the machine early and keeps the room silent, so the take has a clean top the music editor can slip to any frame.','Recording & Editing',ARRAY['Clean tail','Cue','Downbeat','Editing','Count-off','Sync point']::text[],ARRAY['Rolling in a count-off or talkback that bleeds into the top of the take.','Starting the recorder late and clipping the attack of the first note.','Confusing a clean top with a hard start; a clean top can still have a soft fade-in, just no stray noise.']::text[],ARRAY['Capturing an a cappella entrance with a clean top for editing.','Needing a clean top to align a cue''s first note to a cut.','Editing a compiled score where each piece must have a clean top to butt-join.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7e2dd8bf-1f90-5442-8919-c9f83df44727' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Clean top'),'[^a-z0-9]','','g'));
