SELECT '7e2dd8bf-1f90-5442-8919-c9f83df44727','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7e2dd8bf-1f90-5442-8919-c9f83df44727' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '093bb5f7-39ca-599b-b09e-5708e0be5c0b','Click dropout','A momentary loss or interruption of the click-track signal in the performers'' headphones during recording, so the audible metronomic pulse cuts out and players temporarily lose their timing reference.','A click track is a steady beep players hear in headphones to keep time. A click dropout is when that beep cuts out for a moment. The players can drift off the beat until it comes back.','Naming the fault helps the crew catch and fix it, because losing the click even briefly can throw the ensemble out of sync with the picture.','If musicians report a click dropout, the music editor and engineer check the headphone routing, the click generator, and the cue mix, then re-record the affected bars.','Click Track',ARRAY['Click track','Click value','Cue mix','Headphone mix','Sync point','Streamer']::text[],ARRAY['Blaming the players for rushing when a click dropout was the real cause of the drift.','UNSAFE: turning the headphone click up to painful levels to avoid missing it; protect hearing and fix the routing instead.','Ignoring an intermittent dropout instead of tracing the faulty cable or cue-mix send.']::text[],ARRAY['A cellist loses the beat when the click drops out for two bars.','Troubleshooting a headphone send that intermittently cuts the click.','A take is ruined by a click dropout at a key hit and must be redone.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='093bb5f7-39ca-599b-b09e-5708e0be5c0b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Click dropout'),'[^a-z0-9]','','g'));
