INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67c457bf-9854-5603-975c-ec48f914f1c6','Click value','The numeric value that defines a click track''s tempo. In the traditional frame-based film system it is expressed as the number of film frames (and eighths of a frame) between successive clicks -- a smaller frame value gives a faster tempo -- and it can equivalently be stated in beats per minute.','A click value sets how fast the click track beeps. In the old film method it counts the frames between beats. Fewer frames between beats means a faster tempo. Today it is often just given in beats per minute.','It fixes the exact tempo so the music editor can build a click that places beats and hits on the intended frames of the picture.','A composer picks a click value, such as a 12-frame click, from a click book or software so a downbeat falls on a chosen catch point, then the editor generates that click for the session.','Click Track',ARRAY['Click track','Click dropout','Catch point','Tempo','Frame rate','Click book']::text[],ARRAY['Reading a smaller frame value as a slower tempo; fewer frames per beat is actually faster.','Forgetting that the click value depends on frame rate, so the same frames-per-beat gives a different tempo at 24 versus 25 frames per second.','Confusing the click value (the tempo setting) with a click dropout (a signal fault).']::text[],ARRAY['Choosing a click value so a bar line lands on an on-screen explosion.','Converting a frame-based click value to beats per minute for a DAW.','Reading click values from a click book to match an old cue''s tempo.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67c457bf-9854-5603-975c-ec48f914f1c6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Click value'),'[^a-z0-9]','','g'));
