INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '11d76af9-f9a7-5477-b751-d2f9ed18f653','Comic hurry','A silent-film photoplay genre: a fast, bustling ''hurry'' cue written in a light, humorous style, used to accompany comic chases, slapstick pursuits, and frantic comedic action. Like all hurries it is quick in tempo with short, agitated note values, but its character is playful rather than dramatic.','A hurry is fast, busy chase music from silent films. A comic hurry is the funny version of it. It races along to match slapstick chases and silly, frantic action on screen.','It gave silent-film players a ready-made cue to drive comic action, matching quick on-screen movement with light, energetic music.','A theater pianist or ensemble pulled a comic hurry from a photoplay album to underscore a slapstick chase, repeating or vamping it to fit the scene''s length.','Photoplay Genre',ARRAY['Comic misterioso','Compiled accompaniment','Photoplay music','Misterioso','Characteristic piece','Cue sheet']::text[],ARRAY['Playing a comic hurry too heavily or darkly, which turns comedy into melodrama.','Confusing it with a dramatic hurry or agitato meant for serious action.','Assuming it is one fixed composition; it is a genre category, with many titles filling the same role.']::text[],ARRAY['Accompanying a slapstick foot chase in a silent comedy.','Underscoring a frantic, comic escape through a crowded street.','Selecting a comic hurry from a mood-music album to fit a comedy gag.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='11d76af9-f9a7-5477-b751-d2f9ed18f653' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Comic hurry'),'[^a-z0-9]','','g'));
