SELECT '11d76af9-f9a7-5477-b751-d2f9ed18f653','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='11d76af9-f9a7-5477-b751-d2f9ed18f653' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f406a915-4e1b-54ca-8b9d-9484a2532ff9','Comic misterioso','A silent-film photoplay genre: a ''misterioso'' cue -- quiet, suspenseful, creeping music, usually in a minor key with soft, stealthy figures -- written in a light, comic vein for comedic stealth, tiptoeing, mischief, and comic suspense rather than genuine menace.','A misterioso is soft, sneaky, mysterious music from silent films. A comic misterioso is the funny version. It fits tiptoeing and comic suspense, hinting at mischief instead of real danger.','It let players underscore comic sneaking and suspense with music that sounds mysterious but stays light, cueing the audience to laugh rather than fear.','An accompanist chose a comic misterioso from a photoplay album for a scene of a character tiptoeing to steal a pie, matching its stealthy, playful mood.','Photoplay Genre',ARRAY['Comic hurry','Misterioso','Compiled accompaniment','Photoplay music','Characteristic piece','Cue sheet']::text[],ARRAY['Playing it as a true misterioso, making a comic scene feel genuinely threatening.','Confusing the comic misterioso with a dramatic or ''gruesome'' misterioso used for real menace.','Treating it as one fixed tune rather than a genre with many interchangeable titles.']::text[],ARRAY['Underscoring a character sneaking on tiptoe in a silent comedy.','Accompanying a bumbling burglar creeping through a house.','Choosing a comic misterioso for a playful hide-and-seek gag.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f406a915-4e1b-54ca-8b9d-9484a2532ff9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Comic misterioso'),'[^a-z0-9]','','g'));
