INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd413216b-7eea-5cd3-a6c7-66d0963ed27d','Compilation score','A film score assembled largely or entirely from pre-existing music -- popular songs, classical works, or library tracks not originally composed for the film -- selected and arranged to accompany the picture, as opposed to an original underscore written specifically for it.','A compilation score is a film score built from music that already existed. Instead of new music, it uses pop songs or classical pieces. The filmmakers pick tracks that fit each scene.','It scores a film using known or ready-made music, which can set a period, tap a song''s cultural meaning, or save the time and cost of original composition.','A music supervisor clears and places existing tracks against picture to build a compilation score, matching each song''s mood and tempo to the scene.','Score Type',ARRAY['Compiled accompaniment','Source music','Needle drop','Original score','Music supervisor','Temp track']::text[],ARRAY['Confusing a compilation score with source music; compilation tracks are often non-diegetic underscore, not sound coming from within the scene.','Assuming pre-existing tracks are free to use; each must be licensed for both the master recording and the composition.','Calling any film with a few songs a compilation score, rather than one scored mainly from existing music.']::text[],ARRAY['Scoring a period drama with era-appropriate pop hits.','Building a montage from licensed songs instead of original cues.','A director choosing a compilation score to evoke a specific decade.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d413216b-7eea-5cd3-a6c7-66d0963ed27d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compilation score'),'[^a-z0-9]','','g'));
