SELECT 'd413216b-7eea-5cd3-a6c7-66d0963ed27d','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d413216b-7eea-5cd3-a6c7-66d0963ed27d' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de0ac82e-ae1f-51a5-a1cf-926e7a8597e7','Compiled accompaniment','A silent-film accompaniment assembled by selecting and stitching together pre-existing pieces -- photoplay numbers and library music organized by mood -- to fit a film''s scenes in sequence, typically guided by a cue sheet, rather than a specially composed original score.','In the silent-film era, players often had no new music written for a film. Compiled accompaniment means they built the score from existing mood pieces. They picked pieces to match each scene and played them in order.','It let theaters accompany any film cheaply and quickly by drawing on standard mood-music libraries, without commissioning an original score.','A music director followed a cue sheet, pulling a hurry, a misterioso, or a love theme from photoplay albums to compile an accompaniment matched to the film''s scenes.','Silent-Film Music',ARRAY['Compilation score','Photoplay music','Cue sheet','Comic hurry','Comic misterioso','Characteristic piece']::text[],ARRAY['Confusing compiled accompaniment with a through-composed original silent-film score written for one film.','Assuming pieces were played at random; selections followed the scene''s mood and often a printed cue sheet.','Thinking each film had a single fixed accompaniment; different theaters compiled different music for the same film.','Confusing compiled accompaniment (a silent-era, live accompaniment assembled from mood pieces per a cue sheet) with a compilation score (a modern sound-film score built from pre-existing songs or works).']::text[],ARRAY['A cinema pianist compiling music from mood albums for a new feature.','Following a studio cue sheet to assemble a film''s accompaniment.','Recreating a silent film''s compiled accompaniment for a modern screening.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de0ac82e-ae1f-51a5-a1cf-926e7a8597e7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compiled accompaniment'),'[^a-z0-9]','','g'));
