SELECT 'de0ac82e-ae1f-51a5-a1cf-926e7a8597e7','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de0ac82e-ae1f-51a5-a1cf-926e7a8597e7' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '31a24ca4-0000-529e-9b0d-1ef901caf03b','Conductor picture feed','The synchronized video image of the film supplied to the conductor on the scoring stage, marked with visual timing cues such as streamers and punches so the ensemble can be conducted in precise sync with the picture while a cue is recorded.','It is the movie picture shown to the conductor while the orchestra records. Marks flash on the screen at exact moments, so the music lines up with the film.','It lets the conductor keep the live performance locked to the on-screen action in real time, so recorded music lands on its intended sync points instead of relying on a click alone.','The music editor prepares the picture with streamers, punches, and a cue title slate, then routes it to the conductor''s monitor so takes can be recorded in sync during a scoring session.','Scoring Stage',ARRAY['Streamers and punches','Click track','Scoring stage','Music editor','Picture lock','Timecode']::text[],ARRAY['Confusing the picture feed with the click track; the feed shows visual sync cues while the click gives an audible tempo.','Sending an out-of-date or wrongly offset picture, so the streamers no longer match the locked cut.','Assuming the conductor reads timecode numbers instead of the streamers and punches placed on the image.']::text[],ARRAY['An orchestra records a cue on a scoring stage while the conductor follows streamers on the picture feed.','The music editor re-exports the picture feed after a re-edit moves a cue''s hit points.','A composer chooses to conduct to picture and click together to catch fast action sync points.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='31a24ca4-0000-529e-9b0d-1ef901caf03b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Conductor picture feed'),'[^a-z0-9]','','g'));
