SELECT '31a24ca4-0000-529e-9b0d-1ef901caf03b','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='31a24ca4-0000-529e-9b0d-1ef901caf03b' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd04c2d8f-d1a4-50b2-9d23-c88ad2ca3320','Cue assembly','The process of editing and combining the recorded takes, overdubs, and elements of a single music cue into one complete, in-sync version ready for mixing.','It means putting together the best recorded parts of one piece of film music. The editor joins the takes into one clean version that fits the scene.','It turns the many separate takes captured at a scoring session into a single approved performance of the cue, so the mix stage receives one coherent piece per cue.','After a scoring session the music editor cuts together the chosen takes for each cue in the DAW, fixing sync and edits before the cue is mixed.','Music Editing',ARRAY['Cue','Music editor','Cue assembly master','Scoring session','Conform','Stem']::text[],ARRAY['Assembling from the wrong or unapproved takes because take notes were not logged during recording.','Leaving edit points that break the musical phrasing or create audible clicks between takes.','Forgetting to keep the cue locked to timecode, so the assembled cue drifts against picture.']::text[],ARRAY['A music editor assembles the master take and inserts for a cue after the orchestra records several passes.','During assembly the editor patches a flubbed bar from an alternate take into the main take.','The assembled cue is bounced and sent to the dub stage for the final mix.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d04c2d8f-d1a4-50b2-9d23-c88ad2ca3320' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue assembly'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd04c2d8f-d1a4-50b2-9d23-c88ad2ca3320','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d04c2d8f-d1a4-50b2-9d23-c88ad2ca3320' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '438cfe62-8e00-55c2-b61a-9b28956d786c','Cue assembly master','The finished, approved assembled version of a music cue: the single master edit that consolidates the selected takes and elements and serves as the source for mixing, revision, and delivery.','It is the final joined-together version of one film music piece. This master copy is what gets mixed and delivered to the film.','It provides one definitive reference version of the cue, so mixing, revisions, and deliverables all start from the same approved edit.','The music editor labels the completed assembly as the cue''s master, then pulls stems or a mix from it for the dub stage and the archive.','Music Editing',ARRAY['Cue assembly','Cue','Stem','Music editor','Cue package','Dub stage']::text[],ARRAY['Treating an early rough assembly as the master before takes are approved.','Keeping several unlabeled ''master'' versions, so the wrong edit goes to the mix.','Not re-exporting the master after a late edit, leaving stems out of sync with the current cut.']::text[],ARRAY['The dub stage pulls stems from the cue assembly master for the final re-recording mix.','An archive copy of each cue''s assembly master is stored for future re-use or remixes.','A revision request sends the editor back to update the cue assembly master.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='438cfe62-8e00-55c2-b61a-9b28956d786c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue assembly master'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
