INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b95737f5-dc73-54a4-bf6c-87c98ead534a','Cue combine','An editorial operation that merges two or more adjacent music cues into a single continuous cue, renumbering or renaming the result to reflect the joined content.','It means joining two nearby pieces of film music into one longer piece. Editors do this when a scene no longer needs a break between them.','It simplifies the cue list when a picture edit removes the gap between cues, so a continuous stretch of music is handled as one unit for mixing and paperwork.','When two cues run back to back after a re-edit, the music editor combines them into one cue and updates the cue sheet and numbering.','Cue Management',ARRAY['Cue split','Cue','Cue sheet','Music editor','Cue number','Conform']::text[],ARRAY['Combining cues without updating the cue sheet, so royalty logging becomes wrong.','Merging cues that have different tempos or keys without smoothing the join.','Losing the original separate cue names, making later revisions hard to track.']::text[],ARRAY['A re-edit deletes a scene break, so two cues are combined into one continuous piece.','The composer decides two short cues should play as one longer statement.','A music editor combines cues before delivering a simplified cue list to the mix.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b95737f5-dc73-54a4-bf6c-87c98ead534a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue combine'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b95737f5-dc73-54a4-bf6c-87c98ead534a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
