INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2c275f9d-c744-5a94-91f6-76fbeda78f69','Cue insert','A music cue newly added into the running order of a reel or scene, placed between or within existing cues and given an inserted cue number (often a letter suffix) so surrounding cues need not be renumbered.','It is a new piece of film music dropped into a spot that had none before. It gets a letter added to its number, so the other cues keep their names.','It lets composers add music where the edit now needs it without disturbing the established numbering of the cues already in the reel.','When a director asks for music in a previously unscored moment, the composer writes an insert cue and the editor numbers it, for example 2M4A between 2M4 and 2M5.','Cue Management',ARRAY['Cue','Cue number','Cue suffix','Cue replacement','Spotting session','Cue sheet']::text[],ARRAY['Renumbering the whole reel to fit an insert instead of using a letter suffix.','Inserting a cue but forgetting to add it to the cue sheet and the session.','Choosing an insert number that clashes with an existing revision letter.']::text[],ARRAY['A late note asks for a short musical sting, added as an insert cue between two existing cues.','The editor slots an insert cue into the Pro Tools session for the next scoring session.','An insert cue is written for a scene that was unscored in the temp track.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2c275f9d-c744-5a94-91f6-76fbeda78f69' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue insert'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2c275f9d-c744-5a94-91f6-76fbeda78f69','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
