INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0663ab75-f8c6-5702-9fed-75a62c7a2f7f','Cue lock','The point at which a cue''s timing is fixed against a locked picture, so its start, sync points, and length are frozen and any further picture change is handled as a conform or revision rather than a free edit.','It is when a piece of film music is set to match a finished cut. After this, the timing stays put unless the picture changes and a new version is made.','It gives the composer and mixers a stable target, so a cue can be finished, recorded, and mixed without its sync points shifting underfoot.','Once picture is locked for a reel, the music editor locks each cue''s timings and treats any later cut change as a conform or a revision.','Cue Management',ARRAY['Picture lock','Conform','Cue','Timecode','Cue revision letter','Music editor']::text[],ARRAY['Locking a cue to a picture cut that has not truly been locked, so its hits drift.','Forgetting to conform or re-lock a cue after an approved picture change.','Assuming a locked cue can absorb small edits without a formal revision.']::text[],ARRAY['A reel reaches picture lock, so the editor locks its cues before recording.','A locked cue must be conformed after the director approves a late trim.','The composer finalizes orchestration only once the cue is locked to timing.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0663ab75-f8c6-5702-9fed-75a62c7a2f7f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue lock'),'[^a-z0-9]','','g'));
