INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '606be155-3908-5f01-a1a4-0113040e91bc','Cue package','The bundle of deliverables for a single cue, typically the mix, stems, and any documentation, assembled and named to a delivery specification for the dub stage, archive, or music supervisor.','It is the set of files delivered for one piece of film music. It usually holds the mix, the split tracks, and notes, all named to the studio''s rules.','It packages everything the mix stage and archive need for a cue into one consistent, correctly named set, so nothing is missing at the dub.','The music editor exports each cue''s stems and mix, names them to the delivery spec, and hands off the cue package for the final mix and archiving.','Music Delivery',ARRAY['Stem','Cue assembly master','Cue','Dub stage','Delivery spec','Music editor']::text[],ARRAY['Delivering a cue package with mislabeled or missing stems.','Using a sample rate or file format that does not match the delivery spec.','Bundling an outdated mix that predates the latest cue revision.']::text[],ARRAY['The editor delivers a cue package of stems to the re-recording mixer for the dub.','An archive receives the cue package for every cue at the end of the project.','A music supervisor requests the cue package to clear and log the music.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='606be155-3908-5f01-a1a4-0113040e91bc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue package'),'[^a-z0-9]','','g'));
