INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3585849c-657f-54cc-83ae-6cdef75e01ad','Cue prefix','The leading part of a cue''s identifier, typically the reel number and the ''M'' music designator (for example the ''1M'' in 1M1), which groups a cue within its reel or section of the film.','It is the front part of a film music piece''s name. Often it is the reel number plus an M, like the 1M in 1M1. That shows which reel the cue belongs to.','It sorts and groups cues by reel or section, so anyone can tell at a glance where a cue sits in the film.','When numbering cues, the editor sets the prefix from the reel (1M, 2M, 3M, and so on) and adds the sequence number after it.','Cue Numbering',ARRAY['Cue number','Cue suffix','Reel','Cue','Cue sheet','Cue revision letter']::text[],ARRAY['Confusing the reel prefix with the sequential cue number.','Using inconsistent prefixes across reels, which breaks the sort order.','Dropping the ''M'' designator, so music cues are hard to tell from other elements.']::text[],ARRAY['A composer numbers a reel-3 cue with the prefix 3M before its sequence number.','The editor sorts the cue list by prefix to review one reel at a time.','A cue sheet groups cues by their reel prefix for the mix.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3585849c-657f-54cc-83ae-6cdef75e01ad' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue prefix'),'[^a-z0-9]','','g'));
