SELECT '3585849c-657f-54cc-83ae-6cdef75e01ad','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3585849c-657f-54cc-83ae-6cdef75e01ad' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '990bc9bb-1855-5158-9719-4627b2fa5747','Cue replacement','A new cue written to take the place of an existing one, keeping the same slot in the running order but supplying different music; the swap is flagged so paperwork, sessions, and deliverables track it.','It is a fresh piece of film music that takes over the spot of an old one. The scene keeps its music slot, but the music itself is changed.','It lets the team change the music for a scene after a creative decision without disturbing the numbering of the other cues.','When the director rejects a cue, the composer writes a replacement, and the editor swaps it into the session and cue sheet under the same slot.','Cue Management',ARRAY['Cue','Cue insert','Cue revision letter','Cue status','Cue sheet','Temp music']::text[],ARRAY['Leaving the old cue in the session or cue sheet alongside its replacement.','Not updating the replaced cue''s status, so the mix uses the wrong version.','Reusing the old cue''s stems by mistake after the music has changed.']::text[],ARRAY['A director rejects a cue and the composer delivers a replacement for the same scene.','A licensed song is dropped, so an original replacement cue is scored.','The editor logs the cue replacement so the dub stage loads the new music.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='990bc9bb-1855-5158-9719-4627b2fa5747' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue replacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '990bc9bb-1855-5158-9719-4627b2fa5747','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='990bc9bb-1855-5158-9719-4627b2fa5747' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '26a32699-85df-572e-b3f9-dc089cfa3b94','Cue revision letter','A letter appended to a cue''s number to mark a new version of that cue (for example 1M1 becoming 1M1A, then 1M1B), distinguishing successive revisions or inserts while preserving the base cue number.','It is a letter added to a film music piece''s name to show a new version. So 1M1 becomes 1M1A, then 1M1B, as changes are made.','It keeps a clear version history for each cue, so the team always knows which version is current without renumbering the whole reel.','Each time a cue is revised or an insert is added, the editor bumps its revision letter and updates the session, cue sheet, and delivery names.','Cue Numbering',ARRAY['Cue number','Cue suffix','Cue prefix','Cue status','Cue insert','Cue']::text[],ARRAY['Skipping or reusing revision letters, so versions collide.','Delivering a cue without its current revision letter, so the mix loads an old version.','Confusing a revision letter with an insert letter for a brand-new cue.']::text[],ARRAY['A cue is revised after notes, so 2M5 is delivered as 2M5A.','The editor tracks revision letters to confirm the dub has the latest cues.','An insert cue takes the next available letter after the base cue number.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='26a32699-85df-572e-b3f9-dc089cfa3b94' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue revision letter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '26a32699-85df-572e-b3f9-dc089cfa3b94','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
