INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '845ceda7-ff25-51fc-9838-b83321a64c85','Cue split','An editorial operation that divides a single music cue into two or more separate cues, each given its own number, usually because a picture edit or creative change adds a break within the original cue.','It means cutting one piece of film music into two or more pieces. Each new piece gets its own name and number.','It lets a long or interrupted cue be handled as separate units when the edit or the drama calls for a break, easing revisions, mixing, and logging.','When a scene change cuts into the middle of a cue, the editor splits it into two cues and renumbers the second part.','Music Editing',ARRAY['Cue combine','Cue','Cue number','Cue sheet','Music editor','Conform']::text[],ARRAY['Splitting a cue but not renumbering or logging the new second cue.','Cutting at a point that leaves an unmusical or abrupt edit.','Forgetting to update stems and deliverables for both resulting cues.']::text[],ARRAY['A new scene break splits one cue into two shorter cues.','The composer wants a cue to stop and restart, so the editor splits it.','A split cue is renumbered and added to the cue sheet before the mix.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='845ceda7-ff25-51fc-9838-b83321a64c85' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue split'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '845ceda7-ff25-51fc-9838-b83321a64c85','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
