INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b90fd2e7-fcac-55f4-a3ee-7e1606b30211','Cue status','The tracked production state of a cue within the cue list, such as spotted, in progress, approved, locked, recorded, revised, or delivered, used to manage its progress from spotting to final delivery.','It is the current stage of a film music piece. It shows if the cue is still being written, approved, recorded, or already delivered.','It gives the composer, editor, and producers a shared view of how far each cue has progressed, so nothing is missed before the mix.','The music editor updates each cue''s status on the cue list as it moves from spotting through approval, recording, and delivery.','Cue Management',ARRAY['Cue sheet','Cue','Cue revision letter','Spotting session','Cue replacement','Music editor']::text[],ARRAY['Leaving a cue''s status out of date, so a revised cue still looks approved.','Marking a cue delivered before its stems are actually exported.','Tracking status only in one person''s head instead of a shared list.']::text[],ARRAY['A producer checks the cue list to see which cues are still unapproved.','The editor marks a cue as locked once picture and timing are set.','A cue''s status changes to revised after the director gives notes.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b90fd2e7-fcac-55f4-a3ee-7e1606b30211' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue status'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b90fd2e7-fcac-55f4-a3ee-7e1606b30211','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
