INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da76d614-6b51-5039-95d3-70ea81551016','Cue suffix','The trailing part of a cue''s identifier that follows the base number, most often a revision or insert letter (for example the ''A'' in 1M1A), used to distinguish versions or added cues without changing the base cue number.','It is the end part of a film music piece''s name, usually a letter. For example, the A in 1M1A shows it is a new version or an added cue.','It carries version and insert information, so cues can be revised or added while their base numbers stay stable.','When revising or inserting a cue, the editor sets the suffix letter and updates the session and cue sheet to match.','Cue Numbering',ARRAY['Cue prefix','Cue number','Cue revision letter','Cue insert','Cue','Cue sheet']::text[],ARRAY['Confusing the suffix letter with the reel prefix.','Reusing a suffix already taken by another version, causing clashes.','Delivering with the wrong suffix, so the mix loads the wrong version.']::text[],ARRAY['A revised cue takes the suffix A, becoming 1M1A.','An insert cue uses a letter suffix to slot between numbered cues.','The editor checks each cue''s suffix to confirm the latest version is delivered.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da76d614-6b51-5039-95d3-70ea81551016' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue suffix'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'da76d614-6b51-5039-95d3-70ea81551016','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='da76d614-6b51-5039-95d3-70ea81551016' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da969e17-5579-5a8d-83f5-5f281c1e950d','Cue turnover','The formal handoff of a music cue''s materials at a defined milestone in the scoring workflow — for example, when picture editorial turns over a locked section of picture, with timing and change notes, to the composer and music editor to be scored, or when a finished cue is turned over to the re-recording mix. Each turnover fixes the reference version everyone works to until the next revision.','A cue is one piece of music written for a scene. A turnover is a formal handoff. Someone passes a locked version of the picture, or a finished cue, to the next team. It tells everyone which version to work from. No one changes it until the next handoff.','It gives every department a single agreed reference version to work against, so the composer, music editor, and mixers are not chasing a moving edit. It creates clear checkpoints in a tight schedule.','A music editor receiving a turnover conforms the existing cues to the new picture, logs every frame that moved, and flags cues that no longer fit.','Scoring Workflow',ARRAY['Picture lock','Spotting session','Music editor','Cue','Conform','Cut bar']::text[],ARRAY['Continuing to score against an old turnover after picture editorial has issued change notes, so cues drift out of sync.','Not logging the exact frame changes between turnovers, making it impossible to conform cues cleanly.','Assuming a turnover always means final picture lock; turnovers often precede several more editorial changes.']::text[],ARRAY['Picture editorial turns over a reel to the composer so scoring can begin.','A revised turnover arrives after a scene is re-cut and cues must be conformed.','Finished cues are turned over to the dub stage for the final mix.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da969e17-5579-5a8d-83f5-5f281c1e950d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue turnover'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'da969e17-5579-5a8d-83f5-5f281c1e950d','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='da969e17-5579-5a8d-83f5-5f281c1e950d' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e6f84d69-05fb-50c5-ae2e-f6fe5ffc1276','Cue versioning','The systematic tracking, labelling, and archiving of successive versions and alternates of a music cue as it is revised — for example v1, v2, revised, or an alternate (''alt'') — so that any prior state can be identified, recalled, or restored during the scoring process.','A cue is one piece of music for a scene. It gets revised many times. Versioning means giving each version a clear name and date. It could be version 1, version 2, or an alternate take. This lets the team find or bring back any earlier version later.','It preserves a clear history of a cue so directors can compare options and the team can revert to an earlier idea without rebuilding it. It prevents confusion over which file is current.','A composer saves each approved revision with a version label, notes what changed, and keeps the alternates so a director can request an earlier direction.','Scoring Workflow',ARRAY['Cue','Alternate (alt)','Cue turnover','Stem','Music editor','Session file']::text[],ARRAY['Overwriting the previous version instead of saving a new one, so an approved idea is lost.','Using vague file names that do not say which version is current or approved.','Failing to keep alternates, so a director''s earlier preference cannot be recovered.']::text[],ARRAY['A director asks to hear the version of a cue from two revisions ago.','A composer delivers a main version plus two alternates for a pivotal scene.','A music editor tracks which cue version is approved for the final mix.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e6f84d69-05fb-50c5-ae2e-f6fe5ffc1276' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue versioning'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e6f84d69-05fb-50c5-ae2e-f6fe5ffc1276','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e6f84d69-05fb-50c5-ae2e-f6fe5ffc1276' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b1b220a0-bdea-5dd0-a73b-93660818c7bb','Cue-sheet incipit','The brief opening passage of a cue — its first few notes, and sometimes its title and tempo — reproduced (often in notation) on a cue sheet to identify the piece. In silent-film musical cue sheets the incipit let the theatre musician recognise and cue the correct piece; the incipit is the minimal fragment that uniquely identifies a work.','An incipit is the first few notes of a piece of music. A cue sheet is a list of the music used in a show or film. Printing the opening notes next to each entry helps a musician spot the right piece fast. It works like the first line of a song telling you which song it is.','It provides a compact, recognisable fingerprint of a cue so it can be spotted on a document without printing the full score. It links a written list to the actual music.','A silent-film accompanist reads the incipit on a cue sheet to confirm which piece to play at a scene, matching it against the sheet music on the stand.','Music Documentation',ARRAY['Cue sheet','Cue','Incipit','Spotting notes','Curtain music','Score']::text[],ARRAY['Confusing the notated incipit with the performing-rights cue sheet, which is a text log and usually carries no music notation.','Writing an incipit too short to tell similar pieces apart.','Assuming the incipit is the whole cue rather than just its identifying opening.']::text[],ARRAY['A silent-film pianist uses cue-sheet incipits to follow the prepared music plan.','A music librarian identifies an unlabelled cue from its notated incipit.','A thematic catalogue lists each cue by its opening incipit.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b1b220a0-bdea-5dd0-a73b-93660818c7bb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue-sheet incipit'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b1b220a0-bdea-5dd0-a73b-93660818c7bb','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b1b220a0-bdea-5dd0-a73b-93660818c7bb' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3c60af4e-13c8-5030-acd0-93317456a9fe','Curtain music','Instrumental music played in the theatre while the curtain is down — historically (17th–18th century) the ''act tune'' or ''curtain tune'' performed between the acts of a play, and by extension music played as the curtain rises or falls, functioning much like an overture or entr''acte.','Curtain music is music played while the stage curtain is down. Old plays used it between the acts, when the curtain had dropped. It fills the gap and sets the mood for what comes next. It works like a short overture between scenes.','It covers the pause while the curtain is down, keeps the audience engaged between acts, and sets the mood for the coming scene. It marks the start or end of a dramatic section.','A theatre music director selects and cues curtain music to bridge scene changes, timing it to the physical raising and lowering of the curtain.','Theatre Music',ARRAY['Act tune','Entr''acte','Incidental music','Overture','Descriptive incidental','Curtain call']::text[],ARRAY['Confusing curtain music with the overture, which opens the whole show rather than bridging acts.','Treating it as underscore for on-stage action rather than music for the curtain-down interval.','Assuming the term is modern; ''act tune'' and ''curtain tune'' are 17th- and 18th-century usages.']::text[],ARRAY['A period-play production plays act tunes while the curtain is down between acts.','A music director cues short curtain music to cover a set change.','A revival researches original curtain tunes for authentic staging.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3c60af4e-13c8-5030-acd0-93317456a9fe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Curtain music'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3c60af4e-13c8-5030-acd0-93317456a9fe','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3c60af4e-13c8-5030-acd0-93317456a9fe' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e9320403-13c3-5a2b-8560-985d679ce96d','Cut bar','In music editing to picture, a measure (bar) removed from a cue so that the music re-aligns with a shortened or re-cut section of picture; deleting the bar (or bars) lets the cue''s hit points fall back on the intended frames after an editorial change.','A bar is one measure of music. A cut bar is a measure taken out of a cue. Editors remove it when a scene is shortened. Cutting the bar pulls the music back into line with the new picture. Key moments then still land on the right frame.','It shortens a cue by a whole measure so the score stays locked to picture after an edit trims the scene, without rewriting the whole cue. It keeps hit points on their target frames.','A music editor faced with a scene trimmed by a few seconds deletes a bar so the cue''s downbeats and hits realign with the new cut.','Music Editing',ARRAY['Cue','Hit point','Conform','Cue turnover','Bar (measure)','Editorial compression']::text[],ARRAY['Cutting a bar at a musically weak point that breaks the phrase, instead of choosing a seam that flows.','Removing a bar without checking that later hit points still align with the picture.','Confusing cutting a bar of music with a picture editor''s frame cut; the two must be matched carefully.']::text[],ARRAY['A scene is trimmed after picture lock and the music editor cuts a bar to re-sync the cue.','A cue runs slightly long against the action, so a bar is removed to tighten it.','Conforming a score to a re-cut reel requires cutting bars in several cues.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e9320403-13c3-5a2b-8560-985d679ce96d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cut bar'),'[^a-z0-9]','','g'));
