INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3b7ea775-8ff7-5434-a639-c3680a1de036','Deferred cadence','A cadence whose expected resolution to the tonic is postponed rather than delivered at the anticipated moment — the cadential dominant is reached but arrival on the tonic is withheld, and the progression is extended or restarted (closely related to the evaded cadence), sustaining harmonic tension before eventual closure.','A cadence is a chord ending that gives a sense of rest. A deferred cadence holds that rest back. The music leads you to expect the final chord, then delays it. This keeps the tension going. It is like a sentence that pauses before its last word.','It prolongs tension and forward momentum by denying the ear the resolution it expects, which composers use to keep a passage unsettled or to drive toward a later, stronger arrival.','A film composer scoring rising suspense withholds the cadence under a scene, letting the harmony hang unresolved until the dramatic payoff lands.','Music Theory',ARRAY['Cadence','Evaded cadence','Deceptive cadence','Tonic','Dominant','Resolution']::text[],ARRAY['Confusing a deferred (evaded) cadence with a deceptive cadence, where a substitute chord takes the tonic''s place at the expected moment.','Assuming the resolution never comes; it is postponed, not cancelled.','Hearing any delayed chord as a deferred cadence without a real cadential dominant setting up the expectation.']::text[],ARRAY['A suspense cue withholds resolution to keep a scene tense.','A theme repeatedly approaches closure but restarts to build toward a final arrival.','An analyst labels a passage where the expected tonic arrival is postponed.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3b7ea775-8ff7-5434-a639-c3680a1de036' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Deferred cadence'),'[^a-z0-9]','','g'));
