WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3b7ea775-8ff7-5434-a639-c3680a1de036' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6364c328-f4cb-59ff-a750-f9be023cf6a2','Descriptive incidental','Incidental music (music composed to accompany a play, film, or broadcast) that is descriptive or illustrative in intent — depicting action, character, place, or mood, or mirroring specific on-stage or on-screen events — rather than serving as neutral background or an independent concert piece.','Incidental music is music written to go with a play or film. Descriptive means it paints the action in sound. It might follow a character''s footsteps or show a storm. It tells you about the scene instead of just filling silence.','It supports the drama by illustrating what is happening — reinforcing action, place, or emotion — so the audience feels the scene more strongly than the words alone convey.','A composer scoring a stage play writes descriptive incidental passages that swell with a storm or tiptoe under a stealthy entrance, cued to the staged action.','Theatre Music',ARRAY['Incidental music','Curtain music','Underscore','Mickey-mousing','Programme music','Hit point']::text[],ARRAY['Confusing descriptive incidental music with programme music written for the concert hall, which stands alone without a staged drama.','Over-illustrating every action so the music becomes distracting rather than supportive.','Treating all incidental music as descriptive; some is neutral background or transitional.']::text[],ARRAY['A play calls for music that follows a chase across the stage.','A radio drama uses descriptive cues to signal a change of location.','A composer illustrates a character''s fear with a rising incidental figure.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6364c328-f4cb-59ff-a750-f9be023cf6a2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Descriptive incidental'),'[^a-z0-9]','','g'));
