WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6364c328-f4cb-59ff-a750-f9be023cf6a2' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9a4a90b2-0e83-57be-8f16-b07b456d60c0','Dialogue pocket','The space the score deliberately leaves for spoken dialogue — in level, frequency range, and arrangement — so that music underneath a scene does not mask the voice. The score is written and mixed to ''sit in a pocket'' around dialogue, thinning texture or clearing the vocal frequency band while speech is present.','A dialogue pocket is room left in the music for the talking. The score gets quieter or thinner while people speak. It stays out of the voice''s frequency range. This keeps the dialogue clear. It is like stepping aside so someone can get through a doorway.','It keeps dialogue intelligible over music by reserving level and frequency space for the voice, which is the highest priority in a film mix. It lets score and speech coexist without a fight.','A composer voices the arrangement away from the vocal midrange under dialogue, and the re-recording mixer dips or ducks the score so lines stay clear.','Score & Dialogue',ARRAY['Underscore','Re-recording mix','Ducking','Dialogue intelligibility','Stem','Orchestration']::text[],ARRAY['Scoring dense, busy lines in the vocal midrange under dialogue, forcing the mixer to bury the music.','Relying on the mix to fix a crowded arrangement instead of leaving space when composing.','Assuming louder music reads as more dramatic; it often just masks the dialogue.']::text[],ARRAY['A dialogue-heavy drama needs score that stays clear of the voices.','A mixer asks the composer to thin an arrangement so lines cut through.','A composer arranges a cue to open up during a key spoken line.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9a4a90b2-0e83-57be-8f16-b07b456d60c0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue pocket'),'[^a-z0-9]','','g'));
