WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9a4a90b2-0e83-57be-8f16-b07b456d60c0' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '667a434b-072b-5786-87fa-f2b09380e440','Double pass','The recording of a musical part in two separate passes (takes) that are then combined — either layered (double-tracked) to enlarge and thicken the sound, or captured as a second performance for safety and choice. On the scoring stage a section may play a cue twice so the two passes can be stacked.','A pass is one recorded take of a part. A double pass means recording it twice. The two takes are then stacked together. This makes the sound bigger and fuller. Small timing and tuning differences between the takes add width.','It thickens and widens a part by combining two performances, whose tiny natural differences create a fuller sound, and it also gives a backup take to choose from.','A scoring engineer records a string section twice and layers both passes to make a lush, large ensemble sound from a smaller group.','Recording',ARRAY['Take','Overdub','Double-tracking','Scoring stage','Stem','Punch-in']::text[],ARRAY['Expecting a double pass to fix poor intonation; stacking two out-of-tune takes makes tuning worse, not better.','Layering passes recorded with different mic setups, causing phase and tone problems.','UNSAFE: Monitoring loud brass or percussion passes at excessive levels over long sessions without hearing protection or breaks, risking noise-induced hearing loss (observe OSHA 29 CFR 1910.95 exposure limits).']::text[],ARRAY['A small string section is doubled to sound like a larger ensemble.','A composer stacks two choir passes for a fuller vocal texture.','An engineer records a safety second pass in case the first has a flaw.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='667a434b-072b-5786-87fa-f2b09380e440' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Double pass'),'[^a-z0-9]','','g'));
