INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ab8e13f4-d072-5c7b-bade-458e633f3573','Double-tonic complex','An analytical concept (introduced by Robert Bailey in his study of Wagner) describing a tonal structure in which two tonics — typically a third apart, such as relative major and minor — function together as a paired tonal centre, coexisting with neither subordinate, rather than one key simply modulating to the other.','Most music has one home key, called the tonic. A double-tonic complex has two home keys at once. They are usually close relatives, like A minor and C major. Neither one wins; they share the centre. The music can rest on either and still feel at home.','It explains passages that feel anchored to two keys at once, giving analysts a way to describe stable two-key tonal structures that a single-key model cannot capture.','A film composer exploits a double-tonic pairing to keep a theme harmonically ambiguous, letting a cue pivot between two centres to underscore an unresolved dramatic situation.','Music Theory',ARRAY['Tonic','Relative key','Modulation','Tonal ambiguity','Deferred cadence','Leitmotif']::text[],ARRAY['Treating a double-tonic complex as a simple modulation from one key to the other, rather than two co-equal centres.','Assuming the two tonics must be distantly related; they are usually a third apart, often relative major and minor.','Labelling any ambiguous passage a double-tonic complex without evidence that both tonics are structurally active.']::text[],ARRAY['An analyst describes a Wagner passage that hovers between two related keys.','A composer writes a theme that rests equally on relative major and minor.','A cue stays tonally unsettled by pairing two centres rather than resolving to one.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ab8e13f4-d072-5c7b-bade-458e633f3573' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Double-tonic complex'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
