WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ab8e13f4-d072-5c7b-bade-458e633f3573' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '17951326-4519-5b04-9675-3545e3f498ca','Editorial compression','The shortening of a scene''s or cue''s running time by picture or music editing — removing frames, shots, or bars so events happen sooner and the material fits a tighter duration. In scoring it names the reduction in time the music must span after editorial tightens the picture, and is distinct from audio dynamic-range compression.','Editorial compression means cutting a scene shorter in the edit. Frames or shots are removed so events come sooner. The music then has less time to fill. Note this is about time, not the audio effect also called compression. It is like trimming a paragraph so the same story reads faster.','It tightens pacing by removing time from a scene, which improves flow but forces the score to be re-cut to the new, shorter duration. It exists to serve storytelling rhythm.','When editorial compresses a scene, the music editor removes bars or reshapes the cue so its hit points still land after the shortened picture.','Music Editing',ARRAY['Cut bar','Conform','Editorial stretch','Hit point','Cue turnover','Music editor']::text[],ARRAY['Confusing editorial (time) compression with audio dynamic compression, which controls level, not duration.','Compressing picture without giving the music team new turnovers, so cues no longer fit.','Assuming a shorter scene needs only a faster tempo; often bars must be cut and hits re-placed.']::text[],ARRAY['A slow scene is tightened in the edit and the cue must be shortened to match.','A trailer compresses a sequence and the music is re-cut to the new length.','Editorial notes call for removing seconds from a scene after the score is written.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='17951326-4519-5b04-9675-3545e3f498ca' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Editorial compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '17951326-4519-5b04-9675-3545e3f498ca','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='17951326-4519-5b04-9675-3545e3f498ca' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c53a5eaf-7fb9-5a6f-913d-9ee9b6d197f4','Editorial stem','A stem — a submix bouncing a group of related music tracks to a single stereo or multichannel file — prepared for or used by editorial: for example a music stem delivered to picture editorial to cut against, or a temporary stem used within the edit before the final mix. It lets editors work with grouped music elements without the composer''s full session.','A stem is a submix. It bounces a group of music tracks down to one file. An editorial stem is a stem made for the editors. They cut picture against it, or use it in the edit. It gives them the music in a few simple pieces, not hundreds of tracks.','It hands editorial a manageable, grouped version of the music so editors can cut and rebalance without opening the composer''s full session, while keeping elements separable for later changes.','A composer bounces editorial stems — such as rhythm, strings, and brass — so the picture editor can adjust the music balance while cutting a scene.','Music Editing',ARRAY['Stem','Cue','Editorial compression','Re-recording mix','Cue versioning','Music editor']::text[],ARRAY['Delivering a single flat mixdown instead of separable stems, so editorial cannot rebalance the music.','Grouping stems inconsistently between cues, making them hard to use across a reel.','Confusing editorial stems, used for cutting, with final print masters delivered to the dub.']::text[],ARRAY['A picture editor cuts a montage against music stems from the composer.','Editorial needs the drums pulled down and uses a separate rhythm stem.','Temp stems are used in the edit before the final scoring mix exists.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c53a5eaf-7fb9-5a6f-913d-9ee9b6d197f4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Editorial stem'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c53a5eaf-7fb9-5a6f-913d-9ee9b6d197f4','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c53a5eaf-7fb9-5a6f-913d-9ee9b6d197f4' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b7a22b1-4c7c-5120-ba72-7412c1cf9ccd','Editorial stretch','The lengthening of a scene''s or cue''s duration in editing — holding shots longer, adding material, or time-stretching audio so the same content spans more time. In scoring it names the increase in duration the music must cover after editorial extends the picture, and is the opposite of editorial compression.','Editorial stretch means making a scene longer in the edit. Shots are held longer or material is added. Sometimes the music itself is time-stretched to fill the gap. The music now has more time to cover. It is the opposite of cutting a scene shorter.','It gives a scene more time — for pacing, breath, or added action — which forces the score to be extended or time-stretched to fit the new, longer duration.','When a scene is lengthened, a music editor extends the cue by adding bars or time-stretches a passage so the music still fills and hits the picture.','Music Editing',ARRAY['Editorial compression','Time-stretch','Conform','Cut bar','Hit point','Elastic phrase']::text[],ARRAY['Time-stretching music too far, so it develops audible artefacts and sounds unnatural.','Stretching a cue without re-checking that hit points still align with the longer picture.','Assuming a slower tempo alone fills the time, when added bars or transitions are actually needed.']::text[],ARRAY['A scene is extended after the cue is written and the music must be lengthened.','A pause is added for effect and the music editor stretches the passage to cover it.','A cue falls short of a new, longer cut and bars are added to fill it.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b7a22b1-4c7c-5120-ba72-7412c1cf9ccd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Editorial stretch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b7a22b1-4c7c-5120-ba72-7412c1cf9ccd','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b7a22b1-4c7c-5120-ba72-7412c1cf9ccd' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2317df9e-2c1f-55f4-bf3f-789457783f6a','Elastic phrase','A musical phrase written or performed with flexible internal timing so its total length can be expanded or contracted — through rubato, added or removed beats, or time-stretching — to fit changing picture timings without rewriting the material. Its elasticity lets one phrase land on differing frame targets across edits.','An elastic phrase is a musical line with stretchy timing. Its length can be pulled longer or squeezed shorter. The composer bends the timing to hit picture cues. The tune stays the same, but its length changes. It works like a rubber band around the scene.','It lets a composer fit music to picture that may still change by building phrases whose timing can flex to new hit points, rather than being locked to one exact duration.','A composer writing to an unlocked edit shapes elastic phrases that can be stretched or tightened later, so a single cue still lands its hits after picture changes.','Composition & Sync',ARRAY['Rubato','Hit point','Editorial stretch','Editorial compression','Time-stretch','Cue turnover']::text[],ARRAY['Writing rigid, tightly-locked phrases against an unlocked edit, so any picture change breaks the sync.','Stretching a phrase so far its rhythm loses shape and momentum.','Relying on time-stretch software alone instead of composing flexibility into the phrase.']::text[],ARRAY['A composer scores an edit that is still changing and needs cues that can flex.','A phrase is tightened to hit an earlier cut point after a scene is trimmed.','A cue must land the same hit at two slightly different timings across versions.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2317df9e-2c1f-55f4-bf3f-789457783f6a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Elastic phrase'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2317df9e-2c1f-55f4-bf3f-789457783f6a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2317df9e-2c1f-55f4-bf3f-789457783f6a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9cc2b8ac-4037-50ac-857a-3fcbb16afca1','Electronic sweetener','A synthesized or electronic sound element layered into a score to enhance or reinforce acoustic material, adding shimmer, weight, texture, or edge without forming the main melodic or harmonic content. It sweetens an existing orchestral or acoustic cue rather than standing alone as the lead voice.','A sweetener is an extra sound added to make a cue richer. An electronic sweetener is a synth or electronic layer. It adds shimmer, weight, or edge under the real instruments. It supports the music instead of leading it.','It exists to enhance and modernize an acoustic score, adding low-end power, high sparkle, or tension, while keeping the orchestral performance at the core.','A composer layers a soft synth pad or a sub-bass under a string cue as an electronic sweetener to add depth the orchestra alone cannot give.','Orchestration/Production',ARRAY['Underscore','Hybrid scoring','Synthesizer','Sound design','Layering','Sub-bass']::text[],ARRAY['Letting the electronic sweetener overpower the acoustic material it is meant to support.','Confusing a sweetener with a lead synth part; a sweetener reinforces rather than carries the music.','Adding sweeteners with clashing tuning or timing so they smear the orchestral sound.']::text[],ARRAY['Adding a sub-bass layer to strengthen a low orchestral hit.','Blending synth pads under strings in a hybrid score.','Reinforcing a percussion accent with an electronic layer for impact.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9cc2b8ac-4037-50ac-857a-3fcbb16afca1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Electronic sweetener'),'[^a-z0-9]','','g'));
