WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9cc2b8ac-4037-50ac-857a-3fcbb16afca1' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6ba560e1-9f6b-5c58-943f-29535d81f895','Empathetic music','In Michel Chion''s film-sound theory, empathetic music is music whose mood, tempo, and rhythm directly participate in and reinforce the emotion of the scene it accompanies, so the score openly expresses the feeling the images convey. It is defined against anempathetic music, which carries on with a marked, mechanical detachment from what is happening on screen.','Empathetic music matches the feeling of a scene. Its mood and speed follow what the characters feel. A sad scene gets slow, sad music. It is the opposite of music that ignores the mood.','It exists to guide and amplify the audience''s emotional response, aligning the score''s mood with the drama so viewers feel what the scene intends.','A composer writing an empathetic cue matches the music''s tempo and mood to the scene''s emotion, for example scoring a grieving character with slow, minor-key material.','Music-Image Relationship',ARRAY['Anempathetic music','Mickey-Mousing','Underscore','Leitmotif','Diegetic music','Spotting']::text[],ARRAY['Assuming all film music is empathetic; anempathetic scoring deliberately ignores the scene''s emotion for effect.','Confusing empathetic music with diegetic music; empathy is about matching emotion, not about the source of the sound.','Overusing obvious empathetic cues so the score feels heavy-handed or manipulative.']::text[],ARRAY['Scoring a romantic reunion with warm, lyrical strings that mirror the characters'' joy.','Choosing between empathetic and anempathetic treatment when spotting a violent scene.','Analyzing a soundtrack to describe how the music tracks the on-screen emotion.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6ba560e1-9f6b-5c58-943f-29535d81f895' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Empathetic music'),'[^a-z0-9]','','g'));
