INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '357ea2d2-52fb-5de0-93ec-9b30e22e6f4b','Expandable module','A self-contained musical block, harmonically and rhythmically stable, written so it can be repeated or extended (and trimmed) to change a cue''s length without disrupting its flow. It lets a composer fit music to picture timing that may still change late in the process.','An expandable module is a musical block built to stretch. A composer can repeat or extend it to make a cue longer. This helps when the picture length may still change. The music can grow without sounding broken.','It gives the composer flexibility to lengthen or shorten a cue late in the process, when the edit shifts, without rewriting the whole piece.','Facing a scene whose length may change, a composer writes an expandable module, such as a loopable ostinato section, that can be repeated to cover the final duration.','Cue Construction',ARRAY['Ostinato','Vamp','Holding pattern','Cue','Reconform','Hit-point map']::text[],ARRAY['Building a module that cannot loop cleanly, so extending it creates an audible seam.','Assuming an expandable module removes the need to catch hit points, which still must line up.','Making the module so static that repeating it becomes monotonous.']::text[],ARRAY['Scoring a scene whose final length is not yet locked.','Writing a loopable section to cover a variable montage.','Extending a cue quickly after a picture change.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='357ea2d2-52fb-5de0-93ec-9b30e22e6f4b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Expandable module'),'[^a-z0-9]','','g'));
