INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'efcc59a1-4fd4-5108-8c2c-e73e87085eb2','Fractional click','In click-track scoring, tempo is expressed as the number of film frames between beats, subdivided into eighths of a frame; a fractional click is a click tempo whose frame value includes a fractional part (eighths of a frame per beat, such as 12 and 2/8) rather than a whole number of frames. It provides finer tempo resolution than integer-frame clicks.','A click track sets tempo by counting film frames between beats. A fractional click uses part of a frame, not a whole number. This gives more exact tempos to fit the picture. It lets the music hit tiny timing targets.','It lets a composer fine-tune tempo in small steps so musical beats land exactly on picture events that whole-frame clicks would miss.','When a scene''s hit points fall between whole-frame tempos, the composer chooses a fractional click, such as 12 and 2/8 frames per beat, so the click lands the accents on the action.','Click/Sync Timing',ARRAY['Click track','Free timing','Hit-point map','Streamers and punches','Tempo','Frame rate']::text[],ARRAY['Reading the click-value shorthand 12-2, which is written for 12 and 2/8 frames per beat, as 12.2 frames.','Assuming clicks must be whole frames, missing the finer tempos fractional clicks provide.','Forgetting the click value depends on the film frame rate, so tempos differ at 24 versus 25 frames per second.']::text[],ARRAY['Dialing in a tempo so beats catch action that falls between whole-frame clicks.','Building a click-track cue from a timing breakdown.','Adjusting tempo slightly to improve sync without an obvious tempo change.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='efcc59a1-4fd4-5108-8c2c-e73e87085eb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fractional click'),'[^a-z0-9]','','g'));
