INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '728c163c-ae61-518c-95cb-c2bdfddf8bb1','Free timing','Free timing (recording ''free'' or ''wild'') is the practice of recording a film cue without a click track, the conductor pacing the music to the picture by feel and by visual sync aids such as streamers and punches rather than to a metronomic click.','Free timing means recording music to film without a click track. The conductor keeps time by feel while watching the picture. Visual marks on the screen help them hit key moments. It gives a more natural, flexible tempo.','It exists to let the music breathe with expressive tempo changes, freeing performances from the rigidity of a click when a scene calls for rubato and human phrasing.','For an emotional cue a composer may conduct in free timing, using streamers and punches to catch the hit points while the orchestra follows the conductor''s flexible beat.','Click/Sync Timing',ARRAY['Click track','Streamers and punches','Fractional click','Hit-point map','Rubato','Conductor']::text[],ARRAY['Thinking free timing means ignoring sync; the conductor still catches hit points using visual aids.','Assuming free timing is easier than a click, when it demands precise conducting to stay with picture.','Confusing free timing with tempo-mapped playback; free timing has no click grid at all.']::text[],ARRAY['Recording an expressive, rubato-heavy emotional cue.','Scoring a scene where a rigid click would sound mechanical.','Conducting an orchestra to picture using streamers instead of a click.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='728c163c-ae61-518c-95cb-c2bdfddf8bb1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Free timing'),'[^a-z0-9]','','g'));
