INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '868c4926-a736-5950-8e42-29dbb92e01ea','Furioso','Furioso is a musical character marking meaning ''furiously'' or ''wildly,'' calling for fast, agitated, forceful playing. In silent-film photoplay music it also names a category of agitated cue (often an ''agitato furioso'') used to accompany the most violent or frenzied on-screen action, such as fights, storms, and mob scenes.','Furioso means to play in a furious, wild way. The music is fast, loud, and stormy. In silent-film music it was a cue for the most violent action. Think fights, riots, and raging storms.','As a direction it tells performers to bring maximum agitation and force; as a photoplay category it gave accompanists ready-made music for extreme action scenes.','A silent-film organist, or a composer emulating that idiom, pulls a furioso cue to drive a chase, a battle, or a storm to its peak.','Photoplay Cue Type',ARRAY['Agitato','Hurry','General-use hurry','Misterioso','Photoplay music','Tempo marking']::text[],ARRAY['Treating furioso only as a tempo; it chiefly marks character (furious, agitated) rather than a fixed metronome speed.','Confusing furioso with a generic fast cue; it specifically conveys anger and violence, not mere speed.','Assuming it is exclusive to silent film, when furioso is a standard Italian expression marking in concert music too.']::text[],ARRAY['Accompanying a sword fight or brawl in a silent film.','Scoring a violent storm sequence in the photoplay idiom.','Reading furioso in an orchestral score as a direction to play wildly and fast.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='868c4926-a736-5950-8e42-29dbb92e01ea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Furioso'),'[^a-z0-9]','','g'));
