INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1cf134fa-6eb5-556b-a503-82d648f50671','General-use hurry','A ''hurry'' is a class of silent-film photoplay cue: fast, agitated music written to accompany rapid action such as chases, fights, and fires. A general-use (general-utility) hurry is one not tied to a specific scene type, unlike a ''fire hurry'' or an ''Indian hurry,'' so an accompanist could drop it under almost any quick, tense action.','A hurry is fast, tense music for silent-film action scenes. It fits chases, fights, and fires. A general-use hurry is not tied to one kind of scene. Players could use it for almost any quick action.','It gave theater musicians a flexible, all-purpose action cue they could apply on sight to many different fast scenes without hunting for a specialized number.','A silent-film pianist or organist keeps a few general-use hurries ready to launch the moment on-screen action speeds up.','Photoplay Cue Type',ARRAY['Hurry','Agitato','Furioso','Photoplay music','Misterioso','Cue sheet']::text[],ARRAY['Assuming every hurry is scene-specific; the general-use hurry is deliberately generic.','Confusing a hurry with a slow suspense cue; hurries are fast and agitated.','Thinking hurries were improvised from scratch, when they were published, catalogued cues selected from photoplay albums.']::text[],ARRAY['Accompanying an unspecified chase where no specialized cue fits.','Building a silent-film accompanist''s working folder of flexible cues.','Selecting music quickly from a photoplay album as the action escalates.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1cf134fa-6eb5-556b-a503-82d648f50671' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('General-use hurry'),'[^a-z0-9]','','g'));
