INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e495ba87-6156-5790-910b-d0b0fffa3185','Genre-coded cadence','A cadential (phrase-ending) harmonic or melodic formula that audiences conventionally associate with a specific genre or style, such as a modal plagal close for the pastoral or Western, or a semitone-laden minor cadence for horror, so that its use signals or reinforces that genre.','A cadence is how a musical phrase ends and resolves. A genre-coded cadence is an ending a genre is known for. A cowboy Western close or a spooky horror ending are examples. It hints to the audience what kind of film they are watching.','It lets a composer invoke a genre''s emotional world quickly by using an ending formula the audience already reads as belonging to that genre.','Scoring a Western, a composer ends phrases with open-fifth, modal cadences that listeners recognize as frontier music.','Style/Semiotics',ARRAY['Cadence','Harmonic signifier','Leitmotif','Musical topic','Genre','Underscore']::text[],ARRAY['Assuming a cadence carries fixed meaning; its genre associations are learned conventions, not acoustic facts.','Overusing a coded cadence so the genre signal becomes cliche.','Confusing a genre-coded cadence with a leitmotif; the cadence signals a style, not a specific character or idea.']::text[],ARRAY['Ending phrases in a Western with modal, open cadences.','Signaling horror with a semitone-based minor cadence.','Cueing a romantic-comedy tone through a warm, familiar cadential close.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e495ba87-6156-5790-910b-d0b0fffa3185' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Genre-coded cadence'),'[^a-z0-9]','','g'));
