SELECT 'e495ba87-6156-5790-910b-d0b0fffa3185','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e495ba87-6156-5790-910b-d0b0fffa3185' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ba542811-7331-5b48-8f81-23d97be13b8e','Global reconform','Reconforming is updating an audio session to match a revised picture edit by propagating the picture''s changes (insertions, deletions, and moves) onto the tracks. A global reconform applies these changes across the entire session timeline, all tracks at once, rather than fixing one region locally, keeping music, dialogue, and effects in sync with the new cut.','When the picture editor makes a new cut, the sound must move to match. Reconforming shifts the audio to fit the changes. A global reconform updates the whole timeline at once. This keeps music, dialogue, and effects in sync.','It exists to preserve prior editing and mixing work when the picture changes, automatically shifting all audio to the new cut instead of rebuilding by hand.','When editorial delivers a new cut, the music editor runs a global reconform, driven by a change list or edit decision list, so every track moves to match before scoring continues.','Editing/Conform',ARRAY['Conform','Change list','Edit decision list','Picture lock','Spotting','Hit-point map']::text[],ARRAY['Reconforming against an inaccurate change list, so edits land in the wrong places.','Skipping a backup before a global reconform, risking loss of prior edits.','Assuming a reconform fixes musical hit points automatically; accents often must be re-checked against the new cut.']::text[],ARRAY['Updating a scoring session after editorial sends a revised cut.','Propagating many small picture trims across all tracks at once.','Re-syncing dialogue, effects, and music after a late re-edit.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ba542811-7331-5b48-8f81-23d97be13b8e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Global reconform'),'[^a-z0-9]','','g'));
