WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ba542811-7331-5b48-8f81-23d97be13b8e' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7e6c3a4f-c4cd-5b22-b494-79d2704431c8','Harmonic signifier','A chord, progression, or harmonic gesture that functions as a semiotic sign, carrying a conventional, culturally learned meaning (a mood, place, character type, or idea) beyond its purely musical function, so that hearing it prompts the intended association in film scoring.','A signifier is something that stands for an idea. A harmonic signifier is a chord or progression that carries meaning. Certain chords can suggest danger, wonder, or a place. Composers use them so the audience feels the intended idea.','It gives the composer a compact harmonic shorthand to communicate meaning to the audience, drawing on shared listening conventions built up across film history.','A composer reaches for a familiar harmonic signifier, such as a rising, wondrous progression, to tell the audience a moment is magical without any dialogue.','Style/Semiotics',ARRAY['Leitmotif','Genre-coded cadence','Musical topic','Hexatonic pole','Underscore','Chromatic mediant']::text[],ARRAY['Treating a harmonic signifier''s meaning as universal; associations are learned and culture-specific.','Confusing a harmonic signifier with a leitmotif; a leitmotif is a recurring theme tied to one subject, not a general coded gesture.','Relying on an overfamiliar signifier so the effect reads as cliche.']::text[],ARRAY['Suggesting wonder or the supernatural with a signature progression.','Analyzing how a score conveys meaning through harmony.','Choosing a chord color that codes a location or mood for the audience.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7e6c3a4f-c4cd-5b22-b494-79d2704431c8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Harmonic signifier'),'[^a-z0-9]','','g'));
