WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7e6c3a4f-c4cd-5b22-b494-79d2704431c8' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ee326ef3-f6e8-53e9-8459-5cbbe8ecfb05','Hexatonic pole','The relationship between two consonant triads of opposite mode (one major, one minor) drawn from the same hexatonic collection, whose roots lie a major third apart and which share no common tones, connected by semitonal motion in all three upper voices. Named and theorized by Richard Cohn, it is the maximally smooth voice-leading link between two triads that nonetheless sound maximally remote, and it is widely used to evoke the uncanny.','A hexatonic pole links two chords that sound far apart but move very smoothly. One chord is major and one is minor. They share no notes. Each voice shifts by just a half step. Film composers use it for eerie, uncanny moments.','It provides a harmonic gesture that feels both smooth and strange, giving composers a reliable way to color a moment as uncanny, unstable, or otherworldly.','A film composer scoring a horror or supernatural reveal may slide between a major triad and its hexatonic pole to unsettle the listener without a jarring key change.','Harmony',ARRAY['Neo-Riemannian theory','Voice leading','Chromatic mediant','Triad','Leitmotif','Harmonic signifier']::text[],ARRAY['Confusing a hexatonic pole with an ordinary chromatic mediant; the pole specifically shares no common tones and moves all three voices by semitone.','Assuming the two triads are the same mode; a hexatonic pole always pairs a major triad with a minor one.','Treating the smooth voice leading as implying a close key relationship, when the two chords are functionally remote.']::text[],ARRAY['Scoring a supernatural or uncanny moment in a horror film.','Analyzing chromatic passages in late-Romantic and film scores.','Teaching neo-Riemannian voice leading using a major triad and its pole.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ee326ef3-f6e8-53e9-8459-5cbbe8ecfb05' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hexatonic pole'),'[^a-z0-9]','','g'));
