INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4690cde6-b651-5e02-829d-6483ed795ec0','Hit-point map','A cue-by-cue listing of the specific moments in the picture that the music must accent, the hit points or sync points, each identified by its timecode or footage. It is used to plan a cue''s tempo and structure so musical accents land on those events.','A hit point is a moment in the picture the music must catch. A hit-point map lists all of them with their exact times. Composers use it to plan a cue. It helps the music land its accents on the action.','It gives the composer a precise timing target list so the cue can be built, in tempo, meter, and accents, to catch each important on-screen moment.','After spotting, the composer or music editor prepares a hit-point map of timecodes, then chooses tempos and clicks that place musical accents on those points.','Sync/Spotting',ARRAY['Hit point','Spotting','Click track','Free timing','Streamers and punches','Cue sheet']::text[],ARRAY['Confusing a hit-point map with a cue sheet; the map lists sync moments within a cue, not licensing or cue-order data.','Trying to catch every hit, cluttering the music instead of choosing the meaningful accents.','Recording timecodes against the wrong picture version so the hits no longer line up.']::text[],ARRAY['Planning a tempo so beats catch a series of action hits.','Handing a music editor''s timing notes to the composer after spotting.','Rechecking hit-point timecodes after a picture change.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4690cde6-b651-5e02-829d-6483ed795ec0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hit-point map'),'[^a-z0-9]','','g'));
