INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cf313900-1dc2-5eb5-bc06-bfe1140aaf44','Holding pattern','In scoring and performance, a repeated or sustained musical figure (a vamp) that maintains harmonic and rhythmic continuity while marking time until a cue, downbeat, or picture event arrives, letting the music wait without stopping.','A holding pattern is music that repeats while it waits. Like a plane circling before it lands, the music loops until the right moment. It keeps going until a cue or scene change. Then the piece moves on.','It lets the music stay alive and in tempo during an uncertain or variable stretch, ready to move forward the instant the next cue lands.','A keyboardist or composer holds on a vamp until the director''s cue or the on-screen action arrives, then resolves out of the holding pattern into the next section.','Cue Construction',ARRAY['Vamp','Ostinato','Expandable module','Cue','Free timing','Hit-point map']::text[],ARRAY['Letting the holding pattern drift out of tempo, so the exit no longer lands with picture.','Making the pattern too busy or too static to loop convincingly.','Confusing a holding pattern with a fixed-length section; it must be able to repeat for an open-ended time.']::text[],ARRAY['Vamping under dialogue until an action beat arrives.','Covering a variable gap while waiting for a scene change.','Sustaining a live cue until the director calls the next section.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cf313900-1dc2-5eb5-bc06-bfe1140aaf44' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Holding pattern'),'[^a-z0-9]','','g'));
