INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc9e625b-a92c-58d5-ad72-52c9a3b0697c','Hurry','In silent-film accompaniment, a hurry is a short, fast, agitated stock cue—typically in a minor key with rapid tremolo or scalar figuration—used to underscore chases, fights, storms, and other frenzied action. Hurries were catalogued in photoplay music anthologies alongside related moods such as agitato and misterioso so accompanists could match them to on-screen action.','A hurry is a fast, tense piece of music from the silent movie days. Players used it for chases and fights. It was picked from a book of ready-made cues to fit the action.','It gave live accompanists a ready-made, high-energy musical gesture to raise tension and drive the pace of action scenes, keeping the music matched to fast on-screen events.','A silent-film accompanist pulls a hurry from a photoplay anthology and plays it under a chase, switching cues as the action changes on screen.','Photoplay cue',ARRAY['Misterioso','Agitato','Photoplay music','Underscore','Cue']::text[],ARRAY['Assuming a hurry is one specific composition rather than a whole category of interchangeable fast, agitated stock cues.','Confusing a hurry with a misterioso; a hurry drives fast action, while a misterioso underscores suspense or stealth.','Thinking hurries belong only to comedy; they underscored any frantic action, including drama and horror.']::text[],ARRAY['Accompanying a silent-era chase sequence with escalating on-screen speed.','Underscoring a fight or storm scene from a photoplay music anthology.','Studying historical silent-film accompaniment practice in a film-music course.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc9e625b-a92c-58d5-ad72-52c9a3b0697c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hurry'),'[^a-z0-9]','','g'));
