INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4273fc9f-6ac2-586b-96cc-b92dfba3b712','In-point','The in-point is the exact timecode location at which a music cue, clip, or edit is set to begin. Expressed in SMPTE hours:minutes:seconds:frames, it defines the start boundary of the cue against picture and complements the out-point, which marks its end.','The in-point is the exact spot where a music cue starts. It is marked using timecode, which is like a clock for film counted in frames. The out-point marks where the cue ends.','It fixes precisely where music begins relative to picture, so the cue starts on the intended frame and stays locked to the edit.','A composer or music editor sets a cue''s in-point on a specific frame in the digital audio workstation so playback and the click track line up with picture.','Timecode',ARRAY['Out-point','SMPTE timecode','Hit point','Spotting session','Cue']::text[],ARRAY['Confusing the in-point, where a cue starts, with the out-point, where it ends.','Setting the in-point in seconds instead of exact frames, which causes sync drift.','Forgetting that changing frame rate shifts the frame count, so a copied in-point may no longer match picture.']::text[],ARRAY['Placing a cue''s start on an exact frame at a scene change during a scoring session.','Reading spotting notes that list a timecode in-point and out-point for each cue.','Conforming cues to a re-cut where every in-point must be re-checked against new picture.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4273fc9f-6ac2-586b-96cc-b92dfba3b712' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('In-point'),'[^a-z0-9]','','g'));
