INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '07cd37ff-1af1-5edd-9717-7b8bffbd445e','Long-tail take','A long-tail take is a scoring-stage recording in which the final sustained note or chord of a cue is held and allowed to decay fully—capturing the natural instrument and room reverberation tail—rather than being cut off at the last beat. The extended tail gives the music editor material to shape the cue''s ending and smooth transitions.','A long-tail take is a recording where the last chord is left to ring out fully. The players hold it while the natural echo fades. This gives the editor room to end the cue smoothly.','It preserves the natural decay of the ending so the editor can fade, extend, or blend the cue''s tail cleanly instead of using an abrupt cutoff.','On the scoring stage, the mixer keeps recording after the last downbeat so the reverb tail is captured, giving the music editor a usable long tail for the dub.','Scoring stage',ARRAY['Scoring stage','Reverb tail','Music editor','Cue','Take']::text[],ARRAY['Cutting the recording at the final beat, leaving no natural decay for the editor to work with.','Assuming a long tail can always be added convincingly with artificial reverb, when a captured live tail sounds more natural.','Letting stage noise or talkback intrude during the tail, spoiling an otherwise clean decay.']::text[],ARRAY['Recording the last chord of an emotional cue so its decay can underscore a slow fade-out.','Capturing a long tail so the music editor can extend an ending during the final dub.','Providing a clean tail for a cue that dissolves into the next scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='07cd37ff-1af1-5edd-9717-7b8bffbd445e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Long-tail take'),'[^a-z0-9]','','g'));
