INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3ae1cc61-226b-5966-8845-897776de5551','M&E gap','In a music-and-effects (M&E) mix—the fully mixed music and sound-effects deliverable, without dialogue, used for foreign-language dubbing—an M&E gap is a passage where required audio is missing because a sound was originally carried by or tied to the production dialogue. The gap must be filled with replacement effects or music so the dubbed version is not silent where the original had sound.','An M&E track holds a film''s music and sound effects but no dialogue. It is used to dub films into other languages. An M&E gap is a hole where a needed sound is missing and must be filled.','Naming and fixing M&E gaps ensures the foreign-dubbed version keeps every music and effect sound the original had, with nothing dropping to silence when dialogue is replaced.','A re-recording mixer preparing the M&E spots gaps where an effect leaked only from the dialogue microphone and adds a replacement effect so the dub stays complete.','Deliverables',ARRAY['M&E track','Foley','Re-recording mixer','Stems','Fill']::text[],ARRAY['Assuming the M&E is complete just because music and effects stems exist, without checking for gaps left by dialogue-linked sounds.','Forgetting that an effect captured only on the dialogue track vanishes in the M&E and leaves a gap.','Delivering an M&E with gaps, which forces the foreign dub to play in silence during those moments.']::text[],ARRAY['Preparing an international M&E deliverable for a film''s foreign release.','Filling gaps with Foley or library effects where a sound rode only on the dialogue microphone.','Quality-checking an M&E mix against the original to find and patch missing audio.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3ae1cc61-226b-5966-8845-897776de5551' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E gap'),'[^a-z0-9]','','g'));
