INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'be6c8e9e-7957-5fce-a8b9-5f19fc54599f','M-number','An M-number is the standard film-scoring label that identifies a music cue by reel and sequence, written as the reel number, the letter M (for music), then the cue number—so 1M1 is the first cue of reel one and 2M3 is the third cue of reel two. It gives each cue a unique, order-preserving name shared across the score, parts, cue sheet, and recording session.','An M-number names each piece of music in a film. The M stands for music. In the label 1M1, the first number is the reel and the last is the cue order. So 1M1 means reel one, music cue one.','It gives every cue a unique, sortable name tied to its reel and position, so composer, orchestrator, music editor, and mixer all refer to the same cue without confusion.','During spotting, the music editor assigns each agreed cue an M-number, which then labels the score, the parts, the session, and the cue sheet.','Cue numbering',ARRAY['Cue','Reel','Spotting session','Cue sheet','In-point']::text[],ARRAY['Reading the cue number as a running total across the whole film instead of resetting within each reel.','Renumbering cues after a re-cut without updating parts and the session, so labels no longer match.','Confusing the M-number with the cue''s title; the number gives order and location, not content.']::text[],ARRAY['Labeling cues 1M1, 1M2, 1M3 as a spotting session works through reel one.','Organizing a scoring session''s takes and parts by M-number.','Filling out a cue sheet that lists each cue by its M-number for royalty reporting.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='be6c8e9e-7957-5fce-a8b9-5f19fc54599f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M-number'),'[^a-z0-9]','','g'));
