INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0878f68e-c25e-5713-8f3c-317170d60dd2','Macro-synchronization','Macro-synchronization is the broad, large-scale alignment of a score with picture—matching the music''s overall mood, structure, and pacing to a scene or sequence rather than to individual on-screen actions. It operates at the level of dramatic arcs and structural boundaries, complementing the moment-to-moment detail of micro-synchronization.','Macro-synchronization means matching music to a scene as a whole. The overall mood and pace fit the story. It does not chase every small action on screen.','It keeps the score emotionally and structurally aligned with the drama over long spans, supporting the scene''s shape without tying every note to a specific frame.','A composer scores a chase so the music''s overall build and release track the sequence''s rising tension, letting broad shape—not each cut—drive the writing.','Synchronization',ARRAY['Micro-synchronization','Metric synchronization','Hit point','Underscore','Spotting session']::text[],ARRAY['Confusing macro-synchronization with hitting every action; it aligns broad mood and pacing, not single events.','Believing every scene needs constant tight sync, when broad alignment often serves the drama better.','Ignoring structural sync points, so the music''s shape drifts away from the scene''s arc.']::text[],ARRAY['Scoring a montage so the music''s arc matches the sequence''s overall emotional rise.','Aligning a cue''s structure to a scene''s beginning, turn, and resolution.','Choosing broad mood-based scoring over action-by-action hits for a dialogue scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0878f68e-c25e-5713-8f3c-317170d60dd2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Macro-synchronization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0878f68e-c25e-5713-8f3c-317170d60dd2','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0878f68e-c25e-5713-8f3c-317170d60dd2' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '39303337-37d7-5809-83a3-38c49d80671f','Meter modulation for picture','Meter modulation for picture is the use of metric (tempo) modulation—resetting the pulse by equating a note value in the old tempo to a different note value in the new tempo—to realign a score''s beat grid so an upcoming picture event lands on a musical beat or downbeat. It lets the composer change the felt tempo smoothly while steering the click toward a specific hit point.','This is a way to change a score''s tempo so the beat lands on a picture moment. A note value from the old speed is set equal to one in the new speed. The pulse shifts smoothly to catch the hit.','It smoothly retimes the musical pulse so a coming sync point falls on a strong beat, letting the composer hit picture without an abrupt, jarring tempo jump.','Facing a hit a few seconds ahead that falls awkwardly between beats, a composer applies a metric modulation so the new tempo places that hit squarely on a downbeat.','Tempo and meter',ARRAY['Metric synchronization','Hit point','Click track','Tempo map','Micro-synchronization']::text[],ARRAY['Jumping to an unrelated tempo instead of pivoting on a shared note value, which breaks the smooth feel and confuses players.','Miscalculating the note-value equivalence, so the hit no longer lands on the intended beat.','Overusing tempo changes to catch every hit, making the cue hard to conduct and perform.']::text[],ARRAY['Retiming a cue so a coming cut lands on a downbeat without a jarring tempo jump.','Writing an action cue that shifts pulse to catch several hits in sequence.','Programming a click track that modulates tempo to align with picture events.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='39303337-37d7-5809-83a3-38c49d80671f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Meter modulation for picture'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '39303337-37d7-5809-83a3-38c49d80671f','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='39303337-37d7-5809-83a3-38c49d80671f' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '71091f5f-627b-5dfb-b1a9-3a55aaa84957','Metric synchronization','Metric synchronization is the alignment of music to picture through the rhythmic grid—setting tempo and meter, typically via a click track and tempo map, so that on-screen events fall on musical beats, subdivisions, or bar-lines. It contrasts with free, non-metric sync, in which a conductor lands hits by feel using streamers and punches.','Metric synchronization lines music up to picture using a steady beat grid. The tempo is set so screen events land on beats or bar lines. A click track usually keeps the players locked to that grid.','It makes picture events fall predictably on musical beats, giving tight, repeatable sync that performers can lock to through a click track.','A composer builds a tempo map so key actions land on downbeats, then records the orchestra to a click so every hit stays locked to picture.','Synchronization',ARRAY['Click track','Tempo map','Hit point','Metric modulation','Free timing']::text[],ARRAY['Assuming a click track alone guarantees sync without a tempo map that places hits on beats.','Forcing a rigid grid on an emotional cue that would breathe better with free timing.','Setting a tempo where important hits fall on weak offbeats, which weakens the sync.']::text[],ARRAY['Recording an action cue to a click so every hit lands exactly on picture.','Mapping tempo so a series of edits fall on successive downbeats.','Choosing metric, click-based sync over free conducting for a tightly cut sequence.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='71091f5f-627b-5dfb-b1a9-3a55aaa84957' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Metric synchronization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '71091f5f-627b-5dfb-b1a9-3a55aaa84957','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='71091f5f-627b-5dfb-b1a9-3a55aaa84957' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f2adc89a-7c3a-5e36-ba8f-834d4961f9b8','Micro-synchronization','Micro-synchronization is the fine, event-level alignment of specific musical gestures with individual on-screen actions—an accent, chord, or rhythmic figure placed to coincide precisely with a footstep, a punch, or a look. It is the mechanism underlying close ''Mickey-Mousing'' and detailed hit-point scoring, as opposed to the broad matching of macro-synchronization.','Micro-synchronization means matching single musical moments to single actions on screen. A note or accent lands exactly with a step or a hit. It is the close, detailed kind of syncing.','It ties individual musical events to precise on-screen moments, letting the score punctuate or mirror specific actions frame-accurately.','A composer places an orchestral stab on the exact frame a door slams, using hit points and a click so the accent and the action coincide.','Synchronization',ARRAY['Macro-synchronization','Mickey-Mousing','Hit point','Metric synchronization','Click track']::text[],ARRAY['Overusing tight event sync so the score feels cartoonish, an effect often called Mickey-Mousing.','Confusing micro-synchronization with broad mood matching, which is macro-synchronization.','Placing a hit by ear a frame or two off, so the accent and the action do not truly line up.']::text[],ARRAY['Landing a musical stab exactly as a character is struck.','Scoring slapstick where each movement gets its own musical accent.','Timing a harp glissando to a precise on-screen gesture.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f2adc89a-7c3a-5e36-ba8f-834d4961f9b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Micro-synchronization'),'[^a-z0-9]','','g'));
