WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f2adc89a-7c3a-5e36-ba8f-834d4961f9b8' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd6f99ebe-2708-5743-ac10-a798c39fa07d','Misterioso','Misterioso is an Italian expressive direction instructing music to be performed in a mysterious, veiled, suspenseful manner. In film and photoplay music it also names a stock cue type of that character—typically quiet, chromatic, and tense—used to underscore stealth, suspense, and the uncanny.','Misterioso is an Italian word meaning mysteriously. Written on a score, it tells players to sound tense and secret. In film music it also names a quiet, suspenseful cue used for creeping scenes.','As a direction it tells performers to shape a hushed, suspenseful mood; as a cue type it gave accompanists a ready mysterious underscore for tense scenes.','An accompanist plays a misterioso cue under a stealthy break-in, while a composer may write ''misterioso'' over a passage to guide its tense, veiled character.','Expression marking',ARRAY['Hurry','Agitato','Photoplay music','Underscore','Expression marking']::text[],ARRAY['Treating misterioso as a fixed tempo; it describes mood and character, not a set speed.','Confusing misterioso, meaning suspense and mystery, with a hurry, meaning fast, frantic action.','Playing it too loudly, when the mood depends on a hushed, restrained delivery.']::text[],ARRAY['Underscoring a character sneaking through a dark house.','Marking a suspense cue ''misterioso'' to guide its performance.','Selecting a misterioso from a photoplay anthology for a silent mystery scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d6f99ebe-2708-5743-ac10-a798c39fa07d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Misterioso'),'[^a-z0-9]','','g'));
