INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ce7a5b4b-f06e-5106-8871-ad0b30c8a2f2','Mixed plagal cadence','A mixed plagal cadence is a plagal cadence (subdominant to tonic, IV–I) in which the subdominant is drawn from the parallel minor through modal mixture—most often a minor iv, or a half-diminished ii chord, resolving to a major tonic. The borrowed, flattened sixth scale degree lends a bittersweet color, and the gesture is a hallmark of classical Hollywood and end-title scoring.','A plagal cadence moves from the four chord to the one chord, the classic ''Amen'' ending. A mixed plagal cadence borrows a darker minor version of that four chord. It sounds sweet but sad, a favorite film ending.','It provides harmonic closure with a warm, bittersweet, nostalgic color, which is why it recurs at film endings, studio logos, and emotional resolutions.','A composer ends a love-theme cue with a minor iv resolving to the major tonic, using the mixed plagal cadence to close on a tender, wistful chord.','Harmony',ARRAY['Plagal cadence','Modal mixture','Cadence','Borrowed chord','Tonic']::text[],ARRAY['Calling any IV–I motion a mixed plagal cadence; the subdominant must be borrowed from the parallel minor.','Confusing it with the authentic cadence (V–I); the plagal uses the subdominant, not the dominant.','Spelling the borrowed chord as major, which loses the flattened sixth that gives the cadence its color.']::text[],ARRAY['Ending an emotional end-title cue on a warm, bittersweet resolution.','Scoring a tender scene that closes with a borrowed minor iv to major I.','Analyzing a classic Hollywood score''s cadential harmony in a film-music class.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ce7a5b4b-f06e-5106-8871-ad0b30c8a2f2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mixed plagal cadence'),'[^a-z0-9]','','g'));
