INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b482df9c-639b-59a3-8a79-c199bdeb3b9e','Modular scoring','Modular scoring is a composing approach in which music is written as discrete, self-contained blocks or layers—intros, loops, transitions, and stingers—that can be reordered, combined, looped, or muted to fit changing picture timings or branching narratives. It trades fixed, through-composed cues for reconfigurable modules, making the music adaptable to re-cuts, trailers, and interactive media.','Modular scoring writes music in separate building blocks. Each block can be moved, looped, or stacked to fit the picture. This makes the music easy to rearrange when the edit changes.','It lets one set of musical pieces be reassembled to fit many timings or story branches, so the score adapts quickly to re-cuts and interactive needs without rewriting.','A composer delivers a cue as separate layers and loop-able sections so the editor can extend, shorten, or restructure the music to match a re-cut scene.','Composition approach',ARRAY['Cue','Stems','Loop','Stinger','Underscore']::text[],ARRAY['Assuming modules will fit together seamlessly without composing consistent tempo, key, and transitions between them.','Confusing modular scoring with simply looping one section; it relies on multiple interchangeable blocks.','Forgetting to design clean entry and exit points, so modules cannot be recombined without audible seams.']::text[],ARRAY['Scoring a trailer so sections can be reordered to fit a fast re-cut.','Delivering interchangeable music blocks for a TV episode with shifting timings.','Building adaptive, loop-based music whose modules recombine to fit different scene lengths.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b482df9c-639b-59a3-8a79-c199bdeb3b9e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Modular scoring'),'[^a-z0-9]','','g'));
