INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '62ab5069-905b-5ffd-998a-a8945e42b6dc','Modular silent-film score','Accompaniment for a silent film assembled from short, self-contained musical modules — pre-composed pieces or library cues catalogued by mood, action, or scene type — that an accompanist or arranger selects, orders, and links to fit each dramatic moment and the film''s varying scene lengths. Rather than a single through-composed work, the score is built and rebuilt from interchangeable numbers, often drawn from photoplay-music anthologies and guided by cue sheets.','A silent film had no recorded sound. Musicians played live music with it. A modular score is built from many short pieces. Each piece fits a mood, like a chase or a love scene. The player picks and joins them to match what is on screen.','It let accompanists cover films of any length and mood quickly by reusing catalogued cues, giving flexible, scene-appropriate music without composing a whole new work for every picture.','A theatre organist or pit conductor pulls hurry, misterioso, or love numbers from photoplay albums and cue sheets, then sequences and repeats them live to match the on-screen action.','Silent-Era Scoring',ARRAY['Photoplay music','Cue sheet','Compilation score','Temp music','Underscore','Spotting']::text[],ARRAY['Assuming every silent film had a single fixed, composer-written score rather than a flexible compilation assembled locally.','Ignoring key relationships when linking numbers, so joined modules clash instead of connecting in the same or related keys.','Confusing the original photoplay-album cues with modern re-recorded silent-film scores composed as one continuous work.']::text[],ARRAY['A theatre organist accompanying a 1920s feature from mood-indexed photoplay albums.','A silent-film festival music director assembling a period-authentic compilation score.','An archivist cataloguing the cue sheet and library numbers used for a restored silent print.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='62ab5069-905b-5ffd-998a-a8945e42b6dc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Modular silent-film score'),'[^a-z0-9]','','g'));
