INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8cdb8ccf-0913-5d18-9c91-bffe3b4652e6','Music editorial master','The definitive, fully conformed music edit maintained by the music-editorial department: a master session or delivery in which every cue is placed, trimmed, and synchronised to the final locked picture, serving as the authoritative reference version from which stems, mixes, and cue sheets are derived.','Music editorial is the team that places music against the picture. Their master is the final, correct version of all the cues. Every cue sits at the right spot and length. Other versions and mixes are made from this master. It is the copy everyone trusts.','It provides one authoritative, picture-locked version of the score so the re-recording mix, stems, and paperwork all reference the same edit, preventing sync drift and version confusion.','Before the dub, the music editor conforms every cue to the locked picture and delivers the music editorial master to the mix stage as the reference for balancing music with dialogue and effects.','Music Editorial',ARRAY['Music editor','Conform','Cue','Stem','Dubbing','Music slip']::text[],ARRAY['Mixing from an out-of-date session instead of the current conformed master after a picture change.','Failing to re-version the master when the edit changes, so cues drift out of sync with the new picture.','Confusing the music editorial master with the composer''s original mockups or the final printmaster mix.']::text[],ARRAY['Delivering the conformed score to the re-recording stage for the final mix.','Regenerating stems and a cue sheet from the approved music master.','Reconforming the master after the picture editor delivers a new locked cut.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8cdb8ccf-0913-5d18-9c91-bffe3b4652e6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Music editorial master'),'[^a-z0-9]','','g'));
