WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8cdb8ccf-0913-5d18-9c91-bffe3b4652e6' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2052f5bb-5797-544f-8377-8e55ef107d9b','Music editorial toolkit','The collection of tools, materials, and techniques a music editor uses to place and synchronise music to picture — including timecode, streamers and punches, click tracks, tempo maps, spotting notes, and the DAW sessions used to edit, conform, and deliver cues.','A music editor lines music up with the picture. Their toolkit is the set of tools they use for this. It includes timecode and visual streamers and punches that cue the conductor. It also includes click tracks and editing software. These tools help the music hit the right moments.','It gives the music editor reliable, frame-accurate means to sync, cue, and conform music, so performances and edits land precisely against the picture and the composer''s intent.','On a scoring session, the music editor uses the toolkit — click tracks, streamers, punches, and timecode — to guide the conductor and orchestra to hit key sync points on screen.','Music Editorial',ARRAY['Streamer','Punch','Click track','Time code','Music editor','Spotting']::text[],ARRAY['Thinking a DAW alone replaces streamers and punches on a live scoring stage.','Neglecting an accurate tempo map, so the click and the picture sync points do not align.','Confusing SMPTE timecode reference with musical bar-and-beat position when placing cues.']::text[],ARRAY['Preparing streamers and punches for a live orchestral scoring session.','Building a click track and tempo map so a cue hits on-screen action.','Conforming cues in the DAW after a reel is re-cut.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2052f5bb-5797-544f-8377-8e55ef107d9b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Music editorial toolkit'),'[^a-z0-9]','','g'));
