INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4923dd73-03cb-561a-8f00-3ffbf2d161c9','Music entrance rationale','The dramatic and structural justification for where a musical cue begins — the reasoning, established in spotting, for the exact moment score enters a scene so that its entrance supports the story, respects dialogue and sound effects, and feels motivated rather than arbitrary.','A cue is a piece of score for one scene. The entrance is where that music starts. The rationale is the reason it starts there. Good timing supports the story and stays out of the dialogue''s way. A poor entrance can feel sudden or distracting.','It ensures music starts for a story reason rather than by accident, so entrances feel motivated, protect the intelligibility of dialogue, and shape the audience''s emotional response.','During spotting, the composer, director, and music editor decide and note exactly where each cue enters and why, then the editor marks that entrance timecode for scoring.','Spotting',ARRAY['Spotting','Cue','Music exit rationale','Underscore','Sneak (music)','Music editor']::text[],ARRAY['Starting a cue on a hard cut by default instead of where the drama motivates it.','Entering music under a key line of dialogue and masking its intelligibility.','Confusing a subtle sneak-in entrance with an abrupt stinger entrance.']::text[],ARRAY['A spotting session deciding where score should first enter a scene.','Choosing to sneak music in under ambience rather than on a picture cut.','Revisiting an entrance point after the dialogue is re-edited.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4923dd73-03cb-561a-8f00-3ffbf2d161c9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Music entrance rationale'),'[^a-z0-9]','','g'));
