INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1770ea8b-7d0a-5b8f-88b0-3e59b2e1f196','Music exit rationale','The dramatic and structural justification for where a musical cue ends — the reasoning, established in spotting, for the exact moment score leaves a scene, whether by a resolved button, a tail-out fade, or a hard cut, so the exit supports the story and hands the scene cleanly to dialogue or effects.','The exit is where a cue''s music stops. The rationale is the reason it stops there. Music might end on a strong beat, fade out slowly, or cut on an action. A good exit hands the scene back to the dialogue or sound. A clumsy exit can feel like the music was chopped off.','It ensures music ends for a story reason, so cues resolve or clear at the right moment, making room for dialogue and effects and shaping how a scene releases tension.','In spotting, the team decides where and how each cue ends, and the music editor marks the exit point and shape — button, fade, or cut — for editing and mixing.','Spotting',ARRAY['Spotting','Cue','Music entrance rationale','Tail (music)','Underscore','Music editor']::text[],ARRAY['Fading every cue out by default instead of choosing an exit the drama calls for.','Ending a cue so late it fights the next scene''s dialogue or a hard sound effect.','Confusing a resolved musical button with an abrupt edit-driven cut-off.']::text[],ARRAY['Deciding whether a cue buttons cleanly or tails out under the next scene.','Timing a cue''s exit to clear space for an important line.','Reworking an exit after the picture cut moves.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1770ea8b-7d0a-5b8f-88b0-3e59b2e1f196' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Music exit rationale'),'[^a-z0-9]','','g'));
