INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '51334d31-38ae-56ed-8fa4-bc9264b2c30c','Music slip','A time shift of a music cue relative to picture — moving the whole cue, or a section of it, earlier or later against the timeline without altering its internal content — used to realign musical hit points with on-screen action after an edit or to improve sync.','Slipping means sliding a music cue earlier or later. The music itself does not change. Only its position against the picture moves. Editors slip a cue so its big moments land on the action. It is a common fix after the picture is re-cut.','It lets a music editor realign a cue''s accents and phrases to picture without re-editing the music internally, fixing sync when the film is re-cut or when a hit point misses.','When a scene is trimmed and a musical accent no longer lands on the cut, the music editor slips the cue a few frames until the hit realigns with the action.','Music Editorial',ARRAY['Conform','Hit point','Cue','Music editor','Time code','Music editorial master']::text[],ARRAY['Slipping a cue to fix one hit while knocking several other sync points off elsewhere.','Slipping the picture-relative position when the real fix needs an internal edit or re-time.','Forgetting to re-check downstream cues after slipping the master alignment.']::text[],ARRAY['Realigning a stinger to a newly trimmed action beat.','Nudging a cue a few frames so its downbeat hits a cut.','Conforming music after the editor delivers a revised reel.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='51334d31-38ae-56ed-8fa4-bc9264b2c30c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Music slip'),'[^a-z0-9]','','g'));
