INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '09049577-adb1-58cc-bf41-49631a16e750','Music-and-effects compatibility','The degree to which a film''s music and effects are produced and kept separable so that a clean Music & Effects (M&E) deliverable — the full soundtrack minus the original dialogue — can be created for foreign-language dubbing, ensuring music and effects remain complete and continuous when the dialogue is removed.','M&E stands for music and effects. It is the soundtrack with the voices taken out. Compatibility means the music and effects can stand on their own cleanly. Nothing important should disappear when the dialogue is removed. This lets a dubbing team add new-language voices.','It exists so a film can be localised: keeping music and effects on separate, self-sufficient stems lets distributors replace dialogue in any language without losing score or sound design.','The music editor and re-recording mixer keep score and effects on stems that hold up without dialogue, so a compliant M&E can be delivered to distributors for foreign versioning.','Deliverables',ARRAY['Music and effects track','Stem','Dialogue','Dubbing','Fully-filled M&E','Re-recording mixer']::text[],ARRAY['Leaving score elements buried under dialogue so the M&E has gaps when the voices are removed.','Assuming a finished stereo mix can be split into a clean M&E after the fact without proper stems.','Confusing an M&E-compatible stem set with the final dialogue-inclusive printmaster.']::text[],ARRAY['Preparing a score for international distribution and dubbing.','Delivering separate music and effects stems to meet a distributor''s M&E spec.','Fixing a mix where music dropped out under the original dialogue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='09049577-adb1-58cc-bf41-49631a16e750' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Music-and-effects compatibility'),'[^a-z0-9]','','g'));
