INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '825b0799-efa5-5744-bf1a-97d77e9f6eff','Musical primer','An introductory instructional text or reference that presents the rudiments of music — notation, pitch, rhythm, intervals, scales, and basic terminology — in an elementary, self-contained form intended for beginners.','A primer is a beginner''s guide to a subject. A musical primer teaches the basics of music. It covers reading notes, counting rhythm, and simple terms. It is written for people just starting out. Think of it as a first textbook for music.','It gives newcomers a structured foundation in music fundamentals so they can read notation and grasp basic terms before advanced study or practice.','A student or self-teacher works through a musical primer to learn to read the staff, count rhythms, and name intervals before studying harmony or an instrument.','Music Fundamentals',ARRAY['Music notation','Rudiments','Interval','Scale','Rhythm','Method book']::text[],ARRAY['Treating a primer''s simplified rules as exhaustive rather than a starting foundation.','Skipping the rhythmic and notational basics a primer builds before moving to harmony.','Confusing a primer, an elementary reference, with a full method or theory course.']::text[],ARRAY['A beginner learning to read music from an introductory primer.','A teacher assigning a primer to cover rudiments before ensemble work.','A self-taught musician reviewing fundamentals from a music primer.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='825b0799-efa5-5744-bf1a-97d77e9f6eff' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Musical primer'),'[^a-z0-9]','','g'));
