INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cc486e8c-769b-5b31-9b13-c97005d98b0e','Narrative handoff','The point at which responsibility for carrying the story or emotion passes from one soundtrack element to another — for example from dialogue or source music to underscore, or from one cue to the next — managed so the transition feels seamless and the narrative thread is never dropped.','A film tells its story through pictures, words, sound, and music. A narrative handoff is when one of these takes over from another. For example, music may pick up the feeling as the dialogue ends. A smooth handoff keeps the story flowing. A rough one leaves a gap or a clash.','It keeps the storytelling continuous across changing elements, so emotional engagement is sustained as focus shifts between dialogue, effects, source music, and score.','A composer and music editor time a cue to enter as key dialogue finishes, letting the underscore carry the scene''s emotion forward without a dead spot.','Spotting',ARRAY['Underscore','Source music','Diegetic music','Music entrance rationale','Spotting','Cue']::text[],ARRAY['Overlapping elements so both dialogue and score compete instead of handing off cleanly.','Leaving a silent gap where neither element carries the scene''s emotion.','Confusing a narrative handoff with a simple crossfade between two cues.']::text[],ARRAY['Bringing score in as a conversation ends to carry the emotion.','Transitioning from on-screen source music to underscore across a scene change.','Handing a chase''s energy from sound effects to a driving cue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cc486e8c-769b-5b31-9b13-c97005d98b0e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Narrative handoff'),'[^a-z0-9]','','g'));
