INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9323c3c-f02b-51d1-ab9b-3f154b5a5c95','Neo-Riemannian transformation','An operation in neo-Riemannian theory that maps one consonant triad to another by the smallest possible (parsimonious) voice leading, without reference to a tonic key. The three basic transformations are P (Parallel: hold the root and fifth, move the third by a semitone, e.g. C major to C minor), L (Leittonwechsel or leading-tone exchange: hold the third and fifth, move the root by a semitone, e.g. C major to E minor), and R (Relative: hold the root and third, move the fifth by a whole tone, e.g. C major to A minor); chained together they model the chromatic third-related progressions common in late-Romantic and film music.','A triad is a three-note chord. These operations turn one triad into a nearby one. They do it by moving just one note a tiny step. Because the change is so small, the shift sounds smooth. Film composers use them for a floating, magical harmony.','It provides a way to describe and generate chord changes that move by common tones and small steps rather than by key-based function, explaining the smooth chromatic shifts prized in film and late-Romantic scoring.','A composer or analyst uses P, L, and R moves to build or explain the wonder-and-mystery harmonic slides — for example major-third-related chords — heard in fantasy and science-fiction scores.','Film-Music Theory',ARRAY['Triad','Voice leading','Chromatic mediant','Common-tone modulation','Parallel chord','Leading tone']::text[],ARRAY['Forcing key-based Roman numerals onto parsimonious chromatic-third moves that neo-Riemannian operations describe better.','Mislabelling the operations by swapping which of P, L, and R holds which common tones.','Assuming the transformations require a home key, when they are defined independently of a tonic.']::text[],ARRAY['Analysing a chromatic-mediant progression in a fantasy film cue.','Composing a slowly shifting, wondrous harmonic bed from P/L/R chains.','Teaching how smooth voice leading explains late-Romantic and film harmony.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9323c3c-f02b-51d1-ab9b-3f154b5a5c95' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Neo-Riemannian transformation'),'[^a-z0-9]','','g'));
