INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '284af48a-561f-5fe1-937f-14fb4f58eea6','Neutral bar','A measure of deliberately non-committal musical material — harmonically and melodically neutral, avoiding a strong cadence, key statement, or thematic gesture — placed to bridge or hold a passage, giving flexibility to adjust timing, transition between sections, or accommodate a picture edit.','In music, a bar is one measure of time. A neutral bar is a measure that stays plain on purpose. It does not push a strong melody or a firm key. Composers use it to bridge two ideas or to buy timing room. It keeps their options open against the picture.','It gives a composer or music editor a flexible, non-committal measure of music to smooth a transition, pad or trim timing, or connect sections without committing to a strong harmonic or thematic statement.','A composer inserts a neutral bar to bridge two cues, or to give the music editor a place to add or remove time when conforming to picture.','Compositional Technique',ARRAY['Bar (music)','Transition','Underscore','Vamp','Conform','Music slip']::text[],ARRAY['Filling a neutral bar with a memorable motif, defeating its purpose as a plain connector.','Assuming a neutral bar can absorb any amount of timing change without musical awkwardness.','Confusing a neutral bridging bar with a fully developed transitional passage.']::text[],ARRAY['Bridging between two thematic sections without a strong statement.','Giving the music editor a bar to add or cut time when conforming.','Holding harmony neutral under a line of dialogue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='284af48a-561f-5fe1-937f-14fb4f58eea6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Neutral bar'),'[^a-z0-9]','','g'));
