INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '09837705-f813-5b0a-b04e-6a349e868756','Neutral music','Underscore or source music written to carry little or no strong emotional or stylistic character — neither reinforcing nor opposing a scene''s overt emotion — so it functions as an unobtrusive background bed rather than steering the audience''s feeling.','Most film music pushes a feeling, like sadness or fear. Neutral music does not. It stays in the background without a strong mood. It can fill a room or a radio without pulling focus. Editors use it when a scene should not feel steered by music.','It supplies music that sets place or fills space without dictating emotion, useful where the drama should read plainly or where source music must sound incidental.','A music editor drops neutral cues under a busy office or a diegetic radio so the setting feels alive without the score commenting on the characters'' feelings.','Underscore',ARRAY['Underscore','Source music','Diegetic music','Production music','Temp music','Neutral bar']::text[],ARRAY['Choosing a strongly emotional cue where the scene calls for genuinely neutral background music.','Assuming neutral means characterless or low quality rather than deliberately understated.','Confusing neutral source music with dramatic underscore that comments on the action.']::text[],ARRAY['Scoring a public space where music should sound incidental, not dramatic.','Filling a diegetic radio or television with unobtrusive background music.','Keeping a scene emotionally open by avoiding a leading cue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='09837705-f813-5b0a-b04e-6a349e868756' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Neutral music'),'[^a-z0-9]','','g'));
