INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '38b4217a-cad3-5932-895a-1985a0d7fac5','No-melody mix','An alternate mix or stem of a music cue with the lead melodic line removed, leaving harmony, rhythm, and texture, so the cue can sit under dialogue or narration without the tune competing, or so a different melodic element can be placed on top.','A tune, or melody, is the main line you hum. A no-melody mix takes that line out. The rhythm and chords stay in. This version sits nicely under talking. It also leaves room to add a new melody later.','It gives editors a version of a cue that supports a scene without a foreground tune, so music can underscore dialogue or voiceover without clashing, and so libraries can offer flexible alternates.','A television or trailer editor uses the no-melody mix under a voiceover so the narration stays clear while the music still drives the scene.','Deliverables',ARRAY['Stem','Underscore','Alternate mix','Production music','No-percussion mix','Music and effects track']::text[],ARRAY['Muting only the melody instrument''s fader and leaving its bleed or doublings in the mix.','Assuming a no-melody mix is automatically dialogue-safe without checking the remaining midrange content.','Confusing a no-melody underscore mix with a full instrumental that still contains the tune.']::text[],ARRAY['Placing music under a narrator without the melody fighting the voice.','Delivering library alternates so editors can pick with or without the tune.','Freeing space to add a new vocal or solo line over an existing cue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='38b4217a-cad3-5932-895a-1985a0d7fac5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('No-melody mix'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '38b4217a-cad3-5932-895a-1985a0d7fac5','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='38b4217a-cad3-5932-895a-1985a0d7fac5' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e5f81c6a-6596-58bd-95d7-f7b5ec3c177a','No-percussion mix','An alternate mix or stem of a music cue with the percussion and drum elements removed, leaving melodic and harmonic content, used when rhythmic transients would clash with dialogue, sound effects, or a scene''s pacing, or when a different rhythmic feel is wanted.','Percussion means drums and other rhythm-hit instruments. A no-percussion mix takes those out. The melody and chords stay. Editors use it when drums would fight the dialogue or sound effects. It gives a softer, less driving version of the cue.','It provides a version of a cue without rhythmic transients, so music can underscore dialogue or delicate scenes without drum hits masking speech or colliding with effects.','A re-recording mixer switches to the no-percussion mix under a tense dialogue scene so drum hits do not fight the words or the sound design.','Deliverables',ARRAY['Stem','Underscore','Alternate mix','No-melody mix','Production music','Music and effects track']::text[],ARRAY['Removing percussion but leaving percussive transients in other stems, so the mix still fights dialogue.','Assuming no-percussion always means calmer, when driving harmony can still crowd a scene.','Confusing a no-percussion mix with a fully stripped underscore or a music-and-effects stem.']::text[],ARRAY['Underscoring a dialogue scene where drum hits would mask speech.','Delivering a percussion-free alternate for a distributor or editor.','Softening a cue''s drive for a more intimate moment.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e5f81c6a-6596-58bd-95d7-f7b5ec3c177a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('No-percussion mix'),'[^a-z0-9]','','g'));
