WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e5f81c6a-6596-58bd-95d7-f7b5ec3c177a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '82dd6e19-37bb-588f-901b-d75b637dff9a','Open ending','In film scoring, a cue ending that does not come to rest on a stable, final cadence, leaving the harmony or melody unresolved so the music can flow directly into the next scene, dialogue, or cue. It is the opposite of a closed or ''button'' ending, which finishes with a clear point of resolution.','An open ending is a music cue that stops without a clear finish. The last chord feels unsettled, not final. This lets the music slide straight into the next scene. A closed ending, by contrast, lands on a solid last note.','It keeps musical momentum flowing across a scene change, avoiding a sense of finality where the story is meant to continue and letting one cue lead naturally into the next.','A composer writes an open ending when a cue must lead into the following scene or overlap the next cue, so the editor and mixer can blend them without an abrupt stop.','Cue Structure',ARRAY['Out-point','Cue','Segue','Spotting','Underscore']::text[],ARRAY['Assuming every cue must end on a resolved final chord, which can make scene transitions feel abrupt.','Confusing an open ending with simply fading a cue out; an open ending is composed to stay unresolved, not just lowered in volume.','Writing an open ending so unresolved that it sounds like a mistake rather than an intentional bridge to the next scene.']::text[],ARRAY['Scoring a cue that must lead directly into the next scene without a musical full stop.','Writing music that overlaps or hands off to the following cue during a segue.','Underscoring continuous action across an edit where a resolved ending would feel too final.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='82dd6e19-37bb-588f-901b-d75b637dff9a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Open ending'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '82dd6e19-37bb-588f-901b-d75b637dff9a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='82dd6e19-37bb-588f-901b-d75b637dff9a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'efdee9c0-12c3-5e2b-806a-66690de3ddac','Orchestral handoff','An orchestration technique in which a melodic line, motif, or sustained note is passed from one instrument or section to another, often with a brief overlap (dovetailing), so the musical line continues seamlessly across a change of timbre. The listener perceives one continuous line even though different instruments play successive portions of it.','An orchestral handoff passes a tune from one instrument to another. Think of runners passing a baton in a relay race. Often the two players overlap for a moment so there is no gap. The melody sounds like one smooth line, even though the color changes.','It lets a melodic line continue beyond the range, breath, or bowing limits of a single instrument and adds shifting tone color, keeping long lines alive and varied.','An orchestrator marks a handoff so a phrase can begin in the clarinet and continue in the oboe with a short overlap, and the copyist and players know exactly where the line passes.','Orchestration',ARRAY['Orchestration thinning','Perspective orchestration','Doubling','Voice leading','Underscore']::text[],ARRAY['Handing the line off with no overlap, leaving an audible seam or gap where the timbre changes.','Passing a line to an instrument whose range or dynamic cannot match the previous one, so the line drops out or jumps in level.','Forgetting to mark the handoff in the parts, so players do not know who carries the line.']::text[],ARRAY['Continuing a long melody past the breath limit of a single wind player.','Shifting tone color mid-phrase by moving a line from strings to woodwinds.','Passing a sustained pedal note between sections so it never breaks.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='efdee9c0-12c3-5e2b-806a-66690de3ddac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Orchestral handoff'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'efdee9c0-12c3-5e2b-806a-66690de3ddac','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='efdee9c0-12c3-5e2b-806a-66690de3ddac' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '553105e1-02af-5346-bec9-88ab3342cda1','Orchestral sweetener','A supplementary orchestral element, often a small group of live strings, brass, or woodwinds, layered onto an existing arrangement, sampled mockup, or pop or electronic production to enrich and ''sweeten'' its sound. The added acoustic parts enhance realism, warmth, and emotional depth without forming the primary arrangement.','A sweetener is a small live orchestra part added on top of a track. It makes a mostly electronic or sampled piece sound richer and more real. Adding a few live strings is like adding real fruit to a plain dessert. The main track stays; the live parts just lift it.','It adds the warmth, detail, and human feel of real players to a production built mainly from samples or a rhythm track, raising perceived production value at limited cost.','A composer records a handful of live string or brass players to overdub onto a sampled orchestral mockup, blending them in the mix so the cue sounds like a full live ensemble.','Scoring Production',ARRAY['Orchestration thinning','Orchestral handoff','Overdub','MIDI mockup','Doubling']::text[],ARRAY['Recording sweetener parts without a click or guide track, so they will not line up with the sampled arrangement.','Adding so many sweetener layers that the mix becomes cluttered instead of enhanced.','Expecting a small sweetener section to sound like a full orchestra rather than to reinforce one.']::text[],ARRAY['Overdubbing live strings onto a sampled cue to add realism.','Adding a live brass section to a pop or electronic track for a film trailer.','Reinforcing a synth pad with a few real players to warm the sound.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='553105e1-02af-5346-bec9-88ab3342cda1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Orchestral sweetener'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '553105e1-02af-5346-bec9-88ab3342cda1','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
