INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f8a15143-9e14-52bc-88eb-e801dea4ff06','Orchestration thinning','The deliberate reduction of the number of instruments, doublings, or active voices in a passage so the texture becomes lighter and more transparent. Thinning lowers density and dynamic weight, opens space in the frequency spectrum, and clarifies the most important lines.','Orchestration thinning means taking instruments out of a passage. Fewer players make the music lighter and clearer. It is like quieting a crowded room so one voice stands out. Composers thin the texture to make space, often under dialogue.','It controls texture and dynamics and clears sonic space, often so the music does not fight dialogue or sound effects, while highlighting the lines that matter most.','When a cue is masking dialogue, the composer or orchestrator thins it by cutting doublings or dropping inner parts, leaving a lighter arrangement that sits under the voice.','Orchestration',ARRAY['Orchestral handoff','Perspective orchestration','Doubling','Underscore','Ducking']::text[],ARRAY['Thinning by simply lowering the fader instead of removing instruments, which keeps the texture busy under dialogue.','Removing the wrong voices and accidentally cutting the line that carries the melody or harmony.','Over-thinning so the cue loses its intended emotional weight.']::text[],ARRAY['Lightening a cue so it does not mask dialogue.','Reducing texture for an intimate scene after a big passage.','Clearing low-end space so the music does not clash with sound effects.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f8a15143-9e14-52bc-88eb-e801dea4ff06' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Orchestration thinning'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f8a15143-9e14-52bc-88eb-e801dea4ff06','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f8a15143-9e14-52bc-88eb-e801dea4ff06' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aabc80d3-643e-5419-847c-983b076458a2','Out-point','The exact frame, timecode, or edit position at which a clip, cue, or edit ends, the counterpart to the in-point, which marks where it begins. In scoring and editing, the out-point defines the last frame included and thus the precise moment a cue or shot stops.','The out-point is the exact spot where a clip or music cue ends. The in-point is where it starts. Together they mark the beginning and end, like bookmarks around a section. Editors set out-points by frame or timecode so cuts land in the right place.','It precisely defines where a cue or clip ends so music, picture, and sound can be trimmed and aligned to the frame during editing and scoring.','A composer notes a cue''s out-point in timecode so it ends exactly on a scene change, and an editor sets in- and out-points to trim a clip before placing it in the timeline.','Editing',ARRAY['In-point','Open ending','Cue','Timecode','Spotting','Hit point']::text[],ARRAY['Confusing the out-point with the in-point and trimming the wrong end of a clip.','Forgetting that the out-point is the last included frame, causing an off-by-one-frame error.','Setting an out-point at the wrong timecode frame rate, so the cue ends at the wrong moment.']::text[],ARRAY['Marking where a music cue must stop, on a cut or line of dialogue.','Trimming a sound or picture clip to a precise frame in an editing timeline.','Spotting a film and logging in- and out-points for each cue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aabc80d3-643e-5419-847c-983b076458a2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Out-point'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'aabc80d3-643e-5419-847c-983b076458a2','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aabc80d3-643e-5419-847c-983b076458a2' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bb0862e4-55d8-5e44-90ca-743134fab2b2','Pan-triadic writing','A harmonic approach in which consonant major and minor triads are connected by chromatic, non-diatonic root motions that are not governed by a single tonic or key. Progressions move freely among triads through chromatic-mediant and other neo-Riemannian transformations, producing the lush, floating, ''wondrous'' color associated with much Hollywood and epic film scoring.','Pan-triadic writing uses ordinary major and minor chords. But it links them in ways that ignore one home key. The chords slide by surprising, colorful steps. This gives the shimmering, awe-filled sound heard in many big film scores.','It lets composers create rich, surprising harmonic color and a sense of wonder or vastness while still using familiar consonant triads, freeing harmony from the pull of a single key.','A film composer scoring a reveal or a magical moment slides between triads a chromatic mediant apart to evoke awe, rather than using standard key-based chord progressions.','Harmony',ARRAY['Chromatic mediant','Voice leading','Neo-Riemannian transformation','Perspective orchestration','Underscore']::text[],ARRAY['Assuming the passage is in one key and mislabeling chords with Roman numerals that do not fit.','Confusing pan-triadic motion with simple modulation, when it is really key-independent triad-to-triad movement.','Overusing chromatic-mediant slides so the effect loses its surprise and sense of wonder.']::text[],ARRAY['Scoring a sense of awe, wonder, or the supernatural in a fantasy or science-fiction film.','Writing a magical reveal where standard key-based harmony would feel too grounded.','Analyzing a Hollywood cue whose chords do not follow one key.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bb0862e4-55d8-5e44-90ca-743134fab2b2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pan-triadic writing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bb0862e4-55d8-5e44-90ca-743134fab2b2','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bb0862e4-55d8-5e44-90ca-743134fab2b2' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd51fc4f9-552a-5c0d-a41a-41ffda446c32','Parametric synchronization','A form of music-to-picture synchronization in which a continuously variable musical parameter, such as tempo, dynamics, register, or textural density, is made to track a continuously changing property of the on-screen action rather than marking a single isolated accent. The music follows the shape or intensity curve of the action over time instead of catching one discrete moment.','Parametric synchronization matches a changing part of the music to a changing part of the action. As the action speeds up, the music might speed up or grow louder. It follows the flow, not just one single hit. Think of music rising and falling with the tension on screen.','It ties the music''s evolving character to the evolving action so the score feels connected to the pace and intensity of a scene across time, not just at one accent.','A composer scoring a chase gradually raises tempo, volume, and density as the pursuit intensifies, so the music''s parameters climb along with the action.','Synchronization',ARRAY['Phrasal synchronization','Hit point','Mickey-Mousing','Click track','Spotting']::text[],ARRAY['Confusing parametric synchronization with hitting a single accent; it tracks a change over time, not one moment.','Letting the parameter changes drift out of step with the action because no click or guide is used.','Making a parameter follow the action so literally that it becomes distracting Mickey-Mousing.']::text[],ARRAY['Building musical intensity that rises with an escalating action sequence.','Slowing tempo and thinning texture as on-screen energy winds down.','Mapping loudness to the growing threat in a suspense scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d51fc4f9-552a-5c0d-a41a-41ffda446c32' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parametric synchronization'),'[^a-z0-9]','','g'));
