SELECT 'd51fc4f9-552a-5c0d-a41a-41ffda446c32','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d51fc4f9-552a-5c0d-a41a-41ffda446c32' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7cf58c4f-2e9a-5c39-8603-1beb3aee7f58','Pathetic music','Music intended to evoke pathos, that is, sorrow, grief, tenderness, or pity, used to underscore sad, tragic, or plaintive dramatic situations. In silent-film and photoplay practice, ''pathetic'' was a standard mood heading under which theater musicians filed and selected slow, mournful, or plaintive pieces to accompany emotional scenes.','Pathetic music is sad, moving music. The word comes from ''pathos,'' meaning deep feeling. It is used for grief, loss, and tender scenes. In silent-film days, ''pathetic'' was a label on the shelf where players kept their sad pieces.','It supplies the emotional coloring for sorrowful or tender moments and, in the photoplay era, gave accompanists a ready mood category for quickly matching music to sad scenes.','A silent-film organist selects a piece filed under ''pathetic'' to underscore a deathbed or farewell scene, matching the music''s mournful character to the drama.','Mood Category',ARRAY['Photoplay music','Photoplay album','Photoplay library','Cue sheet','Underscore']::text[],ARRAY['Reading ''pathetic'' in its modern insulting sense rather than its musical meaning of moving or sorrowful.','Choosing music that is merely slow rather than genuinely mournful, missing the emotional target.','Overusing pathetic music so a film feels relentlessly sad and loses contrast.']::text[],ARRAY['Underscoring a death, farewell, or loss in a drama.','Selecting a mournful piece from a photoplay collection for a sad silent-film scene.','Accompanying a tender, tearful moment where sorrow is the main emotion.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7cf58c4f-2e9a-5c39-8603-1beb3aee7f58' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pathetic music'),'[^a-z0-9]','','g'));
