SELECT '7cf58c4f-2e9a-5c39-8603-1beb3aee7f58','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7cf58c4f-2e9a-5c39-8603-1beb3aee7f58' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '607e81b9-30c0-53ba-93b9-696976352b45','Perspective orchestration','An orchestration approach that uses register, dynamics, doubling, and instrument choice to create a sense of spatial depth or point of view, placing some material in the sonic foreground and other material in the background, or suggesting distance and physical perspective that matches what is seen on screen.','Perspective orchestration arranges instruments to create a sense of depth. Some parts sound close and up front. Others sit softly in the background, as if far away. It works like a painter showing near and distant things. Composers use it to match how close or far the action feels.','It gives an arrangement a sense of front-to-back depth and can mirror the on-screen viewpoint or distance, so the music''s spatial layering supports the picture.','For a wide landscape shot, an orchestrator keeps distant material soft and high while a solo instrument sits close and prominent, creating audible foreground and background.','Orchestration',ARRAY['Orchestration thinning','Orchestral handoff','Doubling','Underscore','Dynamics']::text[],ARRAY['Putting every part at the same dynamic and register, so the arrangement sounds flat with no depth.','Confusing orchestral perspective with mix panning alone; perspective comes first from the writing, not only the mix.','Crowding the foreground with too many prominent lines, so nothing reads as distant.']::text[],ARRAY['Scoring a wide establishing shot where the music should feel vast and deep.','Suggesting distance for an off-screen or far-away element.','Layering a solo line in front of a soft orchestral bed for intimacy.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='607e81b9-30c0-53ba-93b9-696976352b45' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Perspective orchestration'),'[^a-z0-9]','','g'));
