WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='607e81b9-30c0-53ba-93b9-696976352b45' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3a8ae73e-2ae8-5a83-8eae-96e33083d90e','Photoplay album','A published collection of photoplay music, typically a bound folio of roughly eight to ten short character pieces composed or arranged for silent-film accompaniment and often grouped by mood or theme. Theater pianists, organists, and small orchestras drew individual numbers from such albums to accompany scenes.','A photoplay album was a book of short music pieces for silent films. It usually held about eight to ten numbers. The pieces were grouped by mood, like ''hurry'' or sad. Players pulled the right number from the album to fit a scene.','It packaged ready-made mood pieces in one affordable volume so cinema musicians could quickly find suitable music without buying every number separately.','A theater organist keeps a shelf of photoplay albums and, during a screening, turns to the album number whose mood fits the scene on screen.','Silent-Film Music',ARRAY['Photoplay music','Photoplay library','Pathetic music','Cue sheet']::text[],ARRAY['Confusing a photoplay album, a published folio of pieces, with a cue sheet, which only lists which pieces to play and when.','Assuming each album was written for one specific film; the pieces were general-purpose mood music.','Thinking the numbers had to be played in album order rather than chosen by scene.']::text[],ARRAY['Building a silent-film accompaniment set from published mood folios.','Selecting a mood piece from a folio to fit a scene during a screening.','Researching period-authentic music for a modern silent-film restoration.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3a8ae73e-2ae8-5a83-8eae-96e33083d90e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Photoplay album'),'[^a-z0-9]','','g'));
