SELECT '3a8ae73e-2ae8-5a83-8eae-96e33083d90e','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3a8ae73e-2ae8-5a83-8eae-96e33083d90e' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '155a76c6-5415-5007-abde-0206ef80ea8a','Photoplay library','The organized collection of photoplay music, comprising individual numbers, albums, and orchestral sets, that a theater, music director, or accompanist maintained and drew upon to assemble accompaniment for silent films. Large picture palaces kept libraries of thousands of scores filed by mood and type for rapid selection.','A photoplay library was a theater''s whole store of silent-film music. It held many pieces, filed by mood and type. Big theaters kept thousands of scores. Players pulled from the library to build the music for each film.','It gave a theater a broad, well-organized stock of mood music so its musicians could quickly assemble a fitting accompaniment for any film that arrived.','A cinema music director files the house library by mood so that, when a new film comes in, the organist can pull agitatos, love themes, and pathetic pieces to match the cue sheet.','Silent-Film Music',ARRAY['Photoplay music','Photoplay album','Pathetic music','Cue sheet']::text[],ARRAY['Confusing a library, the whole stock of music, with a single album or cue sheet.','Assuming small theaters had large libraries; many relied on a modest set of general pieces.','Filing pieces without a mood system, making fast selection during a screening impossible.']::text[],ARRAY['Organizing a theater''s music stock by mood for quick access.','Pulling several pieces from the house library to accompany a new film.','Cataloging a surviving silent-era music collection for an archive.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='155a76c6-5415-5007-abde-0206ef80ea8a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Photoplay library'),'[^a-z0-9]','','g'));
