INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '72b2ec80-f9e9-596a-bb1e-9821949eaf01','Photoplay music','Short, evocative character pieces composed or arranged specifically to accompany silent films, typically organized by mood and dramatic function such as agitato, hurry, love theme, mysterioso, and pathetic. Musicians strung these general-purpose pieces together to build a compiled score for a given film.','Photoplay music is music written to play along with silent films. ''Photoplay'' was an old word for a movie. The pieces came in moods, like chase, love, or sad. Players stitched them together to score a whole film.','It gave silent-cinema musicians a stock of ready mood pieces so they could accompany any film scene by scene, since most films arrived without their own scores.','A theater pianist accompanying a silent film selects photoplay pieces by mood, following a cue sheet, and links them to underscore the action continuously.','Silent-Film Music',ARRAY['Photoplay album','Photoplay library','Pathetic music','Cue sheet','Underscore']::text[],ARRAY['Thinking each film had its own original photoplay score; most were compiled from general-purpose pieces.','Assuming silent films were shown silent; live photoplay music was the norm.','Confusing photoplay music, the pieces themselves, with the cue sheet, the playlist telling when to use them.']::text[],ARRAY['Accompanying a silent film with live piano or organ.','Compiling a mood-based score for a silent feature.','Restoring period-accurate music for an archival silent-film screening.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='72b2ec80-f9e9-596a-bb1e-9821949eaf01' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Photoplay music'),'[^a-z0-9]','','g'));
