SELECT '72b2ec80-f9e9-596a-bb1e-9821949eaf01','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='72b2ec80-f9e9-596a-bb1e-9821949eaf01' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9ea34377-a566-53fe-9dc9-76383aa31781','Phrasal synchronization','Synchronization of music to picture at the level of whole phrases and dramatic units rather than individual frame-accurate accents. The composer aligns the shape, length, and arrival points of musical phrases with scene structure, such as entrances, exits, and beats of the drama, so the music breathes with the action without marking every small movement.','Phrasal synchronization lines up music with the scene in big chunks. A whole musical phrase matches a whole beat of the story. It is looser than hitting every single action. The music breathes with the scene instead of catching every tiny move.','It matches the music''s larger units to the drama''s larger units, giving a natural, flowing fit to picture without the stiffness of frame-by-frame hits.','A composer shapes a phrase to begin as a character enters and to cadence as the scene turns, aligning musical phrasing with dramatic structure rather than clicking to each gesture.','Synchronization',ARRAY['Parametric synchronization','Structural synchronization','Hit point','Spotting','Open ending','Click track']::text[],ARRAY['Trying to hit every small on-screen action when the scene calls for looser, phrase-level fit.','Letting phrases wander so they no longer land on the scene''s key moments.','Assuming phrasal sync needs no planning; the phrase arrivals still must match the drama.']::text[],ARRAY['Scoring a dialogue scene where the music should flow, not catch every gesture.','Aligning a musical phrase to a character''s entrance and exit.','Underscoring a montage so phrases match each section rather than each cut.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9ea34377-a566-53fe-9dc9-76383aa31781' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phrasal synchronization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9ea34377-a566-53fe-9dc9-76383aa31781','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9ea34377-a566-53fe-9dc9-76383aa31781' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7174ed49-17aa-58f6-84aa-0792f6909b07','Picture slip','A loss of synchronization that occurs when the picture edit changes, as shots are added, trimmed, or re-timed, after music has been written or recorded to an earlier cut, so cues no longer line up with the images. More broadly, any timing offset in which the picture drifts out of alignment with the score.','Picture slip is when the film''s edit changes after the music is written. Shots get moved or trimmed, so the cues no longer match. Music that once fit now lands in the wrong place. The composer must fix the timing to catch up.','Naming the problem lets a scoring team spot and fix places where a re-edited picture no longer matches cues written to the old cut, protecting sync before the mix.','After a re-cut, the composer re-spots the cue, shifts hits, and re-conforms the music to the new out-points so the score lines up with the changed picture.','Synchronization',ARRAY['Out-point','Open ending','Spotting','Hit point','Timecode']::text[],ARRAY['Recording a whole cue to a cut that is not locked, so a later re-edit makes the music slip.','Assuming a small picture change will not affect sync; even a few frames can throw off hits.','Fixing slip by ear alone instead of re-conforming to the new timecode and out-points.']::text[],ARRAY['Discovering cues no longer hit after the editor re-cuts a scene.','Re-conforming a recorded score to a revised picture.','Deciding to wait for picture lock before recording to avoid slip.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7174ed49-17aa-58f6-84aa-0792f6909b07' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Picture slip'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7174ed49-17aa-58f6-84aa-0792f6909b07','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
