INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6b30dadf-f353-50df-b25f-969bcce486ee','Picture-change list','A document, generated by the picture editorial department when a cut is revised, that itemizes every change made to the picture between two versions of a reel — shots added, removed, extended, or trimmed — with the exact footage or timecode locations and durations. Downstream departments use it to conform their work to the new cut instead of re-editing from scratch.','When editors change a locked cut, they write a list of every edit. It says what was added or removed, and exactly where. The music and sound teams read this list. They use it to match their work to the new version of the film.','It communicates exactly how a re-cut differs from the previous version, so composers, music editors, and sound editors can update only the affected material rather than rebuilding a reel, preserving sync and saving time.','A music editor receives the picture-change list after a re-cut and uses it to slide, trim, or extend recorded cues so each hit still lands on picture in the new version.','Picture Conforming',ARRAY['Post-record conform','Pre-record conform','Point of synchronization','Picture lock','Conform']::text[],ARRAY['Assuming a picture-change list tracks audio or color changes — it records picture edits only.','Conforming to a superseded change list after a newer revision has been issued.','Reading footage-based changes as timecode, or the reverse, and shifting cues to the wrong frame.']::text[],ARRAY['A director re-cuts a reel after spotting and editorial issues a change list.','A music editor conforms recorded cues to a new version using the change list.','Music and sound departments sync a new picture cut from the same change list.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6b30dadf-f353-50df-b25f-969bcce486ee' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Picture-change list'),'[^a-z0-9]','','g'));
