SELECT '6b30dadf-f353-50df-b25f-969bcce486ee','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6b30dadf-f353-50df-b25f-969bcce486ee' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bff3523d-aefd-5e17-95ea-8110e0bc8aaf','Plaintive','A descriptive term for music whose expressive character conveys sadness, longing, or mournfulness; as a scoring direction it calls for a melancholy, sorrowful quality, often realized through minor modes, sighing melodic gestures, slow tempo, and plaintive-timbred instruments such as oboe, cor anglais, or solo strings.','Plaintive music sounds sad or full of longing. It feels like a quiet cry or a sigh. Composers use it for grief, loss, or tender sad moments. Slow tunes, minor keys, and lonely solo instruments help build this mood.','It labels an emotional target for a cue, guiding the composer and orchestrator toward musical choices that evoke sorrow or yearning to support a scene''s dramatic tone.','During spotting or on a cue sheet, a director or composer marks a moment as needing a plaintive theme, and the orchestrator scores it for expressive solo winds or strings.','Musical Character',ARRAY['Underscore','Spotting','Theme','Orchestration','Cue']::text[],ARRAY['Confusing plaintive with simply quiet or slow — it specifically implies sorrow or longing.','Over-scoring a plaintive cue with full orchestra, burying its intimate, mournful quality.','Treating plaintive as identical to ''sad'' without the sense of yearning or lament it carries.']::text[],ARRAY['Spotting a funeral scene and calling for a plaintive solo-oboe line.','A composer marks a character''s theme plaintive to signal loss.','An orchestrator voices a plaintive cue for cor anglais over sustained strings.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bff3523d-aefd-5e17-95ea-8110e0bc8aaf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Plaintive'),'[^a-z0-9]','','g'));
