SELECT 'bff3523d-aefd-5e17-95ea-8110e0bc8aaf','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bff3523d-aefd-5e17-95ea-8110e0bc8aaf' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8824372c-ef4e-5ef0-9026-e027e92ceef8','Point of synchronization','A specific frame or moment in the picture at which the music is intended to align precisely with an on-screen event — an action, cut, word, or gesture — commonly called a sync point or hit. Points of synchronization are identified during spotting and drive the choice of tempo, click, and streamer/punch cues so a musical accent coincides exactly with the visual.','A point of synchronization is an exact spot in the film where the music must hit an action on screen. It might be a door slam, a look, or a cut. The composer plans the music so a strong beat lands right on that frame.','It defines the exact target the music must hit, letting the composer set tempo and meter so a musical accent lands on the visual event and reinforces the drama.','A composer lists points of synchronization from the spotting notes, then builds a tempo map so a downbeat or accent falls on each one during recording.','Synchronization',ARRAY['Streamer','Punch','Click track','Spotting','Tempo map','Hit point']::text[],ARRAY['Trying to catch too many sync points, forcing awkward tempo changes that hurt the music.','Locking a sync point to the wrong frame because the reference lacks a common sync mark.','Leaving a hit off by frames after a re-cut has moved the sync point.']::text[],ARRAY['Spotting an action scene to mark each impact as a sync point.','Building a tempo map so a cymbal crash lands on a hard cut.','Setting streamers and punches to guide the conductor to each sync point.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8824372c-ef4e-5ef0-9026-e027e92ceef8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Point of synchronization'),'[^a-z0-9]','','g'));
