INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7004e51e-cb6f-5d1d-a9ee-a25a253e16c3','Post-record conform','The process of re-editing an already-recorded score to match picture changes made after the scoring session — sliding, cutting, extending, or repitching recorded cues so each musical event still lines up with the revised picture. It is the alternative to re-recording and is typically carried out by the music editor.','Sometimes the film is re-cut after the music is already recorded. Post-record conform fixes the music to fit the new cut. The music editor moves, trims, or stretches the recorded cues. This keeps each musical hit lined up without recording again.','It lets a production adapt an expensive, already-recorded score to late picture changes without the cost of a new session, keeping sync intact.','Using a change list, the music editor conforms recorded cues in the workstation after a re-cut, nudging and editing audio so hits still land on picture.','Picture Conforming',ARRAY['Pre-record conform','Picture-change list','Conform','Music editor','Point of synchronization']::text[],ARRAY['Assuming every re-cut can be conformed — some changes force a re-record.','Editing recorded audio so aggressively that tempo or musical phrasing is broken.','Conforming without the change list and guessing edit points, drifting out of sync.']::text[],ARRAY['A reel is trimmed after the scoring session and a cue must be shortened to fit.','A music editor conforms recorded cues to a new cut before the final mix.','A hit drifts off picture after a re-cut and is nudged back in the workstation.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7004e51e-cb6f-5d1d-a9ee-a25a253e16c3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-record conform'),'[^a-z0-9]','','g'));
