INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc60c0a7-66b5-5163-9bdd-9957923c4734','Pre-record conform','The process of updating the score''s timing to the current picture cut before the scoring session records, so the composer, orchestra, and conductor perform to the most up-to-date version. Cue timings, tempo maps, and streamer/punch cues are revised to the latest picture changes ahead of recording.','Before the orchestra records, the film cut may have changed. Pre-record conform updates the music timing to that latest cut first. Then the players record to the current version. This avoids having to fix the music after the session.','It ensures the score is recorded against the newest picture so hits are correct at the session, reducing costly conforming or re-recording afterward.','The music editor updates tempo maps, click, and streamers to the latest cut before the date, so the conductor records to accurate picture.','Picture Conforming',ARRAY['Post-record conform','Picture-change list','Conform','Tempo map','Streamer']::text[],ARRAY['Recording to an outdated cut because the latest change list was not applied.','Updating cue timings but forgetting to move the matching streamers and punches.','Assuming pre-record conform removes all need for later fixes when picture keeps changing.']::text[],ARRAY['Editorial delivers a new cut days before the session and cues are re-timed.','A music editor updates the tempo map to the latest picture before recording.','Streamers are repositioned to the current cut ahead of the scoring date.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc60c0a7-66b5-5163-9bdd-9957923c4734' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-record conform'),'[^a-z0-9]','','g'));
