INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '468f0939-ba37-59aa-bc9d-9353ebaeccc5','Prelay','In audio post-production, the preparatory stage in which edited sound elements — dialogue, music, sound effects, and Foley — are laid out and organized onto tracks, cleaned, and readied for the re-recording (final) mix; also the resulting set of prepared tracks. Prelay precedes and feeds the predub/premix and final dub.','Before the final mix, every sound must be edited and placed onto tracks. Prelay is this get-ready stage. Editors line up the dialogue, music, effects, and footsteps in order. That way the mixers can balance them cleanly later.','It organizes and readies all edited audio so the re-recording mixer can focus on balance and blend rather than fixing edits during the mix.','A sound editor prelays cut effects and Foley onto labeled tracks with handles and fades so the dub stage runs efficiently.','Mix Preparation',ARRAY['Predub','Final mix','Stem','Foley','Dialogue editing']::text[],ARRAY['Leaving clicks, overlaps, or missing fades in the prelay for the mixer to fix.','Poor track labeling and layout that slows the dub stage.','Confusing prelay (track preparation) with the predub, which is the actual premixing.']::text[],ARRAY['A sound editor prelays effects and Foley before the dialogue predub.','Music stems are prelaid onto the dub session ahead of the final mix.','Tracks are organized in prelay so the re-recording mixer can start balancing at once.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='468f0939-ba37-59aa-bc9d-9353ebaeccc5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prelay'),'[^a-z0-9]','','g'));
