INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f49382f7-ab47-5315-95f3-1322e143d446','Pull-down','A downward speed and sample-rate adjustment of approximately 0.1% (a factor of 1000/1001) applied to audio when material originating at 24 fps film speed is used against NTSC video, whose picture runs at 23.976 fps. Slowing the audio by 0.1% keeps it locked to the slowed picture; the term also denotes the corresponding sample-rate offset, such as 48000 Hz to 47952 Hz, in a workstation.','Film runs at twenty-four frames each second. The older North American video format, called NTSC, runs about 0.1 percent slower. Pull-down slows the sound by that same tiny amount. This keeps the sound locked to the slower picture.','It compensates for the 0.1% speed offset between 24 fps film and NTSC video so transferred audio stays in sync with picture and does not drift over the length of a reel.','When importing 24 fps-referenced music or production sound into an NTSC (23.976 fps) session, an engineer sets 0.1% pull-down so the audio locks to picture.','Sync & Frame Rate',ARRAY['Pull-up','Frame rate','Timecode','Sample rate','Sync']::text[],ARRAY['Confusing pull-down with pull-up and shifting speed the wrong way, causing drift.','Applying pull-down to material that was already at the video rate, double-correcting it.','Forgetting that pull-down changes pitch slightly as well as speed.']::text[],ARRAY['Conforming 24 fps scoring-stage recordings to a 23.976 fps NTSC mix session.','Laying a mix back to NTSC video with the audio pulled down 0.1%.','Importing telecine-transferred production sound into an NTSC post session.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f49382f7-ab47-5315-95f3-1322e143d446' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pull-down'),'[^a-z0-9]','','g'));
