WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f49382f7-ab47-5315-95f3-1322e143d446' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '28fec370-dced-552d-8291-654dbd03265c','Pull-up','An upward speed and sample-rate adjustment of approximately 0.1% (a factor of 1001/1000) applied to audio to reverse a pull-down — for example, returning audio that was slowed for NTSC (23.976 fps) post-production to true 24 fps film speed, or preparing NTSC-rate audio for a 24 fps deliverable. It also denotes the corresponding sample-rate offset, such as 48000 Hz to 48048 Hz, in a workstation.','Pull-up is the opposite of pull-down. It speeds the sound up by about 0.1 percent. Editors use it to bring sound that was slowed for video back to true film speed. This restores the original timing and pitch.','It restores audio to true 24 fps film speed after NTSC post-production, or matches video-rate audio to a film deliverable, keeping sync across the format change.','When delivering an NTSC-rate mix to a 24 fps film print, an engineer applies 0.1% pull-up so the audio matches the faster film speed.','Sync & Frame Rate',ARRAY['Pull-down','Frame rate','Timecode','Sample rate','Sync']::text[],ARRAY['Mixing up pull-up and pull-down and correcting speed in the wrong direction.','Applying pull-up to material that never received a pull-down, throwing it out of sync.','Overlooking the small pitch shift that comes with the speed change.']::text[],ARRAY['Returning an NTSC post mix to true 24 fps for a theatrical film print.','Preparing 23.976 fps-referenced audio for a 24 fps deliverable with pull-up.','Reversing a pull-down applied earlier in the post workflow.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='28fec370-dced-552d-8291-654dbd03265c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pull-up'),'[^a-z0-9]','','g'));
