INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '087b14f8-d960-5d2f-9e26-953d41764d99','Pulse stem','A stem — a submix of the score printed as a discrete stereo or multichannel element — that contains the cue''s rhythmic pulse material: ostinati, percussion, and pulsing or arpeggiated synth and string figures that drive the cue''s momentum. It is delivered separately from melodic, harmonic, and ambient stems so the pulse can be balanced or muted independently at the mix.','A stem is one grouped layer of the music, printed on its own. A pulse stem holds the steady rhythmic drive of a cue. It has the beats and repeating rhythmic patterns. Keeping it separate lets mixers raise or lower the drive on its own.','Splitting the rhythmic pulse into its own stem gives the re-recording mixer independent control over a cue''s drive and energy relative to dialogue and effects, and supports later revisions or trailer use.','A composer delivers a pulse stem alongside melody, harmony, and effects stems so the dub-stage mixer can dip the rhythmic drive under dialogue without losing the whole cue.','Stems & Deliverables',ARRAY['Stem','Ostinato','Predub','Final mix','Underscore']::text[],ARRAY['Baking reverb or melodic content into the pulse stem so it can no longer be balanced cleanly.','Assuming stem layouts are standardized — deliverable stem sets vary by production.','Printing the pulse stem at a different level or sync than the summed mix, breaking recombination.']::text[],ARRAY['Delivering separated score stems so a mixer can lower the pulse under dialogue.','Reusing a cue''s pulse stem to build a trailer version.','Muting the pulse stem to audition a cue''s melodic content alone.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='087b14f8-d960-5d2f-9e26-953d41764d99' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pulse stem'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '087b14f8-d960-5d2f-9e26-953d41764d99','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='087b14f8-d960-5d2f-9e26-953d41764d99' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bcd2c687-2834-5a87-9b80-90ff046489d2','Punch-and-streamer synchronization','A visual cueing method that guides a conductor to hit points during recording: a streamer is a vertical line (or diagonal wipe) that travels across the picture over a set interval — traditionally about three seconds — arriving at the target frame, and a punch is a brief flash (originally a hole punched in the film, now usually a digital flash) that marks the exact hit frame. Together they let a conductor anticipate and land musical accents on sync points, with or without a click track.','When scoring to film, the conductor must hit exact moments. A streamer is a line that sweeps across the screen over a few seconds. It reaches the edge right at the target moment. A punch is a quick flash on the exact frame. These visual cues tell the conductor when to hit.','It gives the conductor a precise visual countdown to each sync point, enabling accurate hits and flexible tempo without relying solely on a click track.','A music editor places streamers and punches at each hit in the scoring session so the conductor can catch them live on the scoring stage.','Synchronization',ARRAY['Streamer','Punch','Click track','Point of synchronization','Spotting','Scoring stage']::text[],ARRAY['Setting the streamer too short so the conductor cannot anticipate the hit in time.','Placing the punch on the wrong frame, cueing the accent a beat off.','Relying on streamers without a common start mark, so cues begin out of sync.']::text[],ARRAY['Cueing a conductor to catch a dramatic hit without a click track.','A music editor lays streamers and punches for each sync point before a session.','Combining a click track with punches to lock tempo and land specific hits.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bcd2c687-2834-5a87-9b80-90ff046489d2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Punch-and-streamer synchronization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bcd2c687-2834-5a87-9b80-90ff046489d2','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bcd2c687-2834-5a87-9b80-90ff046489d2' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '99421404-6c2f-5409-a199-b3614309dbe2','Reconform','The process of re-editing an existing audio session, score, or set of stems to match a revised picture cut after changes are made to a previously locked edit. An editor compares the old and new picture edit decision lists (or change lists) and inserts, deletes, or shifts material so the audio again lines up frame-accurately with the new version.','Sometimes the film is re-edited after the sound work has started. Reconform means fixing the sound to fit the new cut. The editor compares the old and new edits. Then they move, add, or trim the audio so it lines up with the picture again.','It lets a team preserve completed audio and music work when the picture changes, instead of rebuilding the session from scratch, keeping every element in frame-accurate sync with the new cut.','When a picture editor delivers a new version, the music editor loads the change list into conforming software and reconforms the score session so cues still hit the same on-screen actions.','Editing & Conform',ARRAY['Edit decision list','Change list','Score conform stem','Picture lock','Music editor','Reel–music cue number']::text[],ARRAY['Reconforming from an outdated or mismatched change list, so the audio shifts to the wrong places.','Assuming a ''locked'' picture will not change and building the session in a way that is hard to reconform later.','Forgetting to reconform every stem and reference layer, leaving some elements out of sync with the new cut.']::text[],ARRAY['A director re-edits a scene after picture lock and the music session must be reconformed to the new cut.','Adapting a finished mix to a shorter broadcast version.','Updating score stems after the editor trims frames from several shots.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='99421404-6c2f-5409-a199-b3614309dbe2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reconform'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '99421404-6c2f-5409-a199-b3614309dbe2','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='99421404-6c2f-5409-a199-b3614309dbe2' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '52cd3b9c-3417-52a9-8eef-09497509bc27','Reduced-density mix','A version of a music mix or cue in which the orchestral or instrumental texture is thinned—fewer simultaneous parts, doublings, or layers—so the arrangement occupies less of the frequency and rhythmic space. It is used to reduce masking of dialogue and effects or to present the same material in a lighter, more transparent way.','Density means how many parts play at once. A reduced-density mix has fewer parts playing together. This thins out the music. It leaves more room for the dialogue and sound effects to be heard clearly.','It exists to clear sonic space so speech and key effects stay intelligible, and to let the music support a scene without overwhelming it.','When music covers a dialogue-heavy scene, a composer or mixer supplies a reduced-density mix that drops busy inner parts so the words remain clear under the score.','Mixing & Stems',ARRAY['Registral clearance','Score stem family','Masking','Orchestration','Score prelay','Score conform stem']::text[],ARRAY['Thinking a reduced-density mix just means turning the music down, rather than removing parts.','Stripping so many parts that the cue loses its harmonic support or emotional intent.','Reducing density in the wrong frequency range, so the mix still masks dialogue.']::text[],ARRAY['Preparing an alternate cue for a scene where dialogue must stay clear.','Delivering a lighter version of a theme for an intimate moment.','Thinning inner harmony parts that clash with sound effects.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='52cd3b9c-3417-52a9-8eef-09497509bc27' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reduced-density mix'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '52cd3b9c-3417-52a9-8eef-09497509bc27','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='52cd3b9c-3417-52a9-8eef-09497509bc27' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7daf3613-abd2-5426-aac6-e6294ed338db','Reel–music cue number','A standardized identifier that labels each music cue by the reel it appears in and its order within that reel, conventionally written in the form reel-number, M, cue-number (for example 1M1 or 3M5). The letter M denotes music, distinguishing the cue from dialogue or effects, and the numbering keeps cues organized across the film.','Films are split into sections called reels. Each piece of music is a cue. This number labels a cue by its reel and its order in that reel. For example, 1M1 means reel one, music, first cue. It keeps every cue easy to find.','It gives every cue a unique, sortable name so composers, music editors, orchestrators, and mixers can track, discuss, and file cues without confusion.','A music editor spots the film and assigns each cue a reel–music cue number, then labels the score, session, and cue sheet with it so everyone references the same cue.','Music Editing',ARRAY['Spotting session','Cue sheet','Music editor','Reel','Reconform','Score element']::text[],ARRAY['Confusing the reel number with the cue number within the label.','Renumbering cues after reels are combined or split without updating the score and cue sheet.','Using inconsistent formats across the score, session, and paperwork so cues cannot be matched.']::text[],ARRAY['Labeling cues during a spotting session.','Organizing session files and score parts for a recording date.','Cross-referencing a cue on the cue sheet with its recorded stem.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7daf3613-abd2-5426-aac6-e6294ed338db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reel–music cue number'),'[^a-z0-9]','','g'));
