WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7daf3613-abd2-5426-aac6-e6294ed338db' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4d1e3902-ba0f-5f39-aaab-78a15e8cb874','Registral clearance','An orchestration and mixing practice of keeping a particular pitch register free of competing musical material so another element—typically dialogue, a solo line, or a sound effect—can occupy that register without being masked. Parts are voiced above or below the protected band rather than within it.','Every sound sits in a pitch range, from low to high. Registral clearance means keeping one range mostly empty of music. This leaves space for something else, like the voice. The music is written above or below that range so it does not cover it.','It prevents the score from masking speech or a featured line by reserving the frequency band that element needs, improving clarity in the final mix.','When a scene has important dialogue, an orchestrator voices the strings and winds away from the vocal range so the words are not buried under the music.','Orchestration',ARRAY['Reduced-density mix','Masking','Register','Orchestration','Voicing','Score prelay']::text[],ARRAY['Piling inner parts into the same register as the dialogue, causing masking.','Assuming lowering the music level fixes a clash that is really a register problem.','Clearing the wrong register for the element that needs protecting.']::text[],ARRAY['Orchestrating under a dialogue scene.','Making room for a solo instrument in a dense arrangement.','Fixing a cue where music masks an important line of speech.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4d1e3902-ba0f-5f39-aaab-78a15e8cb874' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Registral clearance'),'[^a-z0-9]','','g'));
