INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67487d42-8c7b-5261-8eb9-f2b51776910b','Ring-out take','An additional recorded take, or an extension of a cue''s final take, in which the ensemble sustains and then lets the last chord or note decay fully so the natural acoustic tail of the scoring stage is captured cleanly. It provides an uninterrupted reverberant decay that can be edited onto the end of the cue.','At the end of a piece, the last chord fades away in the room. A ring-out take records that fading tail on its own. The players hold the final chord and let it die out. The mixer can then add this clean tail to the end of the cue.','It gives the music editor a clean, natural reverb tail to end a cue, avoiding an abrupt cutoff or an artificial fade.','After the main take, the scoring mixer records a ring-out take of the final chord so the cue can end with a smooth, natural decay instead of a hard edit.','Recording',ARRAY['Take','Scoring stage','Score stage master','Reverberation','Sectional overlay','Scoring stage foldback']::text[],ARRAY['Cutting the final chord off before it fully decays, leaving no usable tail.','Recording the ring-out with different mic or room settings, so the tail does not match the cue.','Introducing noise or talkback during the decay, ruining the clean tail.']::text[],ARRAY['Capturing a natural ending for a big final chord.','Providing a clean tail so the dubbing mixer can blend the cue''s end.','Fixing a cue whose ending was clipped in the main take.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67487d42-8c7b-5261-8eb9-f2b51776910b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ring-out take'),'[^a-z0-9]','','g'));
