INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '79702be9-054d-5966-b744-7cf0b8a77e96','Score conform stem','A music (score) stem that has been conformed—re-edited to match a revised picture cut—so the premixed music layer again aligns frame-accurately with the current version of the film. It carries the conformed music separately from the dialogue and effects stems.','A stem is a submix of one group of sounds, like all the music. When the film is re-edited, the music stem must be trimmed and moved to fit. A score conform stem is that music stem after it has been fixed to match the new cut.','It keeps the music layer in sync with the latest picture as a self-contained stem, so the dub and the deliverables stay accurate after re-edits.','After a picture change, the music editor conforms the score stems and delivers the score conform stem to the dub stage so the music still hits the action.','Mixing & Stems',ARRAY['Reconform','Stem','Score stem family','Change list','Score prelay','Reduced-density mix']::text[],ARRAY['Delivering an old score stem that was never conformed to the new cut.','Conforming the mix but forgetting to update the matching stem.','Losing sync because the stem was conformed against the wrong change list.']::text[],ARRAY['Updating music stems after a re-edit before the final dub.','Creating conformed deliverables for a revised release version.','Matching the score stem to a new broadcast edit.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='79702be9-054d-5966-b744-7cf0b8a77e96' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Score conform stem'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '79702be9-054d-5966-b744-7cf0b8a77e96','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
