INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ef5bffa6-61f9-5358-bda5-822cf2d6786e','Score element','A discrete, individually deliverable component of a film''s music—such as a single cue, stem, or submix—kept separate so it can be handled, tracked, or re-mixed on its own. Score elements are the building blocks that make up the complete music portion of a deliverable package.','A film''s music is made of many separate pieces. A score element is one of those pieces, like a single cue or a music submix. Keeping them separate lets the team move or remix one piece without touching the rest.','It lets music be delivered and revised in parts, so a single cue or layer can be swapped, re-mixed, or versioned without rebuilding the whole score.','When preparing deliverables, a music editor labels each score element—cue by cue and stem by stem—so the dub and archive teams can locate and use any single piece.','Deliverables',ARRAY['Stem','Score stem family','Reel–music cue number','Score conform stem','Cue','Score stage master']::text[],ARRAY['Confusing a score element with a full mix; an element is one component.','Failing to label elements clearly, so the wrong piece is used in the dub.','Delivering elements at inconsistent levels or formats across cues.']::text[],ARRAY['Assembling the music deliverables for a mix.','Swapping a single cue without remixing the whole score.','Archiving each music component separately for future reuse.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ef5bffa6-61f9-5358-bda5-822cf2d6786e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Score element'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ef5bffa6-61f9-5358-bda5-822cf2d6786e','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ef5bffa6-61f9-5358-bda5-822cf2d6786e' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '64756958-0ccf-53a2-955e-fc3530a301e9','Score prelay','The stage of laying the edited and premixed music up onto the dubbing session ahead of the final re-recording mix, so the score arrives at the dub stage organized, leveled, and synchronized. Because the music is already premixed to stems, laying it up occupies the slot a predub would fill for dialogue or effects, readying the cues for the final balance.','Before the final mix, the music is prepared and lined up in the session. Score prelay is this step of laying the music up ahead of time. It arrives sorted, timed, and roughly set in level. This makes the final mix faster and smoother.','It streamlines the final dub by delivering the music pre-organized and pre-balanced, so the re-recording mixer can focus on blending it with dialogue and effects.','The music editor prelays the score—placing each cue in sync and at a working level—so the dub stage begins with the music ready to mix.','Dub & Prelay',ARRAY['Predub','Dub stage','Score stem family','Music editor','Score conform stem','Reconform']::text[],ARRAY['Prelaying cues out of sync, so the dub inherits timing errors.','Setting wildly inconsistent prelay levels, making the final balance harder.','Prelaying an outdated cue version that was later revised.']::text[],ARRAY['Preparing the music session before the final re-recording mix.','Laying up conformed score stems for the dub stage.','Organizing cues by reel ahead of a mixing date.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='64756958-0ccf-53a2-955e-fc3530a301e9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Score prelay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '64756958-0ccf-53a2-955e-fc3530a301e9','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
