INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1ee3c68f-25c2-55ab-ad54-aa0b88548dc8','Score replacement pass','A dedicated editing or mixing pass in which existing music—often a temp track or an earlier version of a cue—is systematically swapped out and replaced with new or final score material throughout a sequence. Each cue is located, removed, and re-placed in sync so the section carries the intended music.','Films often use placeholder music first, called a temp track. A score replacement pass is a run through the project to swap that music out. Old cues are removed and the new final music is dropped in, in time with the picture.','It ensures every temporary or outdated cue is replaced with the correct final music before the mix, so nothing placeholder slips through.','Once final cues are recorded, the music editor makes a score replacement pass across the reels, pulling the temp music and laying in each final cue in sync.','Music Editing',ARRAY['Temp track','Music editor','Cue','Score prelay','Reconform','Reel–music cue number']::text[],ARRAY['Missing a cue during the pass, so temp music survives into the mix.','Replacing a cue without matching its original sync points.','Leaving level or fade mismatches between old and new cues after the swap.']::text[],ARRAY['Swapping a temp score for the final recorded cues.','Replacing revised cues after a re-score.','Updating a sequence when the composer delivers new versions.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1ee3c68f-25c2-55ab-ad54-aa0b88548dc8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Score replacement pass'),'[^a-z0-9]','','g'));
