INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '00a45cf3-78a5-5e50-8a84-c4eb3ea96537','Score stage master','The primary recorded master of a music cue captured at the scoring stage, typically the main mixed or multitrack recording of the orchestra and any other performers taken during the session. It is the authoritative source recording from which stems and edited versions are later derived.','A scoring stage is the studio where the orchestra records. The score stage master is the main recording made there. It is the top-quality source of the performance. Later stems and edits all come from this master.','It preserves the definitive session recording as the reference source, so all later stems, edits, and mixes trace back to one authoritative capture.','After the session, the scoring mixer stores the score stage master and derives the stems and cue edits from it rather than re-recording.','Recording',ARRAY['Scoring stage','Score stem family','Ring-out take','Score element','Scoring stage foldback','Score conform stem']::text[],ARRAY['UNSAFE: Storing the only score stage master without a backup, risking total loss of an irreplaceable session recording.','Editing the master directly instead of working from a copy.','Confusing a single stem with the full stage master.']::text[],ARRAY['Archiving the definitive orchestra recording after a session.','Deriving stems from the session master for delivery.','Referring back to the master when a stem must be rebuilt.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='00a45cf3-78a5-5e50-8a84-c4eb3ea96537' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Score stage master'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '00a45cf3-78a5-5e50-8a84-c4eb3ea96537','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='00a45cf3-78a5-5e50-8a84-c4eb3ea96537' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a02f9f25-ea81-51fc-afd1-949871b0ac94','Score stem family','The complete set of related music stems delivered together for a project—for example separate orchestra, choir, synth, solo, and percussion stems—that sum to the full score mix. Grouping them as a family keeps the music''s component submixes organized and recallable for the dub and for later remixing.','A stem is a submix of one group, like just the strings or just the synths. A score stem family is the full set of these music submixes for a project. Together they add up to the whole score. Keeping them as a set makes remixing easy.','It organizes the music''s submixes so the re-recording mixer can rebalance or mute individual groups, and so the score can be remixed for other formats later.','The scoring mixer delivers a score stem family—orchestra, choir, and electronics stems—so the dub stage can adjust the internal music balance without a full re-score.','Mixing & Stems',ARRAY['Stem','Score conform stem','Score element','Score stage master','Score prelay','Reduced-density mix']::text[],ARRAY['Delivering stems that do not sum back to the approved full mix.','Leaving stems in inconsistent formats or levels across the family.','Omitting a stem the mixer needs to rebalance the music.']::text[],ARRAY['Delivering music submixes for the final dub.','Remixing the score for a different release format.','Muting or boosting one music group during the mix.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a02f9f25-ea81-51fc-afd1-949871b0ac94' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Score stem family'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a02f9f25-ea81-51fc-afd1-949871b0ac94','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a02f9f25-ea81-51fc-afd1-949871b0ac94' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ee2c554d-dc27-5517-b1f2-91b4d445218a','Scoring stage foldback','The monitoring feed sent to performers and the conductor on a scoring stage, carrying the click track, any pre-recorded or playback elements, and a balance of the live ensemble so the players can stay in sync while recording to picture. It is delivered over headphones or stage loudspeakers separately from the control-room monitor mix.','Foldback is the sound sent back to the players so they can hear their cues. On a scoring stage it carries the click, any backing tracks, and the orchestra. Musicians usually listen on headphones. This keeps them in time with the film.','It lets the orchestra perform in tight sync with the click and picture by giving each performer the reference and blend they need to hear, independent of the recording mix.','The scoring mixer sets up foldback so the conductor and players hear the click and playback at safe, clear levels while the take is recorded.','Recording',ARRAY['Click track','Scoring stage','Streamers and punches','Score stage master','Monitor mix','Sectional overlay']::text[],ARRAY['UNSAFE: Setting headphone foldback so loud that it risks the musicians'' hearing over a long session.','Letting the click bleed into the live microphones through the foldback.','Giving performers an unbalanced foldback mix so they cannot hear the click or key cues.']::text[],ARRAY['Feeding click and playback to the orchestra during a recording session.','Setting up headphone mixes for a conductor and soloists.','Recording live players against pre-recorded synth elements.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ee2c554d-dc27-5517-b1f2-91b4d445218a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Scoring stage foldback'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ee2c554d-dc27-5517-b1f2-91b4d445218a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ee2c554d-dc27-5517-b1f2-91b4d445218a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '59d82ced-2f09-5aa9-94d9-47edf3ad2f43','Sectional overlay','A recording made by capturing an individual orchestral section (such as strings, brass, or choir) separately and layering it over previously recorded material, rather than recording the full ensemble at once. The overlaid section is performed to the existing tracks so the parts combine into the finished cue.','Sometimes each group of instruments is recorded on its own. A sectional overlay is one section, like the strings, recorded and layered on top of the earlier tracks. The players perform along to what was already recorded. All the layers then combine into one cue.','It builds a fuller or cleaner cue than a small or split ensemble could record live, and gives control over each section''s balance, by layering sections one at a time.','When the budget or room limits ensemble size, the scoring mixer records a string pass, then overlays brass and choir sections to the same click and picture.','Recording',ARRAY['Overdub','Sectional recording','Click track','Scoring stage foldback','Score stem family','Ring-out take']::text[],ARRAY['Overlaying a section without the same click or tempo map, so the layers drift out of sync.','Changing mic setup or room between overlays, so sections do not blend.','Layering so many overlays that phase and timing errors build up.']::text[],ARRAY['Recording a large orchestral sound with a smaller ensemble.','Adding a choir over a pre-recorded orchestra.','Building a cue section by section for balance control.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='59d82ced-2f09-5aa9-94d9-47edf3ad2f43' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sectional overlay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '59d82ced-2f09-5aa9-94d9-47edf3ad2f43','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='59d82ced-2f09-5aa9-94d9-47edf3ad2f43' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '11d1d316-dd0a-5c65-84b6-db7062c4c37b','Session punch','A punch is a single-frame visual cue — traditionally a hole punched in the film print so a bright flash appears on screen — placed at a precise picture event so a conductor knows the exact frame to hit while recording to picture. In a scoring session it marks a sync point, usually as the target that one or more streamers lead up to.','A punch is a quick flash of light on the movie screen. It marks one exact frame the conductor must hit. The orchestra plays so the music lands right on that flash. It helps everyone stay in time with the film.','It gives the conductor and players a precise, unmistakable visual marker for a key sync point, letting a live orchestra land an accent exactly on a picture event without relying only on a click.','During a scoring session the composer or music editor places punches at the film''s hit points, and the conductor watches for each flash to time the ensemble''s accents to picture.','Conducting Aids',ARRAY['Session streamer','Click track','Sync point','Hit point','Music editor']::text[],ARRAY['Confusing a punch with a streamer; the punch is the instantaneous flash at the hit, while the streamer is the moving line that leads up to it.','Placing the punch a frame or two off the intended picture event, so the recorded accent misses the action.','Relying on punches alone without a preceding streamer, giving the conductor no lead-in to prepare the hit.']::text[],ARRAY['Recording a live orchestra to picture on a scoring stage.','Cueing a conductor to catch a specific dramatic hit, such as a door slam.','Setting up a conductor''s video in scoring software that overlays streamers and punches on the picture.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='11d1d316-dd0a-5c65-84b6-db7062c4c37b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Session punch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '11d1d316-dd0a-5c65-84b6-db7062c4c37b','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='11d1d316-dd0a-5c65-84b6-db7062c4c37b' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8c061a80-a853-516b-b962-63d186348c0a','Session streamer','A streamer is a vertical or diagonal colored line that travels across the picture over a set number of frames and arrives at a sync point, warning the conductor that a hit is coming. In a scoring session it leads the conductor''s eye toward the punch or accent, giving a timed run-up to the moment the music must land.','A streamer is a colored line that slides across the movie screen. It reaches the edge right when a big moment happens. It warns the conductor that a hit is coming, like a countdown. This helps the orchestra play the accent at the right time.','It provides a moving visual countdown to an upcoming sync point so a conductor can prepare and time an ensemble''s accent precisely to picture.','A music editor sets streamers to run for a couple of seconds up to each hit, and the conductor uses the sweeping line as a lead-in to place the downbeat or accent.','Conducting Aids',ARRAY['Session punch','Click track','Sync point','Hit point','Conductor''s part']::text[],ARRAY['Confusing the streamer with the punch; the streamer is the moving lead-in line, the punch is the flash at the exact hit.','Making the streamer too short, so the conductor has no time to react before the hit arrives.','Assuming a streamer replaces the click; many cues use streamers and a click together.']::text[],ARRAY['Guiding a conductor into a fermata release on a specific frame.','Free-timing a cue to picture without a click, using streamers alone.','Preparing a conductor''s video with streamers burned in for a live scoring session.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8c061a80-a853-516b-b962-63d186348c0a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Session streamer'),'[^a-z0-9]','','g'));
