INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2d061e71-d6f5-5797-a0ee-42f9c0fb197a','Soft out','A soft out is a cue ending that tapers or fades away gradually — typically a sustained, decaying note or chord rather than a decisive final accent — leaving the exact end point open so the re-recording mixer can fade or overlap it as needed. It contrasts with a hard out, which ends on a firm, accented button.','A soft out is a gentle way for a music cue to end. The music fades out or holds a note that slowly dies away. It has no sharp final hit. This lets the mixer fade the music smoothly under the next scene.','It gives a cue an open, fadeable ending so the dubbing mixer can blend it into following dialogue, effects, or the next cue without an abrupt stop.','A composer writes a soft out — a long sustain or slow decay — when the music should dissolve under a scene change, and the re-recording mixer rides it down in the final mix.','Cue Construction',ARRAY['Hard out','Cue','Tail','Re-recording mixer','Underscore']::text[],ARRAY['Confusing a soft out with a hard out; a soft out fades away, a hard out ends on a firm accent.','Writing a soft out too short, giving the mixer no tail to fade.','Assuming the printed final note is played to silence; a soft out is meant to be faded under the mix.']::text[],ARRAY['Ending a tense cue so it dissolves under dialogue in the next scene.','Overlapping the fading tail of one cue with the start of the next.','Giving the dub mixer room to fade music under a sound-effects moment.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2d061e71-d6f5-5797-a0ee-42f9c0fb197a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Soft out'),'[^a-z0-9]','','g'));
