INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3587d557-1fc9-5009-ba8f-71bb36c4103c','Spotting note','Spotting notes are the written record produced from a spotting session: a timecode-referenced list specifying where each music (or sound) cue starts and stops and what it should accomplish dramatically. They become the composer''s and music editor''s working map of the film''s musical requirements.','A spotting note is a written note made while watching the film. It marks the exact time each music cue should start and stop. It also says what the music should do in that scene. The composer uses these notes as a to-do list for the score.','They capture the director''s and composer''s decisions about music placement and intent so the whole team works from one agreed, timecoded plan.','During or right after the spotting session, the music editor logs each cue''s in and out timecode and a short description of its purpose, then distributes the notes as the spotting log.','Spotting',ARRAY['Spotting session','Cue','Cue sheet','Timecode','Music editor','Hit point']::text[],ARRAY['Writing vague notes without accurate timecode, so cue starts and stops cannot be reproduced.','Recording only music placement and omitting the dramatic intent the director asked for.','Confusing the spotting note with the final cue sheet used for music rights and royalties.']::text[],ARRAY['Logging cue in and out points as the director and composer watch a locked cut.','Handing the composer a timecoded map of every cue before writing begins.','Updating spotting notes after a scene is re-edited.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3587d557-1fc9-5009-ba8f-71bb36c4103c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spotting note'),'[^a-z0-9]','','g'));
