INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4b6a7f16-9a76-56ea-a714-38b86480ff24','Stock cue','A stock cue is a pre-existing piece of production or library music selected from a catalog and used in a film or program instead of newly composed score. It is licensed ready-made, often cataloged by mood or dramatic use, and dropped in where original scoring is unnecessary or impractical.','A stock cue is ready-made music picked from a library. It is not written fresh for the film. Editors choose it from a catalog and license it to use. It saves time and money when custom music is not needed.','It supplies usable music quickly and cheaply from a licensed catalog, covering scenes — such as source music or background beds — that do not require bespoke scoring.','An editor or music supervisor searches a library by mood or genre, drops a stock cue onto the timeline, and clears its license for the production.','Music Sources',ARRAY['Library music','Production music','Source music','Cue','Music supervisor','Needle drop']::text[],ARRAY['Assuming stock cues are free to use; they still require proper licensing for the intended use.','Confusing a stock cue with original score written specifically for the film.','Ignoring catalog metadata, so a cue''s mood or length does not fit the scene.']::text[],ARRAY['Scoring a low-budget documentary from a music library.','Filling a background radio or television moment with a licensed source cue.','Using a temp library track that later becomes the final stock cue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4b6a7f16-9a76-56ea-a714-38b86480ff24' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stock cue'),'[^a-z0-9]','','g'));
