INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6f7f0a7c-35fe-5368-ae40-b911f9ddcabf','Structural conform','A structural conform is the process of re-aligning an existing score or recorded music to match structural changes in a revised picture edit — scenes added, removed, shortened, or reordered — usually guided by a change list or edit decision list. Unlike minor timing tweaks, it addresses shifts in the film''s large-scale structure.','A structural conform means fixing the music after the film''s edit changes a lot. Scenes may be cut, added, or moved around. The music editor shifts and trims cues so they still line up. It keeps the score matched to the new version of the film.','It keeps the music synchronized with the film after significant re-editing, so cues still begin, end, and hit in the right places against the new cut.','When a new cut arrives, the music editor uses the change list to slide, cut, and repeat sections of each cue so the score conforms to the updated picture structure.','Editing & Conform',ARRAY['Conform','Change list','Edit decision list','Music editor','Cue','Reconform']::text[],ARRAY['Conforming only the timing of accents while ignoring whole scenes that were added or removed.','Working from an outdated change list, so cues line up to the wrong cut.','Rebuilding cues from scratch when a structural conform against the change list would preserve the original performance.']::text[],ARRAY['Adapting a finished score after the director re-orders two sequences.','Conforming recorded cues to a shortened television edit.','Updating music to a new picture cut using the editor''s change list.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6f7f0a7c-35fe-5368-ae40-b911f9ddcabf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Structural conform'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6f7f0a7c-35fe-5368-ae40-b911f9ddcabf','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6f7f0a7c-35fe-5368-ae40-b911f9ddcabf' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e14102e3-0e5b-59c5-b528-59cc2971069d','Structural synchronization','Structural synchronization is the alignment of a score''s large-scale musical structure — its sections, phrases, and cadences — with the film''s structural units, such as scenes, sequences, and dramatic turning points. It operates at the level of overall form, as distinct from point synchronization, which matches individual accents to individual visual events.','Structural synchronization means matching the shape of the music to the shape of the film. Big musical sections line up with whole scenes or story beats. It works on the large scale, not single hits. This makes the score feel built into the story.','It ties the music''s form to the film''s dramatic architecture so musical arrivals and changes support the narrative''s larger shape, not just isolated moments.','A composer plans a cue so a new theme or key change lands at a scene''s dramatic shift, aligning musical form with the film''s structure rather than only catching single hits.','Synchronization',ARRAY['Point synchronization','Sync point','Hit point','Cue','Underscore','Structural conform']::text[],ARRAY['Focusing only on catching individual hits and missing the larger fit between musical form and scene structure.','Confusing structural synchronization with frame-accurate point sync; they work at different scales.','Letting a musical section change in the middle of a scene, breaking the alignment with the film''s structure.']::text[],ARRAY['Timing a musical climax to a film''s emotional turning point.','Matching a cue''s sections to the beats of a montage.','Planning key or theme changes to arrive at scene transitions.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e14102e3-0e5b-59c5-b528-59cc2971069d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Structural synchronization'),'[^a-z0-9]','','g'));
