INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '635dbffc-ec7c-5308-a4f8-5b998958c365','Subtonic half cadence','A subtonic half cadence is a phrase-ending harmonic gesture in which a subtonic (flat-VII) chord moves to the dominant (V), the non-diatonic flattened-seventh bass coloring the approach to the half cadence''s pause on V. Codified in Frank Lehman''s study of Hollywood cadences and traced to Jerome Moross''s 1958 score for The Big Country, it became a signature harmonic gesture of the American Western idiom.','This is a musical pause made from two chords. The first chord is built on a lowered seventh note of the scale. The music then steps up to the main tension chord and rests. This open, rugged sound became a classic Western-movie gesture.','It creates an open, unresolved pause with a rustic, wide-open-spaces color, letting a composer signal the Western genre and set up a following answering phrase.','A film composer uses a flat-VII-to-V motion at the end of an antecedent phrase to evoke Americana or the Western, then answers it with a consequent phrase.','Harmony',ARRAY['Half cadence','Subtonic','Dominant','Cadence','Antecedent phrase','Modal mixture']::text[],ARRAY['Thinking the subtonic (flat-VII) is the leading tone; the subtonic sits a whole step below the tonic, not a half step.','Expecting the flat-VII to resolve up to tonic; here it moves to the dominant to form a half cadence.','Confusing the half cadence''s pause on the dominant with an authentic cadence that resolves to tonic.']::text[],ARRAY['Scoring a Western landscape shot with an Americana theme.','Ending an antecedent phrase on an open, unresolved dominant.','Analyzing the harmonic language of a Jerome Moross or Copland-influenced score.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='635dbffc-ec7c-5308-a4f8-5b998958c365' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Subtonic half cadence'),'[^a-z0-9]','','g'));
