INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '320f6abd-ef5d-5a2e-a250-c122c2ff1c68','Sync-point tolerance','Sync-point tolerance is the small window — typically a few frames — within which a musical accent can fall relative to its intended picture event and still be perceived as synchronized. It underlies the distinction between hard sync points, which must hit an exact frame, and soft sync points, which read as in sync across a range of frames.','Sync-point tolerance is the tiny wiggle room around a hit. A music accent can land a few frames early or late and still look on time. Sharp actions need an exact hit. Softer moments allow a little slack.','It tells the composer and music editor how precisely each hit must land, so effort goes into frame-accurate placement only where the picture demands it.','A music editor treats a punch or explosion as a hard sync point needing exact placement, but allows a glance or gesture a few frames of tolerance when timing the cue.','Synchronization',ARRAY['Sync point','Hit point','Hard sync point','Soft sync point','Timecode','Streamer']::text[],ARRAY['Treating every sync point as frame-exact, wasting time chasing accuracy the audience cannot perceive.','Assuming any hit can be loose; sharp, percussive actions have very little tolerance.','Ignoring that tolerance depends on the speed and sharpness of the action on screen.']::text[],ARRAY['Deciding whether a subtle emotional beat needs a frame-exact hit.','Placing an accent within a few frames of a soft on-screen gesture.','Judging whether a cue still reads as in sync after a small picture change.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='320f6abd-ef5d-5a2e-a250-c122c2ff1c68' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync-point tolerance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '320f6abd-ef5d-5a2e-a250-c122c2ff1c68','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='320f6abd-ef5d-5a2e-a250-c122c2ff1c68' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e068a44d-324e-59fe-bdad-d1176b0bd8fd','Synchresis','Synchresis, a term Michel Chion coined by fusing "synchronism" and "synthesis," names the automatic, near-unavoidable way a viewer''s mind bonds a sound and a visual event that land at the same instant, so the two seem linked even when nothing rationally connects them. It is the perceptual mechanism that makes sound effects, Foley, and scored hits appear to belong to the images they accompany.','Synchresis is how our brain glues a sound to a picture. When a sound and an image happen together, we feel the image made the sound. It happens automatically, even if the two are unrelated. This is why sound effects and music hits feel like they belong on screen.','It explains why synchronized sound and picture bond in the viewer''s mind, which is the basis for Foley, sound effects, and musical hits reading as connected to the image.','A sound editor or composer exploits synchresis by placing a sound or accent exactly on a visual event, so the audience accepts it as caused by what they see.','Film Sound Theory',ARRAY['Point of synchronization','Sync point','Hit point','Foley','Mickey Mousing','Diegetic sound']::text[],ARRAY['Thinking synchresis requires the object''s real sound; any plausible sound placed on the event will fuse.','Assuming loose timing still fuses; synchresis depends on the sound and image coinciding closely.','Confusing synchresis (the perceptual fusion) with synchronization (the technical act of lining up sound and picture).']::text[],ARRAY['Adding a Foley footstep the audience accepts as the actor''s step.','Landing a musical stinger on a cut so it feels caused by the image.','Choosing an unrealistic effect sound that still reads because it hits on the visual.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e068a44d-324e-59fe-bdad-d1176b0bd8fd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Synchresis'),'[^a-z0-9]','','g'));
