INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7e1b34ce-0eb6-5636-90a2-e0af568da1b8','Synchronization score','A film score composed and recorded in precise synchronization with the picture, in which musical events, accents, and phrase boundaries are aligned to specific frames using timing references such as click tracks, streamers and punches, or SMPTE timecode. It is distinguished from a compilation or library approach, in which pre-existing music is placed against picture without being written to hit particular on-screen moments.','This is film music written to line up exactly with the picture. The composer marks the key moments on screen. The music is then timed so hits and accents fall on those frames. Tools like a click track keep the players in step with the film.','It makes the music and the on-screen action share the same timing, so accents, cuts, and dramatic beats are underscored at the exact frames the director intends.','A composer scores to a click and to streamers and punches so the orchestra records each cue locked to the picture''s timecode on the scoring stage.','Scoring Technique',ARRAY['Spotting session','Click track','Streamers and punches','Hit point','SMPTE timecode','Tempo fitting']::text[],ARRAY['Assuming a score locked to a click cannot breathe musically, when sync scores still allow rubato within the timing frame.','Confusing synchronization of music to picture with synchronization licensing rights, which is a legal rather than a timing concept.','Ignoring frame-accurate sync points and letting accents drift off the on-screen action.']::text[],ARRAY['Recording an action cue on a scoring stage so each hit lands on the picture.','Building a tempo map so bar-lines fall on scene cuts.','Locking a cue to SMPTE timecode before an orchestra session.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7e1b34ce-0eb6-5636-90a2-e0af568da1b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Synchronization score'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7e1b34ce-0eb6-5636-90a2-e0af568da1b8','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7e1b34ce-0eb6-5636-90a2-e0af568da1b8' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b2e83238-6de1-5251-8057-0528d178866a','Tail-out','A reel of film or audio wound so that the end (tail) of the program is on the outside of the reel, leaving the start (head) on the core; such a reel must be rewound before it can be projected or played from the beginning. Film elements and audio reels are commonly stored and shipped either heads-out or tails-out, and the winding state is labeled so handlers know whether rewinding is required.','A reel can be wound two ways. Tail-out means the end of the program sits on the outside. So the start is buried in the middle. You must rewind it before you can play it from the start. Reels are often stored this way and clearly labeled.','Labeling and winding a reel tail-out signals that it needs rewinding before playback, and for film it can reduce handling by leaving the reel in its last-projected state until it is needed again.','An archivist or projectionist reads the head and tail leader labels, then rewinds a tails-out reel to heads-out before threading it for projection or transfer.','Archival Handling',ARRAY['Heads-out','Film leader','Reel','Rewind','Cue mark']::text[],ARRAY['Threading a tails-out reel onto a projector without rewinding, so the program would run in reverse.','Failing to label the winding state, forcing the next handler to guess heads-out from tails-out.','Assuming every reel is stored heads-out, when many are deliberately kept tails-out.']::text[],ARRAY['Prepping a film reel for a screening and finding it wound tails-out.','Logging archived reels and recording each one''s winding state.','Returning a printed reel to storage wound tails-out after projection.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b2e83238-6de1-5251-8057-0528d178866a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tail-out'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b2e83238-6de1-5251-8057-0528d178866a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b2e83238-6de1-5251-8057-0528d178866a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4549301a-e088-55cb-ac85-bb6412ffd778','Tempo fitting','The process of choosing and adjusting a cue''s tempo — and, where used, its click track — so that bar-lines, downbeats, and accents coincide with the film''s sync points while the cue''s overall duration matches the scene. It may use small tempo variations or a tempo map so several on-screen events fall on musically usable beats.','A cue has to fit the timing of a scene. Tempo fitting is picking a speed that makes the strong beats land on the right moments. The composer nudges the tempo until the accents hit the action. This can mean small speed changes across the cue.','It lets a composer make one piece of music line up with several fixed on-screen events at once, so the score hits the picture without sounding forced.','Using a DAW or a click-book method, a composer or music editor tries tempos and tempo changes until the downbeats fall on the scene''s hit points.','Scoring Technique',ARRAY['Click track','Hit point','Tempo map','Sync point','Streamers and punches','Spotting session']::text[],ARRAY['Picking one rigid tempo and missing sync points that a slight tempo change would have caught.','Fitting the downbeats but ignoring whether the resulting tempo suits the scene''s mood.','Confusing tempo fitting with simply time-stretching finished audio to fit.']::text[],ARRAY['Finding a tempo so a cue''s accents hit three separate action beats.','Building a tempo map so the first downbeat lands on a picture cut.','Adjusting click tempo on the scoring stage to catch a missed hit.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4549301a-e088-55cb-ac85-bb6412ffd778' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tempo fitting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4549301a-e088-55cb-ac85-bb6412ffd778','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4549301a-e088-55cb-ac85-bb6412ffd778' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8fe13158-d1a6-5648-a030-4d9f4613f1cb','Temporal vectorization','In Michel Chion''s theory of audiovision, one of the ways sound temporalizes the image: sound orients a shot or sequence toward a future point, creating a sense of direction, imminence, and expectation that the image alone may not convey. The sound gives the shot a felt trajectory toward an anticipated resolution.','Sound can give a picture a sense of heading somewhere. A held note or a ticking clock makes us feel that something is coming. Michel Chion called this vectorization. The image feels aimed at a future moment. It builds a feeling of waiting.','It explains how a composer or sound designer can make an image feel goal-directed and suspenseful, steering the viewer''s sense of what is about to happen.','A composer writes a rising, unresolved line under a still or ambiguous shot so the audience feels pulled toward the coming event.','Film Music Theory',ARRAY['Temporalization of image','Added value','Synchresis','Tension plateau','Underscore']::text[],ARRAY['Treating vectorization as mere background mood rather than a directional pull toward a future beat.','Assuming the sense of expectation comes from the image when the sound is creating it.','Confusing vectorization with simple increases in tempo or loudness.']::text[],ARRAY['Scoring a still shot so it feels charged with something about to happen.','Using an unresolved sustained chord to build anticipation before a reveal.','Adding a rhythmic pulse that makes a slow scene feel goal-directed.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8fe13158-d1a6-5648-a030-4d9f4613f1cb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Temporal vectorization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8fe13158-d1a6-5648-a030-4d9f4613f1cb','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8fe13158-d1a6-5648-a030-4d9f4613f1cb' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '001e02a9-c721-5144-a375-137124ad2ae4','Temporalization of image','In Michel Chion''s audiovisual theory, the process by which sound gives temporal structure to images that in themselves may be static or temporally ambiguous. Chion distinguishes three aspects: temporal animation (how sharply time is felt), temporal linearization (imposing a sequential, real-time flow), and vectorization (orienting the image toward a future). It is a central mechanism of what he calls added value.','On their own, some shots feel frozen or timeless. Sound can give them a flow of time. Michel Chion called this the temporalization of the image. The sound sets the pace, puts events in order, and points them forward. We then feel that time as if it came from the picture.','It explains how sound, not the image, often supplies a scene''s sense of pace, continuity, and forward motion, which composers and sound designers use to shape how time is felt.','A sound team adds rhythm or continuous sound under a montage of stills so the shots read as a flowing, real-time sequence rather than separate frozen images.','Film Music Theory',ARRAY['Temporal vectorization','Added value','Synchresis','Underscore','Kinetics']::text[],ARRAY['Crediting the picture with a sense of time that the soundtrack is actually providing.','Assuming temporalization only means matching tempo, ignoring ordering and direction.','Overlooking that removing the sound can leave the images feeling static and out of time.']::text[],ARRAY['Scoring a slideshow-like montage so it feels like continuous real time.','Using a steady pulse to give a dreamlike sequence a clear flow.','Analyzing why a silent scene feels timeless until sound is added.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='001e02a9-c721-5144-a375-137124ad2ae4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Temporalization of image'),'[^a-z0-9]','','g'));
