INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e3a9a214-5a39-5eca-83e3-80851908746b','Tension plateau','A passage of underscore that establishes and then sustains a steady, elevated level of dramatic tension without building to a climax or releasing, holding the audience in a prolonged state of unease. It functions as a flat region in the score''s tension curve, as opposed to a rising build or a resolving release.','Film music often rises to a peak and then relaxes. A tension plateau instead holds the tension flat. The music keeps the audience on edge for a long stretch. It does not climb higher, and it does not let go. This suits scenes of steady dread.','It lets a composer keep a scene taut over time, holding suspense through a sustained threat rather than spending it in a single peak.','A composer holds a sustained dissonant texture or ostinato at a constant intensity under a long suspense sequence, avoiding resolution until the scene demands it.','Scoring Technique',ARRAY['Underscore','Ostinato','Drone','Temporal vectorization','Hit point']::text[],ARRAY['Letting the level drift upward so the plateau becomes a build and loses its held quality.','Resolving the harmony too early and releasing tension the scene still needs.','Confusing a held tension plateau with a lack of musical movement or interest.']::text[],ARRAY['Underscoring a long stakeout or standoff at a constant level of unease.','Holding dread steady through an extended horror sequence.','Sustaining suspense across a scene before a later release.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e3a9a214-5a39-5eca-83e3-80851908746b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tension plateau'),'[^a-z0-9]','','g'));
