SELECT 'e3a9a214-5a39-5eca-83e3-80851908746b','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e3a9a214-5a39-5eca-83e3-80851908746b' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2cff3b62-f44b-557a-a18c-41293f4ad368','Textural leitmotif','A leitmotif whose recurring identity is carried by a distinctive musical texture — such as a particular chordal density, figuration, or layering — rather than by a memorable melodic theme. The texture itself becomes the recurring signifier associated with a character, place, or idea.','A leitmotif is a musical idea that returns to stand for a character or theme. Usually it is a tune. A textural leitmotif uses a certain sound-texture instead of a melody. The same layered pattern returns to signal the same idea. You know it by its feel, not its tune.','It gives a composer a way to tag a character or idea recognizably when a hummable theme is unwanted, using a consistent texture as the recurring marker.','A composer reuses a specific shimmering cluster or rhythmic figuration whenever a certain force appears, so audiences feel its presence without a stated melody.','Thematic Device',ARRAY['Leitmotif','Timbral leitmotif','Texture','Ostinato','Underscore']::text[],ARRAY['Assuming every leitmotif must be a melody, and missing texture-based recurring ideas.','Making the texture too generic, so it fails to read as a specific recurring signifier.','Confusing a textural leitmotif with ordinary background scoring that carries no associative meaning.']::text[],ARRAY['Signaling a looming force with a recurring layered cluster rather than a tune.','Giving an abstract idea a consistent textural sound across a film.','Reusing a rhythmic figuration as a character''s identifying sound.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2cff3b62-f44b-557a-a18c-41293f4ad368' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Textural leitmotif'),'[^a-z0-9]','','g'));
