INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '83b07fd6-03b5-5302-bc92-a4db55a41e27','Theme stem','A stem — a submix of the music bounced as a separate audio group — that isolates a particular musical theme or thematic layer within a cue, so it can be balanced, muted, or reused independently of the rest of the score. It is a thematic subdivision of the music stems delivered in post-production.','A stem is a submix: a group of tracks bounced together as one file. A theme stem holds just one theme''s music on its own. Keeping it separate lets the mix team raise, lower, or reuse that theme alone. This helps when the theme must sit under dialogue.','It gives the re-recording mixer independent control of a theme''s level and reuse, and supports later edits or versions without remixing the whole cue.','A composer delivers the main theme on its own stem so the dub mixer can lift it under a key moment or duck it beneath dialogue.','Deliverables',ARRAY['Stem','Submix','Re-recording mix','Leitmotif','Music editing']::text[],ARRAY['Baking the theme into a full mix so it cannot be adjusted on its own later.','Confusing a music stem with a single instrument track or the final printmaster.','Delivering stems with overlapping content, so raising the theme stem double-tracks the music.']::text[],ARRAY['Delivering a hero theme on its own stem for the final dub.','Ducking a theme stem under dialogue in the re-recording mix.','Reusing a theme stem for a trailer without the rest of the cue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='83b07fd6-03b5-5302-bc92-a4db55a41e27' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Theme stem'),'[^a-z0-9]','','g'));
