SELECT '83b07fd6-03b5-5302-bc92-a4db55a41e27','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='83b07fd6-03b5-5302-bc92-a4db55a41e27' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7f0624ee-5e48-519b-9eb0-2f64fffa1c61','Timbral leitmotif','A leitmotif whose recurring identity is carried primarily by a specific timbre or instrumental color — a particular instrument, ensemble, or sound associated with a character, place, or idea — rather than by melodic contour alone. The return of that sound signals the association even when the melodic material changes.','A leitmotif is a musical idea tied to a character or theme. A timbral leitmotif ties the idea to a certain sound instead of a tune. For example, a character may always be marked by a solo cello. When you hear that sound, you know who is near.','It lets a composer identify a character or idea by instrumental color, which is recognized quickly and can carry meaning even when the melody varies.','A composer assigns a distinctive instrument or synth patch to a character and brings that timbre back whenever the character''s presence should be felt.','Thematic Device',ARRAY['Leitmotif','Textural leitmotif','Timbre','Orchestration','Underscore']::text[],ARRAY['Choosing a timbre that is too common to read as a specific character''s marker.','Assuming only melody can carry a leitmotif and overlooking instrumental color.','Changing the associated instrument each time, so the timbral link is lost.']::text[],ARRAY['Marking a villain with a specific low brass color across a film.','Signaling a character by their instrument even under a new melody.','Choosing an unusual timbre so a theme is instantly recognizable.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7f0624ee-5e48-519b-9eb0-2f64fffa1c61' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timbral leitmotif'),'[^a-z0-9]','','g'));
