INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '29b32028-017a-532d-bffb-285422813fb8','Timing note','A note specifying the precise timing of an on-screen event — given in seconds and frames, or in feet and frames, relative to the cue''s start or to timecode — supplied to the composer, usually by the music editor from the spotting session, so that music can be written to land on that event. A cue''s timing notes together form a detailed breakdown of the moments the music should catch.','A timing note tells the composer exactly when something happens on screen. It gives a time, such as a certain second and frame, for a hit or a cut. The composer uses it to place the music on that moment. The music editor usually writes these notes during spotting.','It turns on-screen events into exact times the composer can score to, so the music hits the intended moments accurately.','A music editor lists timing notes for each cue, and the composer builds the tempo and accents so the music lands on those marked times.','Music Editing',ARRAY['Spotting session','Hit point','Sync point','Streamers and punches','Music editor','SMPTE timecode']::text[],ARRAY['Recording a timing without its frame count, leaving the composer to guess the exact moment.','Referencing timings to the wrong start point, such as reel start instead of cue start.','Treating soft, flexible moments as if every timing note were a frame-exact hard hit.']::text[],ARRAY['Writing timing notes during a spotting session for each planned cue.','Giving the composer feet-and-frames timings for every hit in a cue.','Checking a cue against its timing notes before the scoring session.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='29b32028-017a-532d-bffb-285422813fb8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timing note'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '29b32028-017a-532d-bffb-285422813fb8','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='29b32028-017a-532d-bffb-285422813fb8' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ee81ec6c-7bbf-5c31-acc8-52d70f0c3836','Tonal pairing','An analytical concept in which two tonal centers, often a third or other interval apart, are held in an unresolved, mutually defining relationship across a passage or whole work, so that neither is unambiguously subordinate to the other. Associated with the nineteenth-century ''double-tonic complex'' (Robert Bailey), it treats decentered interaction between key areas as a structural alternative to a single, unitary tonic hierarchy.','Most music has one clear home key. Tonal pairing is when two keys share the spotlight. Neither one fully wins as the home base. Composers use this to keep music feeling open or unsettled. Film scores borrow it for scenes with mixed emotions.','It lets composers build large-scale tension and ambiguity by playing two key centers against each other, expanding harmonic expression beyond a single governing tonic.','A film composer voices a cue around two competing key centers so a scene feels unresolved, delaying commitment to one tonic until a dramatic turning point.','Harmony',ARRAY['Tonal teleology','Double-tonic complex','Directional tonality','Tonic','Modulation','Leitmotif']::text[],ARRAY['Assuming any modulation equals tonal pairing; pairing needs two centers held in ongoing tension, not a simple key change.','Treating one of the two keys as the ''real'' tonic and the other as a passing area, which collapses the pairing.','Confusing tonal pairing with bitonality, where two keys sound at the same time rather than competing over a span.']::text[],ARRAY['Analyzing a Romantic-era cue that never settles between two related keys.','Scoring an ambiguous scene by balancing two tonal centers to withhold resolution.','Studying a leitmotif that shifts its harmonic home between two keys.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ee81ec6c-7bbf-5c31-acc8-52d70f0c3836' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tonal pairing'),'[^a-z0-9]','','g'));
