SELECT 'ee81ec6c-7bbf-5c31-acc8-52d70f0c3836','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ee81ec6c-7bbf-5c31-acc8-52d70f0c3836' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '61c0cd88-b791-55cc-a684-cd53edb9ec39','Tonal teleology','The goal-directed quality of tonal music: the way harmonic events are heard as purposefully moving toward a tonal goal, typically a cadence or structural resolution on the tonic. It frames a passage''s harmony as a directed process with implied points of arrival rather than a static succession of chords.','Teleology means moving toward a goal. In tonal music, chords feel like they are heading somewhere. They pull toward a resting point, usually the home chord. This forward pull is tonal teleology. Composers use it to make music feel like it is going somewhere.','It explains why tonal music feels like it is ''going somewhere,'' giving harmony a sense of momentum and expectation that composers exploit to shape tension and release.','A composer delays an expected cadence to stretch the sense of forward pull, timing the harmonic arrival to land on a dramatic beat in the picture.','Harmony',ARRAY['Tonal pairing','Cadence','Tonic','Harmonic rhythm','Resolution','Modulation']::text[],ARRAY['Thinking teleology is about a single chord rather than the directed motion of a whole progression toward a goal.','Assuming all music is teleological; much modal, static, or ambient scoring deliberately avoids goal-directed motion.','Confusing the tonal goal with simply the last chord, ignoring the structural arrival that defines it.']::text[],ARRAY['Building a cue that drives harmonically toward a resolution on a key story beat.','Deliberately writing static, non-teleological harmony for an ambiguous or suspended mood.','Analyzing how a progression sets up and then delays its expected arrival.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='61c0cd88-b791-55cc-a684-cd53edb9ec39' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tonal teleology'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '61c0cd88-b791-55cc-a684-cd53edb9ec39','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='61c0cd88-b791-55cc-a684-cd53edb9ec39' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '97d5c8e2-0aa4-5a4e-9723-e544bc03eedb','Top-and-tail scoring','A scoring approach in which music is placed only at the beginning (''top'') and end (''tail'') of a scene, sequence, or program, leaving the intervening section unscored. It bookends the material with music while keeping the middle dry, letting dialogue, effects, or silence carry the center.','This means putting music only at the start and end of a scene. The middle is left without any score. It is like bookends holding up a shelf. The music opens and closes the scene. It stays out of the middle.','It frames a scene with musical mood at its entrances and exits while leaving the middle clear for dialogue or tension, controlling where the audience feels a score.','A composer spots a dialogue-heavy scene to open on a short cue and close on another, writing nothing under the conversation in between.','Scoring Technique',ARRAY['Spotting','Cue','Underscore','Source music','Vamp-out','Bookend']::text[],ARRAY['Confusing it with trimming the silent head and tail of an audio clip, which is a different editing task.','Leaving the middle unscored by accident rather than as a deliberate dramatic choice.','Adding a music tail that overlaps the next scene''s start and muddies the transition.']::text[],ARRAY['Opening and closing a talky scene with brief cues while leaving the dialogue unscored.','Bookending a montage with music at its start and finish.','Scoring only the intro and outro of a television segment.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='97d5c8e2-0aa4-5a4e-9723-e544bc03eedb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Top-and-tail scoring'),'[^a-z0-9]','','g'));
