WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='97d5c8e2-0aa4-5a4e-9723-e544bc03eedb' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e1b6c563-77a5-5ff8-b3dc-5679fd05a84f','Topic transformation','In musical topic theory, the reworking of a recognizable musical topic — a conventional figure such as a march, hunt, pastoral, or lament that carries cultural meaning — through variation, combination, or ironic recontextualization (''troping''), so its expected signification is altered or layered. The transformed topic conveys a new or complicated meaning while remaining recognizable.','A musical topic is a familiar style that carries meaning, like a march or a lullaby. Topic transformation changes that style on purpose. The composer bends or mixes it so it means something new. Listeners still recognize it, but they feel the twist.','It lets composers use shared musical conventions as raw material, reshaping their meaning to comment on, subvert, or deepen the drama a cue supports.','A film composer states a heroic march topic and gradually distorts it — minor mode, unstable harmony — to show a hero''s corruption across the story.','Music Theory',ARRAY['Leitmotif','Musical topic','Troping','Motivic development','Underscore','Tonal pairing']::text[],ARRAY['Treating a topic as a fixed label rather than material that can be varied and recombined.','Assuming the audience must consciously name the topic; its cultural meaning works even when unnamed.','Confusing topic transformation with simple thematic variation that carries no shift in meaning.']::text[],ARRAY['Turning a pastoral topic dark to signal a threat entering an idyllic scene.','Combining a military topic with a lament to complicate a battle''s tone.','Tracking how a film''s main theme shifts its topic as a character changes.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e1b6c563-77a5-5ff8-b3dc-5679fd05a84f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Topic transformation'),'[^a-z0-9]','','g'));
