INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd0477868-c954-5a2c-9048-e7f744ca42f9','Transition module','A self-contained, reusable segment of music written to connect two other sections or cues — bridging from one musical state, key, tempo, or mood to another. Common in adaptive/interactive scoring and production-music libraries, it functions as a modular building block dropped in between other modules to smooth a transition.','A transition module is a short piece of music that links two other pieces. It bridges from one section to the next. Think of it as a musical ramp between two rooms. Game and library composers keep these ready to reuse.','It provides a ready-made musical bridge so sections with different tempo, key, or mood can be joined smoothly, which matters when music must adapt on the fly to changing picture or gameplay.','A game composer writes short transition modules that the audio engine triggers to move between an exploration cue and a combat cue without an abrupt cut.','Scoring Technique',ARRAY['Cue','Stinger','Vamp-to-hit','Adaptive music','Transition','Loop']::text[],ARRAY['Writing a transition that only works from one specific tempo or key, defeating its reusable purpose.','Making the module too long, so it lags behind the on-screen or in-game change it should cover.','Forgetting to match the module''s entry and exit points to the surrounding cues, causing a jump.']::text[],ARRAY['Bridging exploration and combat music in a video game score.','Connecting two library cues of different moods for a montage.','Smoothing a key change between two sections of an adaptive cue.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d0477868-c954-5a2c-9048-e7f744ca42f9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transition module'),'[^a-z0-9]','','g'));
