INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c1ab81e9-d2f2-5ef9-bc1d-f5e5d97e9901','Under-dialogue corridor','The restricted range of level and frequency within which underscore is kept while dialogue is present, so the music supports the scene without masking or competing with speech. In practice it describes the low-level, spectrally-carved ''lane'' the score occupies beneath dialogue, reinforced by ducking, EQ, and arrangement choices that leave the vocal range clear.','When people talk on screen, the music must stay out of the way. The under-dialogue corridor is the narrow space the score fits into. It sits low in volume. It also avoids the frequencies of the voice. This keeps the talking clear.','It keeps the score audible but subordinate during dialogue, protecting speech intelligibility while still letting music color the scene.','A composer arranges a cue low and away from the vocal midrange, and a mixer ducks and EQs it, so the music stays inside the space left for dialogue.','Scoring Technique',ARRAY['Underscore','Ducking','Dialogue','Spotting','Stem','Frequency masking']::text[],ARRAY['Scoring in the same midrange as the voice, so the music masks the dialogue even at a low level.','Relying only on volume ducking and ignoring arrangement and EQ that keep the vocal range clear.','Making the corridor so narrow the music becomes inaudible and adds nothing to the scene.']::text[],ARRAY['Arranging a cue to sit under a conversation without burying the words.','A re-recording mixer carving EQ and ducking music around dialogue.','Choosing sparse instrumentation so the score fits beneath a busy dialogue scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c1ab81e9-d2f2-5ef9-bc1d-f5e5d97e9901' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Under-dialogue corridor'),'[^a-z0-9]','','g'));
