INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0dcc8987-c9b4-510b-879e-680ff5e036fc','Vamp-out','A cue ending in which a short passage (a vamp) is repeated to fill time until a cutoff or fade, rather than resolving through a fixed, notated ending. The players hold on the repeated figure until cued to stop, letting the music tail out flexibly to hit a picture point or downbeat.','A vamp is a short bit of music repeated over and over. A vamp-out ends a cue by looping this bit. The players keep repeating until they get a signal to stop. This lets the music end right on a chosen moment. It is a flexible way to finish a cue.','It gives a cue a flexible, open-ended tail so its stopping point can be adjusted to match picture timing without rewriting the ending.','A composer marks a two-bar vamp at the end of a cue so the conductor can repeat it until the exact frame of a cut, then cut off.','Scoring Technique',ARRAY['Vamp-to-hit','Cue','Wild ending','Click track','Cutoff','Fade']::text[],ARRAY['Writing a vamp that is harmonically closed, so repeating it sounds like a wrong restart rather than a hold.','Failing to mark a clear cutoff cue, leaving players unsure when to stop.','Confusing a vamp-out with a written ritardando ending, which has a fixed, notated close.']::text[],ARRAY['Repeating a final figure until the scene cuts, then cutting off.','Holding a cue''s ending open while an edit is still being finalized.','Tailing music out to a fade under the start of the next scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0dcc8987-c9b4-510b-879e-680ff5e036fc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vamp-out'),'[^a-z0-9]','','g'));
