SELECT '0dcc8987-c9b4-510b-879e-680ff5e036fc','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0dcc8987-c9b4-510b-879e-680ff5e036fc' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'beec4978-cb78-54c5-96a0-4095a45fb13a','Vamp-to-hit','A conducting-and-timing device in which the ensemble repeats a vamp (a short looping passage) until a specific sync point or ''hit'' in the picture is reached, at which point the conductor cues the music to proceed or land on the accent. It provides flexible timing to catch a visual hit without locking the whole cue to a rigid click.','A hit is a moment in the film the music must match, like a punch landing. Vamp-to-hit means looping a short passage until that moment comes. The conductor watches the picture. On the hit, the music moves on or accents it. This catches the moment without a strict click.','It lets performers catch an exact picture moment while keeping the surrounding music free of a rigid click, trading metronomic lock for a repeated holding pattern.','A conductor loops a written vamp while watching a streamer, then drives the orchestra onto the downbeat exactly as the on-screen hit occurs.','Sync Technique',ARRAY['Vamp-out','Hit point','Streamers and punches','Click track','Free timing','Cue']::text[],ARRAY['Writing a vamp too long to loop cleanly, so the conductor cannot land the hit precisely.','Assuming vamp-to-hit removes the need to watch the picture; the conductor must still catch the visual cue.','Confusing it with a fixed click, which cannot flex to an uncertain hit time.']::text[],ARRAY['Holding on a vamp until an on-screen explosion, then hitting the accent.','Catching an action beat whose exact timing varies between takes.','Bridging to a downbeat that must land on a hard cut in the edit.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='beec4978-cb78-54c5-96a0-4095a45fb13a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vamp-to-hit'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'beec4978-cb78-54c5-96a0-4095a45fb13a','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='beec4978-cb78-54c5-96a0-4095a45fb13a' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc74db72-6727-5fdc-8c4e-e6d30d34750d','Variable click','A click track whose tempo and/or meter change over the course of a cue — through programmed accelerandos, ritardandos, or beat-value and time-signature changes — rather than staying at one fixed tempo. It lets performers stay locked to a metronomic reference while the music speeds up, slows down, or shifts meter to catch picture.','A click track is a metronome the players hear in headphones. A variable click changes speed as the cue goes on. It can speed up, slow down, or change the beat. This lets the music bend to the picture while everyone stays together.','It keeps an orchestra tightly synchronized while allowing the tempo to move, so a cue can accelerate, relax, or change meter and still land on precise picture points.','A composer programs tempo changes into the click so the orchestra can push into an action beat and pull back afterward, all while staying locked to the same reference.','Click & Sync',ARRAY['Written click','Click track','Streamers and punches','Tempo map','Vamp-to-hit','Hit point']::text[],ARRAY['Assuming every click is a steady tempo; a variable click changes and must be rehearsed carefully.','Programming tempo changes too abruptly for players to follow cleanly.','Confusing a variable click with free timing, where there is no click reference at all.']::text[],ARRAY['Programming an accelerando into the click for a chase cue.','Changing meter mid-cue to catch a series of irregular hits.','Relaxing the tempo at a cue''s end while staying locked to the reference.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc74db72-6727-5fdc-8c4e-e6d30d34750d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Variable click'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dc74db72-6727-5fdc-8c4e-e6d30d34750d','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dc74db72-6727-5fdc-8c4e-e6d30d34750d' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9aa2aa2a-5c76-5e1e-a717-e1c35c77ed6e','Wild ending','An ending recorded ''wild'' — played freely by the ensemble without a click or strict sync to picture — so the final gesture, ritardando, and cutoff can be shaped naturally. It is often recorded as an alternate to a locked ending, giving the music editor a more organic close to cut to.','Wild means played freely, not locked to a click or the picture. A wild ending lets the players finish a cue in a natural way. They can slow down and cut off as it feels right. The editor can then choose this looser ending.','It captures a natural, musically shaped close — one a click-locked take can make sound stiff — giving the edit an expressive option for a cue''s final moments.','After recording a cue to click, the composer has the orchestra play just the last phrase wild so the ritardando and final chord breathe.','Recording Technique',ARRAY['Wild take','Vamp-out','Free timing','Click track','Cutoff','Alternate take']::text[],ARRAY['Recording a wild ending with no reference pitch or tempo, so it will not edit back to the click-locked body.','Forgetting to slate it clearly as the wild alternate, causing confusion in the edit.','Assuming a wild ending can always be synced to a hard picture point, when its flexible timing may not line up.']::text[],ARRAY['Capturing a natural ritardando on a cue''s final phrase.','Recording a free, breathing final chord as an alternate to the locked ending.','Giving the music editor an organic close to cut to for an emotional scene.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9aa2aa2a-5c76-5e1e-a717-e1c35c77ed6e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wild ending'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9aa2aa2a-5c76-5e1e-a717-e1c35c77ed6e','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9aa2aa2a-5c76-5e1e-a717-e1c35c77ed6e' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2495cd04-7a1f-5313-938d-33340d710a5d','Wild take','A take recorded ''wild'' — without synchronization to picture, click, or timecode — so the performance is free of a fixed timing reference. In scoring, a cue or section played wild can later be placed or edited against picture, trading exact sync for natural, unconstrained phrasing.','Wild means recorded free, not locked to the picture or a click. A wild take lets the players perform without a metronome. The timing is natural, not strict. The editor can place or trim it against the film later.','It captures an expressive, naturally-phrased performance unconstrained by a click, which the music editor can then fit to picture in the edit.','A composer records a solo passage wild so the player can rubato freely, then the music editor aligns key moments to picture afterward.','Recording Technique',ARRAY['Wild ending','Free timing','Click track','Take','Wild track','Music editor']::text[],ARRAY['Recording everything wild and assuming it will sync tightly to picture, when free timing may not line up.','Not capturing a reference tempo or guide, making the wild take hard to edit against the score.','Confusing a wild take (no sync) with a click take, which is locked to a timing reference.']::text[],ARRAY['Recording a rubato solo free of the click for natural phrasing.','Capturing a cue wild when no exact hits must be caught.','Giving the editor a freely-played alternate to place against picture.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2495cd04-7a1f-5313-938d-33340d710a5d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wild take'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2495cd04-7a1f-5313-938d-33340d710a5d','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2495cd04-7a1f-5313-938d-33340d710a5d' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '030e2828-0104-5b9c-bb41-6ed40300a8c1','Written click','A click track whose tempo and meter follow the tempi and time-signature changes the composer has written into the score, so the click is generated directly from the notated tempo map. It provides a fixed metronomic reference tied to the written music, as distinct from free timing, which uses no click at all.','A click track is a metronome the players hear. A written click follows the tempos the composer wrote in the score. The click matches the notated music exactly. Players stay together on the beat the page shows.','It ties the performers'' click reference directly to the written tempo map, so the orchestra plays the cue at the speeds and meters the composer notated while staying synchronized.','A composer enters tempo and meter changes into the notation software, and the click is generated from that written tempo map for the session.','Click & Sync',ARRAY['Variable click','Click track','Tempo map','Streamers and punches','Free timing','Hit point']::text[],ARRAY['Assuming the written tempo will automatically catch every picture hit, when hits may need tempo tweaks or streamers.','Entering tempo changes carelessly in the software, so the click drifts from the intended timings.','Confusing a written click with free timing, where the players follow no click at all.']::text[],ARRAY['Generating the session click from the tempo map in the notation software.','Playing a cue to the composer''s written tempo and meter changes.','Checking that the written click lands the cue on its intended hit points.']::text[],'5a9583b4-3e21-4c4a-a304-3497a4d54ff0'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='030e2828-0104-5b9c-bb41-6ed40300a8c1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Written click'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '030e2828-0104-5b9c-bb41-6ed40300a8c1','5a9583b4-3e21-4c4a-a304-3497a4d54ff0',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='030e2828-0104-5b9c-bb41-6ed40300a8c1' AND gt.achievement_id='5a9583b4-3e21-4c4a-a304-3497a4d54ff0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ae142f0b-7a11-512f-929d-5d8aff4fb664','ADR seating','The craft of blending automated dialogue replacement (ADR) into a scene so the re-recorded line matches the original production sound in level, tonal balance, perspective, and ambience. Seating uses EQ, reverb/room matching, worldizing, and level rides so a clean studio take sits convincingly among the surrounding production dialogue.','ADR means dialogue an actor re-records in a studio after filming. Seating that line means blending it into the scene. The mixer matches its loudness, tone, and room echo. Done well, viewers never notice the swap.','It makes studio-recorded replacement lines sound as if they were captured on location, preserving the illusion of one continuous performance and acoustic space.','A re-recording mixer adds matching room reverb and EQ to an ADR take and rides its level so it blends seamlessly with adjacent production dialogue.','ADR & Dialogue',ARRAY['ADR stem','Center-channel anchoring','Dialogue stem','Worldizing','Production dialogue','Reverb matching']::text[],ARRAY['Leaving the ADR line dry and up-front so it sounds detached from the room the scene was shot in.','Matching only level while ignoring EQ, perspective, and reverb, so the re-voiced line still stands out.','UNSAFE: Monitoring the dubbing stage at high SPL for long stretches while fine-tuning the mix risks permanent noise-induced hearing loss; keep exposure within OSHA limits (90 dBA time-weighted over 8 hours, 85 dBA action level) and take listening breaks.']::text[],ARRAY['Blending a studio-recorded line into an exterior scene with traffic and wind.','Matching an ADR replacement to the reverberant tone of a large interior location.','Seating a censored word replacement so it disappears into surrounding dialogue.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ae142f0b-7a11-512f-929d-5d8aff4fb664' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR seating'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ae142f0b-7a11-512f-929d-5d8aff4fb664','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ae142f0b-7a11-512f-929d-5d8aff4fb664' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e989cc23-17e5-5edb-ae63-b071e9b652ec','ADR stem','A mix stem containing only the automated dialogue replacement (ADR) content, kept separate from production dialogue and other elements so it can be balanced, muted, or re-versioned independently. It is one component of the dialogue group within the broader dialogue/music/effects (DME) stem structure delivered from a final mix.','A stem is a submix of one group of sounds kept on its own. An ADR stem holds the re-recorded dialogue by itself. Keeping it separate lets people change the voices later. It helps when a film is dubbed into other languages.','It isolates re-recorded dialogue so it can be adjusted, replaced, or re-versioned later, which is essential for foreign-language dubbing, edits for broadcast, and archival deliverables.','During the final mix a re-recording mixer routes ADR to its own stem so the deliverable lets a foreign-language house swap dialogue without touching music and effects.','Stems & Deliverables',ARRAY['ADR seating','Dialogue stem','DME stems','Print master','Fold-down','M&E']::text[],ARRAY['Bouncing ADR into the production dialogue stem, which prevents clean replacement for dubbed versions.','Assuming the ADR stem is a final deliverable by itself rather than one component of the DME stem set.','UNSAFE: Monitoring the dubbing stage at high SPL for long stretches while fine-tuning the mix risks permanent noise-induced hearing loss; keep exposure within OSHA limits (90 dBA time-weighted over 8 hours, 85 dBA action level) and take listening breaks.']::text[],ARRAY['Delivering separated stems so a distributor can create a foreign-language version.','Muting the ADR stem to check how much of a scene relies on replacement lines.','Archiving dialogue elements separately for future remixes or restorations.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e989cc23-17e5-5edb-ae63-b071e9b652ec' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR stem'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e989cc23-17e5-5edb-ae63-b071e9b652ec','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e989cc23-17e5-5edb-ae63-b071e9b652ec' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'df7611dc-81a6-59c4-93aa-940ebe1b7992','Articulation lift','A targeted upper-midrange boost, typically in the roughly 2-5 kHz presence band, applied to dialogue to strengthen consonant articulation and intelligibility. It emphasizes the frequency region that carries most consonant information, helping speech remain clear against music and effects.','Consonants like S, T, and K make speech clear. An articulation lift is a small boost around 2 to 5 kHz. It brings out those consonants so words are easier to follow. Mixers use it to help dialogue cut through music and effects.','It raises the consonant-rich presence band so dialogue stays intelligible within a dense mix, directly supporting the priority that speech must be understood.','A re-recording mixer adds a gentle few-dB shelf or bell around 3 kHz on a dialogue premix so lines cut through a loud action sequence.','Dialogue EQ',ARRAY['Brittle consonants','Boxiness carve','Presence','De-essing','Intelligibility','Dialogue stem']::text[],ARRAY['Over-boosting the presence band, which turns clarity into harsh, brittle, sibilant dialogue.','Adding a broad lift to fix a masking problem that a level ride or music duck would solve better.','UNSAFE: Monitoring the dubbing stage at high SPL for long stretches while fine-tuning the mix risks permanent noise-induced hearing loss; keep exposure within OSHA limits (90 dBA time-weighted over 8 hours, 85 dBA action level) and take listening breaks.']::text[],ARRAY['Lifting consonants on a soft-spoken actor so lines read over a busy soundscape.','Restoring intelligibility on a muffled production recording.','Helping dialogue survive a fold-down to a small television speaker.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='df7611dc-81a6-59c4-93aa-940ebe1b7992' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Articulation lift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
