WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='df7611dc-81a6-59c4-93aa-940ebe1b7992' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '08264e85-72b1-52af-b515-26486b1a9611','Audio-visual speech translation','The automated translation of spoken content from one language to another using both the audio signal and visual speech cues, chiefly lip and mouth movements, from the speaker; unlike speech-to-speech translation, the target may be rendered as text or as speech. Incorporating the visual modality improves robustness, particularly in acoustically noisy conditions where audio alone degrades.','This is computer translation of speech from one language to another. It uses both the sound and the video of the mouth moving. Watching the lips helps the system hear better in noisy scenes. It is used to help dub films and videos.','It exploits visual speech information to make automatic translation more accurate and noise-robust than audio-only systems, supporting applications like film dubbing and accessibility.','A localization tool feeds both the actor''s voice and mouth video into a model so translation stays accurate even when the scene has heavy background noise.','Automatic Dubbing',ARRAY['Audio-visual speech-to-speech translation','Automatic dubbing','Cascaded dubbing','Automated dubbing pipeline','Lip sync']::text[],ARRAY['Assuming the visual channel is optional; it is what provides robustness when the audio is noisy.','Confusing it with lip reading alone, when it fuses audio and visual cues together.','Treating machine output as broadcast-ready without human review of accuracy and timing.']::text[],ARRAY['Translating an interview clip where background noise degrades the audio.','Assisting dubbing localization for streaming content.','Researching noise-robust translation for on-set or field capture.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='08264e85-72b1-52af-b515-26486b1a9611' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Audio-visual speech translation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '08264e85-72b1-52af-b515-26486b1a9611','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='08264e85-72b1-52af-b515-26486b1a9611' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cd7056d3-d3ca-5444-b368-db749de2a4b4','Audio-visual speech-to-speech translation','Speech-to-speech translation that converts spoken input in a source language directly into spoken output in a target language while using visual speech cues (lip and mouth movements) alongside the audio. The visual stream improves translation accuracy and noise robustness compared with audio-only speech-to-speech systems.','Here a computer turns spoken words in one language into spoken words in another. It listens to the voice and also watches the lips. The lip movements help it stay accurate when there is background noise. The result is new speech, not just text.','It produces translated speech end-to-end while using the mouth video to stay accurate in noise, aiming at natural dubbing and real-time cross-language communication.','A dubbing research pipeline uses both voice and face video to generate a translated spoken track that holds up on noisy source material.','Automatic Dubbing',ARRAY['Audio-visual speech translation','Automatic dubbing','Cascaded dubbing','Automated dubbing pipeline','Text-to-speech']::text[],ARRAY['Expecting the output to lip-sync perfectly to the original picture without extra alignment steps.','Assuming it replaces skilled dubbing mixers rather than assisting a localization workflow.','Ignoring that visual cues mainly help in noise and are not a cure for a weak translation model.']::text[],ARRAY['Generating a translated voice track for noisy documentary footage.','Prototyping real-time cross-language conversation with camera input.','Comparing audio-only and audio-visual models on degraded recordings.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cd7056d3-d3ca-5444-b368-db749de2a4b4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Audio-visual speech-to-speech translation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cd7056d3-d3ca-5444-b368-db749de2a4b4','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cd7056d3-d3ca-5444-b368-db749de2a4b4' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9398b987-6e3f-52c6-a6bd-dace37e91605','Automated dubbing pipeline','The chained sequence of processing stages that converts source-language speech into a translated, timing-matched spoken track, typically automatic speech recognition, machine translation, prosodic/length alignment, and text-to-speech, followed by audio rendering that adds background and reverberation. Each stage feeds the next to produce a dubbed output.','A pipeline is a chain of steps that run in order. An automated dubbing pipeline turns speech into a translated voice track. First it writes down the words, then translates them, then speaks them. It also fits the new speech to the original timing.','It structures dubbing as modular automated stages so each task (recognition, translation, timing, synthesis, rendering) can be built and improved separately while producing a coherent dubbed track.','A localization engineer configures the pipeline so machine translation is length-constrained and the synthesized voice is fitted to each original utterance''s duration.','Automatic Dubbing',ARRAY['Automatic dubbing','Cascaded dubbing','Audio-visual speech-to-speech translation','Prosodic alignment','Text-to-speech']::text[],ARRAY['Ignoring prosodic alignment and length control, so translated speech no longer fits the original timing.','Assuming errors do not accumulate; a mistake early in the chain propagates to the final voice.','Skipping the rendering stage, leaving synthesized voice dry and detached from the original scene.']::text[],ARRAY['Building a system to dub lecture videos into several languages.','Tuning length-controlled translation so lines fit the on-screen timing.','Adding background and reverb so the dubbed voice matches the original space.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9398b987-6e3f-52c6-a6bd-dace37e91605' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Automated dubbing pipeline'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9398b987-6e3f-52c6-a6bd-dace37e91605','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9398b987-6e3f-52c6-a6bd-dace37e91605' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1704174c-c925-5996-879c-67382bd32ba2','Automatic dubbing','The automated replacement of original-language speech in audio-visual content with translated speech, performed by software rather than human voice talent and mixers. It adapts speech-to-speech translation with prosodic alignment and length (isometric) control so the translated voice matches the timing and delivery of the source.','Dubbing replaces the original speech with a translated version. Automatic dubbing does this with software instead of by hand. The computer translates the lines and speaks them in the new language. It also tries to match the timing and feel of the original.','It aims to scale localization by generating translated, timing-matched voice tracks automatically, reducing the cost and turnaround of traditional voice-cast dubbing.','A streaming platform runs automatic dubbing to produce draft translated tracks for many titles, which human editors then review and refine.','Automatic Dubbing',ARRAY['Automated dubbing pipeline','Cascaded dubbing','Audio-visual speech translation','Prosodic alignment','ADR']::text[],ARRAY['Expecting the isometric constraint alone to guarantee lip-sync; timing fit is not the same as visual sync.','Treating automatic output as final rather than a draft for human quality control.','Assuming one voice model captures the emotion and character of the original performance.']::text[],ARRAY['Producing draft foreign-language tracks for a large streaming catalog.','Localizing corporate or e-learning video at scale.','Generating a first-pass dub that human talent later polishes.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1704174c-c925-5996-879c-67382bd32ba2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Automatic dubbing'),'[^a-z0-9]','','g'));
