WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c30f307a-ced9-5a67-a203-482f9f18956a' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bf94a7ac-50a2-5876-8e58-03ff5886885a','Clip-gain leveling','The dialogue-editing and mixing practice of adjusting each audio clip''s clip gain — a per-clip level offset applied to the region itself, upstream of the channel''s inserts and fader — so that individual clips, phrases, or even syllables share a consistent baseline level before any compression or fader automation is applied. It flattens the raw level variation between takes, mic distances, and delivery so downstream processing works on already-even material.','Recorded dialogue lines are not all the same loudness. Clip-gain leveling means adjusting each clip''s volume by hand. You raise the quiet lines and lower the loud ones. This is done before any compressor or fader. It gives every line a steady starting level.','It gives the compressor, EQ, and fader automation a consistent input level to work from, so dynamics processing is not forced to chase wild level swings between clips. This produces smoother, more transparent dialogue than relying on the compressor alone.','An editor or re-recording mixer draws clip-gain adjustments line by line across a scene, lifting a mumbled word or pulling down a shouted one, so the whole dialogue track sits at an even level going into the premix.','Dialogue Editing',ARRAY['DX predub','Dialogue crest management','Compression','Fader automation','Gain staging','Dialogue carve']::text[],ARRAY['Using the channel fader or a compressor to fix gross level differences that should have been evened out first with clip gain.','Applying clip gain after inserts in the signal path and expecting it to behave like a pre-insert trim, changing how the compressor reacts.','Over-leveling so every word is identical, which flattens the natural dynamics and expression of the performance.','UNSAFE: Repeatedly cranking the monitor level to judge tiny clip-gain moves; sustained loud monitoring risks noise-induced hearing loss, so keep exposure within OSHA limits (85 dBA action level, 90 dBA 8-hour average).']::text[],ARRAY['Evening out a dialogue scene cut from several takes with different mic distances before the premix.','Smoothing a single line where one word jumps out louder than the rest.','Prepping edited dialogue so a light compressor can be used transparently rather than aggressively.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bf94a7ac-50a2-5876-8e58-03ff5886885a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Clip-gain leveling'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bf94a7ac-50a2-5876-8e58-03ff5886885a','739bdba4-0fac-4455-9ee2-1a56096cab92',true
