INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4d472bd5-4f29-51d3-a6d5-d6ae0b78e146','Close-up intimacy','The intimate, highly present sonic quality given to dialogue that accompanies a tight close-up shot, achieved by matching sound perspective to picture: a dry, proximate treatment with minimal room reflection, full low-mid warmth, and high presence so the voice feels physically near the listener. It is an application of the sound-perspective principle that a voice''s apparent distance should track the framing of the shot.','In a close-up shot, the camera is near the actor''s face. The sound should feel just as close and personal. So the dialogue is kept dry, warm, and present. Little room echo is added. This makes the voice feel intimate.','It reinforces the emotional closeness of a close-up by making the voice sound near and detailed, keeping the ear''s sense of distance in step with what the eye sees. Mismatched perspective breaks the illusion, so this ties sound to picture.','A re-recording mixer favors a close, dry mic perspective and adds presence for a close-up, while pulling back on reverb and room tone so the line feels whispered right beside the audience.','Sound Perspective',ARRAY['Sound perspective','Proximity effect','Dialogue anchoring','Room tone','Reverb','Perspective cut']::text[],ARRAY['Leaving a wide, roomy dialogue perspective on a close-up, so the voice sounds distant when the face is huge on screen.','Adding so much presence or low-end warmth that the voice becomes unnatural or boomy rather than intimate.','Assuming intimacy comes only from volume, when perspective, dryness, and spectral balance matter more than loudness.']::text[],ARRAY['Mixing a quiet, emotional close-up so the dialogue feels whispered right next to the viewer.','Matching a dry, present voice to a tight shot after a wider, roomier angle.','Choosing the closest, cleanest mic take to support an intimate two-shot conversation.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4d472bd5-4f29-51d3-a6d5-d6ae0b78e146' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Close-up intimacy'),'[^a-z0-9]','','g'));
