INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd46c8228-8e01-5948-bd42-c9688d99d9e1','Comb filtering from podium or desk reflections','The comb-filter interference produced when a microphone picks up both the direct sound of a talker and a short-delayed reflection of that same sound bouncing off a nearby hard surface such as a lectern top or table/desk. Because the two signals differ only by a short time delay, they sum to a response with a regular series of peaks and cancellation notches (first notch near the frequency whose half-period equals the path-length delay), giving a hollow, colored tone to the voice.','A microphone can hear the voice twice. One path is direct. The other bounces off a hard desk or podium first. The two arrive at slightly different times. When they mix, some tones get weaker and others get louder. This hollow, uneven sound is called comb filtering.','Naming this specific cause helps a technician diagnose a hollow or phasey podium/desk voice as a reflection problem rather than a bad microphone or EQ issue. Understanding it points to the right fix: change geometry or use a boundary microphone.','A sound tech hearing a hollow tone from a lectern mic recognizes desk-reflection comb filtering and either raises the mic, angles it, adds absorptive treatment, or switches to a boundary (PZM) mic on the surface to remove the delayed path.','Acoustics',ARRAY['Comb filtering','Boundary microphone','Phase cancellation','Reflection','3:1 rule','Dialogue carve']::text[],ARRAY['Trying to EQ out the notches, which cannot restore cancelled frequencies and shifts as the talker moves.','Placing a normal cardioid mic flat on or just above a hard desk, maximizing the short reflection instead of using a boundary mic.','Blaming the microphone or the room reverb when the coloration actually comes from one nearby hard surface.']::text[],ARRAY['A lectern speech mic sounding hollow because the desk surface reflects sound back into it.','A panel-discussion table where each mic picks up its talker plus a tabletop reflection.','Choosing a boundary microphone on a podium shelf to avoid the reflection path entirely.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d46c8228-8e01-5948-bd42-c9688d99d9e1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Comb filtering from podium or desk reflections'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
