INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2ecf57b1-237d-5bdf-b116-b1759125d37c','Consonant formation','The articulatory production of consonant speech sounds, described in phonetics by three dimensions: place of articulation (where in the vocal tract the airflow is constricted), manner of articulation (how the airflow is obstructed — stop, fricative, nasal, approximant, etc.), and voicing (whether the vocal folds vibrate). These parameters determine the acoustic character of each consonant and much of its intelligibility.','Consonants are speech sounds like p, s, and t. Consonant formation is how the mouth makes them. It depends on where you block the air. It also depends on how you block it. These sounds give words much of their clarity.','Understanding how consonants are formed lets an editor or mixer know which sounds carry intelligibility and where their energy sits, so processing protects clarity. It explains why sibilants, plosives, and fricatives behave differently under EQ and compression.','A dialogue editor uses knowledge of consonant formation to tell a plosive burst from a sibilant, choosing de-essing for the sibilant and gentle level or filtering for the plosive rather than one blanket fix.','Phonetics',ARRAY['Consonant-to-vowel balance','Sibilance','Plosive','Fricative','Consonant-zone management','Intelligibility']::text[],ARRAY['Treating all consonants the same, when a plosive, a sibilant, and a nasal need very different handling.','Assuming consonants carry the loudness of speech, when they are usually lower in energy than vowels but higher in frequency.','Confusing place of articulation with voicing, so the actual cause of a harsh or dull sound is misjudged.']::text[],ARRAY['Deciding whether a harsh sound is a sibilant to de-ess or a plosive to filter.','Explaining why raising high frequencies sharpens consonants but not vowels.','Teaching why certain speech sounds survive a noisy channel while others are lost.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2ecf57b1-237d-5bdf-b116-b1759125d37c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant formation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2ecf57b1-237d-5bdf-b116-b1759125d37c','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2ecf57b1-237d-5bdf-b116-b1759125d37c' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'acd09d1b-f4d7-50be-b93f-a16c75ef6444','Consonant riding','The manual dynamic technique of riding (moving in real time) the gain or fader on dialogue to lift quiet consonants — or restrain over-loud ones — relative to the surrounding vowels, so the sounds that carry intelligibility stay audible without raising the level of the whole line. It is a targeted, moment-to-moment level move rather than a static setting.','Consonants can be quiet and easy to miss. Riding means moving the volume by hand as the line plays. In consonant riding, you lift the soft consonants a little. This keeps the words clear without making the whole line louder.','It preserves intelligibility by boosting the low-energy consonants that carry meaning, doing so surgically so vowels and overall loudness are not pushed up. This keeps speech clear in a dense mix without over-compressing.','A mixer automates small gain lifts on the final consonants of words that would otherwise get buried under music or effects, keeping the ends of words readable.','Dialogue Mixing',ARRAY['Fader automation','Clip-gain leveling','Consonant-to-vowel balance','Dialogue crest management','Intelligibility','Consonant-zone management']::text[],ARRAY['Reaching for a compressor to solve buried consonants when a targeted gain ride would be more transparent.','Riding too aggressively so lifted consonants pop out and sound unnatural.','Riding overall line level instead of the consonants, which raises noise and vowels without fixing clarity.']::text[],ARRAY['Lifting soft word endings so dialogue reads over a loud music cue.','Rescuing a mumbled consonant on a single line rather than re-recording it.','Keeping whispered dialogue intelligible without raising its noise floor.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='acd09d1b-f4d7-50be-b93f-a16c75ef6444' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant riding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'acd09d1b-f4d7-50be-b93f-a16c75ef6444','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='acd09d1b-f4d7-50be-b93f-a16c75ef6444' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f2dae1ab-e26d-5465-a184-25bbc21873e1','Consonant splatter','Harsh, exaggerated bursts of energy on consonant sounds — especially sibilants and plosives — that spray forward and distract from the words, typically an artifact of over-aggressive compression or limiting, excessive high-frequency boost, or heavy-handed de-essing that pumps the consonant transients. It is the audible over-emphasis of consonant transients rather than a natural articulation trait.','Consonants like s, t, and p can burst out too hard. This harsh, spraying sound is called consonant splatter. It often comes from too much compression or too much high boost. It pulls your ear away from the words.','Naming the artifact lets a mixer trace edgy, spitty dialogue back to processing choices rather than the performance, pointing to gentler dynamics or EQ as the fix. Recognizing it protects a natural, comfortable dialogue tone.','A mixer hearing spitty s and t sounds backs off the compressor ratio, eases a high-shelf boost, or retunes the de-esser so the consonants sit naturally instead of splattering.','Dialogue Mixing',ARRAY['Sibilance','De-esser','Plosive','Consonant-zone management','Compression','Consonant formation']::text[],ARRAY['Adding more high-frequency boost for clarity, which makes the splatter worse instead of better.','Compressing or limiting so hard that transients pump and spray on every consonant.','Mistaking processing-induced splatter for the actor''s natural diction and trying to fix it at the source.']::text[],ARRAY['Taming spitty sibilance after a bright presence boost on a lead voice.','Fixing plosive bursts that jump forward under heavy limiting.','Diagnosing edgy dialogue that only appears after the compressor is engaged.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f2dae1ab-e26d-5465-a184-25bbc21873e1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant splatter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f2dae1ab-e26d-5465-a184-25bbc21873e1','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f2dae1ab-e26d-5465-a184-25bbc21873e1' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6298bc4b-4565-5a69-b0a0-bbff57e27c8d','Consonant-to-vowel balance','The relative level and spectral balance between consonants and vowels in speech. Vowels carry most of the acoustic energy and are lower in frequency, while consonants are lower in energy but higher in frequency and carry the bulk of intelligibility; managing their proportion — through EQ, dynamics, and level rides — determines how clear speech reads without becoming harsh or muddy.','Vowels are the loud, open sounds in speech. Consonants are quieter but carry most of the meaning. If vowels are too strong, words get muddy. Consonant-to-vowel balance keeps both in the right proportion. This keeps speech clear.','It frames intelligibility as a balance problem: too much vowel energy sounds full but unclear, while lifted consonants restore readability. Understanding it guides EQ and dynamics decisions toward clear, natural dialogue.','A mixer who finds dialogue full but hard to follow lifts the consonant region or rides consonants up relative to the vowels, rather than simply raising the whole track.','Phonetics',ARRAY['Consonant formation','Consonant riding','Consonant-zone management','Intelligibility','Sibilance','Dialogue carve']::text[],ARRAY['Raising overall dialogue level to fix clarity, which lifts vowels and noise without improving consonants.','Boosting consonants so far that speech becomes harsh and sibilant instead of clear.','Assuming vowels drive intelligibility, when consonants carry most of the information.']::text[],ARRAY['Making a full-sounding but unclear voice readable without raising its level.','Balancing EQ so speech stays crisp over a busy effects bed.','Judging why one actor''s diction reads more clearly than another''s at the same level.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6298bc4b-4565-5a69-b0a0-bbff57e27c8d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant-to-vowel balance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6298bc4b-4565-5a69-b0a0-bbff57e27c8d','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6298bc4b-4565-5a69-b0a0-bbff57e27c8d' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b4c423c0-7444-536b-8a55-f80d5402c5bc','Consonant-zone management','The focused control of the mid-to-high frequency band where consonant intelligibility chiefly lives — roughly the presence and sibilance region (about 2–8 kHz) — using EQ, de-essing, and level moves so consonants stay clear and articulate without becoming harsh or spitty. It treats that band as a distinct zone to be kept clean in the dialogue and, where needed, unmasked in the music and effects.','Most speech clarity lives in a band of higher tones. This band is where s and t sounds live. Consonant-zone management keeps it clean and clear. You use EQ and gentle de-essing. Done well, words stay crisp but not harsh.','It concentrates intelligibility work on the frequency range that matters most for understanding speech, so consonants read clearly while harshness is kept in check. It also guides carving competing energy from that band in other stems.','A mixer keeps the presence band of the dialogue clean, de-esses only where sibilance spikes, and dips the same band in music so consonants are never masked.','Dialogue Mixing',ARRAY['Consonant-to-vowel balance','Dialogue carve','Sibilance','De-esser','Frequency masking','Consonant formation']::text[],ARRAY['Broadly boosting highs for clarity instead of managing the specific consonant band, which adds hiss and harshness.','Over-de-essing the zone until consonants go dull and speech loses its edge.','Ignoring that music and effects share this band, so the dialogue is masked even when its own EQ is right.']::text[],ARRAY['Keeping dialogue crisp over a dense music cue by clearing the presence band in the music.','Balancing de-essing and presence so consonants read without sounding harsh.','Diagnosing masked speech by looking at the 2–8 kHz region across stems.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b4c423c0-7444-536b-8a55-f80d5402c5bc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant-zone management'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b4c423c0-7444-536b-8a55-f80d5402c5bc','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b4c423c0-7444-536b-8a55-f80d5402c5bc' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7094109e-2e26-5219-b437-3b65bb3b8399','Cross-lingual prosody transfer','In speech synthesis and automated dubbing, the transfer of the prosodic contour of a source-language utterance — its intonation, stress, rhythm, and timing (the suprasegmental features) — onto a target-language rendering, so the dubbed or converted speech preserves the expressive delivery and emphasis of the original performance across the language change. It separates prosody from linguistic content so the former can be carried over independently.','Prosody is the melody and rhythm of speech. It is how a voice rises, falls, and stresses words. In dubbing, the new language should keep the original feeling. Cross-lingual prosody transfer copies that rhythm and tone onto the new voice.','It keeps the emotion, emphasis, and pacing of the original performance intact when the words change language, so a dub feels like the same acting rather than a flat read. This matters for believable localization.','An automated-dubbing pipeline analyzes the actor''s original intonation and timing, then conditions the target-language synthesis to follow that expressive contour so stresses land where the performance intended.','Localization',ARRAY['Cross-lingual voice cloning','Prosody','Text-to-speech','Automated dubbing','Voice conversion','Lip sync']::text[],ARRAY['Assuming prosody maps one-to-one across languages, when stress and rhythm patterns differ by language.','Transferring pitch and timing so rigidly that the target language sounds unnatural.','Confusing prosody transfer, which carries delivery, with voice cloning, which carries speaker identity.']::text[],ARRAY['Preserving an actor''s emphasis and pacing when dubbing a series into another language.','Conditioning a text-to-speech model on the original performance''s intonation.','Keeping an emotional line''s rising or falling contour intact across a language change.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7094109e-2e26-5219-b437-3b65bb3b8399' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cross-lingual prosody transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7094109e-2e26-5219-b437-3b65bb3b8399','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7094109e-2e26-5219-b437-3b65bb3b8399' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fda427b8-5f11-59ef-b2a2-c626c7679b73','Cross-lingual voice cloning','A speech-synthesis technique that captures a speaker''s vocal identity (timbre and voice characteristics) from recordings in one language and reproduces that same identity speaking a different language the source speaker may never have spoken. It disentangles speaker identity from linguistic content so a cloned voice can be rendered in a new language while remaining recognizably the same person.','Voice cloning copies how a person sounds. Cross-lingual means it works across languages. So a cloned voice can speak a language the real person never spoke. Dubbing uses this to keep the same voice in every country.','It lets a production keep a consistent voice identity across localized versions, so audiences in every language hear a voice that sounds like the original performer. This supports faster, more consistent dubbing.','A localization team clones a lead actor''s voice from the original-language recordings and uses it to generate the dubbed lines in other languages, keeping the same vocal character throughout.','Localization',ARRAY['Cross-lingual prosody transfer','Text-to-speech','Automated dubbing','Voice conversion','Speaker embedding','Lip sync']::text[],ARRAY['Assuming a cloned voice automatically carries the original delivery, when identity and prosody are handled separately.','Overlooking consent, rights, and disclosure obligations when cloning a real performer''s voice.','Expecting a clone trained on one language to pronounce another perfectly without target-language modeling.']::text[],ARRAY['Keeping a star''s recognizable voice across multiple dubbed language versions.','Generating pickup lines in a performer''s voice when re-recording is impractical.','Building a consistent narrator identity across localized editions of a program.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fda427b8-5f11-59ef-b2a2-c626c7679b73' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cross-lingual voice cloning'),'[^a-z0-9]','','g'));
