INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e404e8ba-a608-532b-b2ed-6a752ce7dce9','DX predub','The dialogue predub (premix): an intermediate submix in which all edited dialogue — production dialogue, ADR, and group loop — is processed (EQ, noise reduction, de-essing, level balancing, panning) and combined into the dialogue stem ahead of the final re-recording mix. ''DX'' is the standard abbreviation for dialogue, and the DX predub is one of the D, M, and E predubs feeding the final mix.','DX is short for dialogue. A predub is an early submix of one sound group. A DX predub mixes all the cleaned-up dialogue into one balanced layer. This is done before the final mix. It makes the last stage simpler to handle.','It reduces a huge number of dialogue tracks to a coherent, pre-balanced dialogue stem, so the final mix works with manageable elements and the dialogue stem can be delivered separately for M&E and localization. It concentrates dialogue cleanup in one dedicated pass.','A re-recording mixer builds the DX predub by leveling, EQing, and de-noising every dialogue line into a smooth dialogue stem, then brings that stem into the final mix alongside the music and effects predubs.','Mix Workflow',ARRAY['Predub','DME stems','M&E','ADR','Clip-gain leveling','Final mix']::text[],ARRAY['Confusing the DX predub (the dialogue premix stem) with the final mix, which combines all predubs.','Baking effects or heavy reverb into the dialogue predub so it can no longer serve a clean M&E deliverable.','Leaving level and noise problems for the final mix instead of resolving them in the dialogue predub.','UNSAFE: Judging a long dialogue predub at high monitor SPL for hours; keep exposure within OSHA limits (85 dBA action level, 90 dBA 8-hour average) to avoid noise-induced hearing loss.']::text[],ARRAY['Building the dialogue stem for a feature before the final re-recording mix.','Delivering a clean dialogue stem so a foreign M&E version can be assembled.','Consolidating dozens of ADR and production tracks into one balanced dialogue premix.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e404e8ba-a608-532b-b2ed-6a752ce7dce9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('DX predub'),'[^a-z0-9]','','g'));
