INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6a7631d1-6ef5-5fd5-9332-f1511ac16e98','Dialogue anchoring','The mixing principle of treating dialogue as the fixed reference around which the whole mix is balanced — in level, so other elements are set relative to it, and typically in space, keeping dialogue locked to the center channel and tied to the screen regardless of on-screen movement. It keeps the audience''s attention and spatial focus grounded on the voice.','In most scenes, the dialogue is the most important sound. Dialogue anchoring keeps it as the fixed center of the mix. Everything else is balanced around it. The voice usually stays locked to the center speaker. This keeps it clear and tied to the screen.','It guarantees speech intelligibility and a stable focal point by making dialogue the constant the rest of the mix serves, rather than letting music or effects pull attention away. Anchoring to the center also keeps the voice tied to the picture in surround.','A re-recording mixer sets the dialogue level first and keeps it centered, then balances music and effects around that anchor so the voice never gets buried or wanders off-screen.','Mixing Technique',ARRAY['Center channel','Dialogue carve','Consonant riding','Sound perspective','Intelligibility','DX predub']::text[],ARRAY['Building the mix around music or effects and fitting dialogue in afterward, so speech ends up buried.','Panning dialogue off-center for a moving actor, breaking the anchor and the screen tie.','Letting dialogue level drift scene to scene, so the anchor is inconsistent for the audience.']::text[],ARRAY['Setting the dialogue level as the reference before balancing an action scene.','Keeping a voice locked to the center channel while effects move around the surround field.','Maintaining a steady dialogue anchor across a whole reel for consistent loudness.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6a7631d1-6ef5-5fd5-9332-f1511ac16e98' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue anchoring'),'[^a-z0-9]','','g'));
