INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '65cb4d6a-a8b1-5be0-8b83-4662c906f099','Dialogue carve','The use of subtractive (often dynamic or multiband) EQ to cut competing energy — usually in the music and effects, and sometimes in the dialogue itself — in the frequency range where speech lives, clearing a spectral space so the dialogue reads clearly without simply being turned up. It is a masking-avoidance move that carves a slot for the voice.','Music and effects can cover up the voice. A dialogue carve cuts those competing sounds with EQ. It clears a space for the dialogue to sit in. Think of carving a slot so the words fit through. This keeps speech easy to hear.','It solves frequency masking by removing competing energy rather than raising dialogue level, keeping speech clear while preserving the fullness and loudness of music and effects. This maintains intelligibility without a louder, fatiguing mix.','A mixer applies a dynamic EQ dip to the music in the vocal presence band, keyed off the dialogue, so the music ducks its competing frequencies only while someone is speaking.','Dialogue Mixing',ARRAY['Frequency masking','Dynamic EQ','Ducking','Consonant-zone management','Dialogue anchoring','Equalization']::text[],ARRAY['Only raising dialogue level to beat masking, which makes the whole mix louder and more fatiguing.','Carving too wide or too deep a notch in the music, so the score sounds gutted.','Carving the dialogue instead of the competing elements, thinning the voice you are trying to protect.']::text[],ARRAY['Dipping the music''s midrange under dialogue so speech stays clear in a scored scene.','Using dynamic EQ keyed to the voice to unmask dialogue only when it is present.','Clearing a spectral slot for narration over a full effects bed.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='65cb4d6a-a8b1-5be0-8b83-4662c906f099' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue carve'),'[^a-z0-9]','','g'));
