INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '79dae826-0ce3-527a-90b0-d726561c99c0','Dialogue crest management','The control of the crest factor of dialogue — the ratio between its peak levels and its average (RMS/loudness) level — using clip gain, compression, and limiting so that speech maintains a consistent average loudness without transient peaks overshooting headroom or true-peak limits. It reconciles the naturally spiky dynamics of speech with loudness and peak-delivery specifications.','Crest is the gap between the loudest peaks and the average level. Speech has sharp peaks on some sounds. Dialogue crest management tames those peaks. It uses gentle compression and limiting. This keeps dialogue at a steady, even loudness.','It lets dialogue sit at a strong, consistent average loudness for delivery specs while keeping peaks under control, so the voice is present without clipping or exceeding true-peak ceilings. This is essential for meeting loudness standards.','A mixer uses clip-gain leveling plus a gentle compressor and a true-peak limiter to reduce dialogue crest factor, hitting the program loudness target while keeping peaks below the delivery ceiling.','Level Control',ARRAY['Crest factor','Clip-gain leveling','Compression','True-peak limiting','Loudness (LUFS)','Dialogue anchoring']::text[],ARRAY['Chasing a loudness target with a limiter alone, squashing dialogue instead of managing its crest with leveling and compression.','Ignoring true-peak overshoots that pass a sample-peak meter but exceed inter-sample delivery limits.','Over-compressing so the dialogue loses all natural dynamics and sounds lifeless.','UNSAFE: Turning up the monitors to hear peak detail for long stretches; sustained loud monitoring risks hearing loss, so stay within OSHA limits (85 dBA action level, 90 dBA 8-hour average).']::text[],ARRAY['Meeting a broadcast loudness spec while keeping true peaks under the ceiling.','Smoothing a performance with wide dynamics so it holds a steady average level.','Setting up gain, compression, and limiting stages on the dialogue bus for delivery.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='79dae826-0ce3-527a-90b0-d726561c99c0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue crest management'),'[^a-z0-9]','','g'));
