INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4176730b-f464-55b3-8e20-7c7dc5bcdb2a','Dialogue focus','The set of mix decisions that direct the audience''s auditory attention to the dialogue and keep speech the perceptual focal point of the soundtrack, achieved by managing the dialogue''s relative level, spectral balance, panning and the treatment of surrounding music and effects. It ensures the voice reads as the primary narrative element even in dense scenes.','Focus is the main thing your ears notice. Dialogue focus keeps the talking as that main thing. The mixer sets the voice clearly above the music and effects. This helps the audience follow the story. It matters most in busy, loud scenes.','It exists so the spoken story information always reaches the audience clearly, preventing music or effects from pulling attention away from the voice.','A re-recording mixer rides dialogue level and dips competing elements so the voice stays the focal point through a busy action scene.','Dialogue Mixing',ARRAY['Dialogue premix','Dialogue intelligibility management','Dialogue-triggered unmasking','Ducking','Re-recording mixing']::text[],ARRAY['Assuming louder always means clearer; over-raising dialogue level can distort or make the voice sound detached rather than focused.','Ignoring frequency masking, so music or effects sharing the voice''s band bury dialogue even when its meter reads high.','UNSAFE: Pushing monitoring level far above the calibrated reference to ''find'' the balance, raising noise exposure toward OSHA action limits over a long mix day.']::text[],ARRAY['Mixing a crowded restaurant scene so the leads'' lines stay front and center.','Balancing a music-driven montage where a key line must still be understood.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4176730b-f464-55b3-8e20-7c7dc5bcdb2a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue focus'),'[^a-z0-9]','','g'));
