INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a82be866-e578-5acc-909e-d443498b6f58','Dialogue intelligibility management','The systematic process of keeping spoken dialogue clearly understandable throughout a mix, using level control, equalization, dynamic processing, de-masking of competing music and effects, and control of noise and reverberation, so speech intelligibility survives playback on varied consumer systems. It treats narrative clarity as a measurable, defended target rather than an accident of balance.','Intelligibility is how easy speech is to understand. This work keeps every line clear. The mixer removes noise, shapes tone, and lowers competing sounds. The goal is that listeners catch each word. It must still work on small TV or phone speakers.','It guarantees the audience can understand the words across many playback systems, from cinema to phone speakers, which is the core job of a dialogue mix.','A mixer checks a scene on small near-field and TV-style speakers, then EQs and de-masks so lines stay clear on limited-bandwidth systems.','Dialogue Mixing',ARRAY['Dialogue focus','Dialogue-triggered unmasking','Speech intelligibility','Dialogue premix','Loudness normalization']::text[],ARRAY['Judging intelligibility only on full-range monitors; many viewers hear dialogue on small speakers where low lines vanish.','Relying on level alone instead of clearing masking energy from music and effects in the voice''s frequency band.','UNSAFE: Raising monitor SPL well above the calibrated reference to check clarity, increasing daily noise exposure beyond OSHA permissible limits.']::text[],ARRAY['Preparing a broadcast mix that must pass a network''s dialogue-clarity check.','Fixing a scene where whispered or accented lines are hard to follow.','Checking a final mix on TV and phone speakers before delivery.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a82be866-e578-5acc-909e-d443498b6f58' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue intelligibility management'),'[^a-z0-9]','','g'));
