INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9bd87cf-650e-5b97-b16e-b4e8748bc30e','Dialogue master','The completed, mixed dialogue element of a program: the final combined dialogue stem (production dialogue, ADR, and group/loop lines) balanced and processed as delivered, kept discrete within the print master so dialogue can be separately re-balanced, replaced, or used to build music-and-effects and foreign-language versions.','A master is a finished, final version. The dialogue master is the finished mix of all the talking. It holds the on-set lines and any re-recorded lines together. It is kept as its own track group. That lets studios re-balance or swap dialogue later.','It preserves the final dialogue as a self-contained element so it can be re-balanced for different releases and reused when building music-and-effects and dubbed versions.','The mixer prints the dialogue master as a stem in the DME set, which the studio later uses to create trailer, broadcast, and foreign-language versions.','Mix Stems',ARRAY['Domestic dialogue stem','Print master','Dialogue premix','DME stems','M&E (Music and Effects)']::text[],ARRAY['Confusing the dialogue master (final mixed stem) with raw edited dialogue tracks that still need premixing.','Letting the dialogue master drift in level or phase from the M&E, so the stems no longer sum back to the approved final mix.']::text[],ARRAY['Delivering DME stems where the dialogue master is one of the three required elements.','Rebuilding a foreign-language version by replacing the dialogue master with dubbed dialogue.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9bd87cf-650e-5b97-b16e-b4e8748bc30e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue master'),'[^a-z0-9]','','g'));
