INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '24103f19-b264-5da0-8f35-afcfe5ad1c73','Dialogue matching','The craft of making re-recorded or replacement lines (ADR, group/looping) match the original production dialogue in level, timbre, microphone perspective, background ambience, and acoustic character, so replaced and original lines are indistinguishable within a scene. It combines editorial choices with mix processing such as EQ, dynamics, reverb and worldizing.','Matching means making two things sound the same. Some movie lines are re-recorded later in a studio. Those clean lines can sound wrong next to the ones shot on set. Dialogue matching makes the new lines blend in. The mixer matches loudness, tone, and room sound.','It hides the seams between production dialogue and studio replacements so the audience never notices a change of voice quality or space.','When an ADR line replaces a noisy on-set take, the mixer EQs it, adds matching reverb, and sets level so it blends with the surrounding production lines.','Dialogue Mixing',ARRAY['ADR','Dialogue reverb matching','Worldizing','Production dialogue','Dialogue premix']::text[],ARRAY['Matching level but not perspective, so a clean close ADR line sits wrong next to a wide, roomy production shot.','Forgetting the scene''s background ambience under a clean ADR line, making the replacement drop out of the world.','Over-processing ADR to match a poor production take instead of choosing the best usable source.']::text[],ARRAY['Blending an ADR replacement into a dialogue scene shot outdoors.','Matching a group/loop crowd line to the recorded location ambience.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='24103f19-b264-5da0-8f35-afcfe5ad1c73' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue matching'),'[^a-z0-9]','','g'));
