INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd7b054b7-d3e7-54d7-9bc0-dd6d0b9a2cb2','Dialogue predub','In re-recording, an intermediate mixed submix (also called a premix) that consolidates the many edited dialogue tracks (production dialogue, ADR, group) into a manageable, processed dialogue stem before the final mix, with EQ, noise reduction, level balancing and panning already applied.','A film''s dialogue lives on many separate tracks. That is too many to balance at once in the final mix. A dialogue predub combines them into one tidy group first. The mixer cleans and balances the lines in this pass. The final mix then treats dialogue as one ready element.','It reduces dozens of dialogue tracks to a coherent, pre-processed stem so the final mix stays manageable and the dialogue is already clean and balanced.','Before the final mix, the mixer builds a dialogue predub, smoothing levels and removing noise so the final pass can focus on balancing dialogue against music and effects.','Mix Stems',ARRAY['Dialogue premix','Dialogue master','Final mix','Re-recording mixing','DME stems']::text[],ARRAY['Treating the predub as final; unresolved noise or level jumps get much harder to fix once music and effects are added.','Printing the predub too hot or with irreversible processing, leaving no headroom or flexibility for the final mix.']::text[],ARRAY['Building the dialogue predub on a large feature before the final re-recording sessions.','Handing a clean dialogue predub to the mix stage so the day focuses on the DME balance.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d7b054b7-d3e7-54d7-9bc0-dd6d0b9a2cb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue predub'),'[^a-z0-9]','','g'));
