INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '75520be9-9606-5094-ab0c-13042cc5b06c','Dialogue premix','An intermediate submix that combines and pre-processes the edited dialogue tracks into a single balanced dialogue stem ahead of the final mix. ''Premix'' is used interchangeably with ''predub'' (more common in some regions and workflows) for this stage of consolidating and cleaning dialogue.','A premix is a mix done before the main mix. The dialogue premix blends all the talking tracks into one group. The mixer balances levels and cleans the sound in this step. It is the same idea as a dialogue predub. It makes the final mix simpler.','It prepares dialogue as one clean, balanced stem before the final mix, cutting track count so the final pass can concentrate on the overall balance.','A mixer runs a dialogue premix to set relative line levels and clean noise, then brings that stem into the final mix against music and effects.','Mix Stems',ARRAY['Dialogue predub','Dialogue master','Final mix','Re-recording mixing','DME stems']::text[],ARRAY['Assuming ''premix'' and ''predub'' mean different things; in most workflows they name the same intermediate stage.','Baking in aggressive processing during the premix that cannot be undone in the final mix.']::text[],ARRAY['Creating a dialogue premix stem on a television episodic mix.','Consolidating many edited dialogue tracks into one premixed stem before final.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='75520be9-9606-5094-ab0c-13042cc5b06c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue premix'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
