INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6c537fc3-a06d-5a7b-8b22-385cf6929d64','Dialogue reverb matching','A subset of dialogue matching focused on matching the reverberation and room acoustics of replacement lines (typically dry ADR) to those of the surrounding production dialogue, using convolution or algorithmic reverb, EQ and sometimes worldizing so the added space matches the on-screen space and mic distance.','Rooms add echo, called reverb. Lines shot on set carry the room''s natural echo. Lines re-recorded in a dry studio have almost none. Reverb matching adds the right echo to the studio lines. Then they sound like they belong in the same room.','It makes dry studio dialogue sit in the same acoustic space as the production dialogue, so replaced lines share the scene''s sense of room and distance.','The mixer auditions the production line, then dials convolution reverb and EQ on the ADR until its tail and tone match the scene''s space.','Dialogue Mixing',ARRAY['Dialogue matching','ADR','Worldizing','Convolution reverb','Production dialogue']::text[],ARRAY['Adding reverb by ear without referencing the actual production line, so the space is close but noticeably wrong.','Using a preset room that does not match the scene''s size, surfaces, or mic distance.','Matching reverb but ignoring background ambience, so the line still fails to blend.']::text[],ARRAY['Placing ADR into a reverberant stairwell or cathedral scene.','Matching the room tone and echo of a replaced line in a tiled bathroom set.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6c537fc3-a06d-5a7b-8b22-385cf6929d64' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue reverb matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6c537fc3-a06d-5a7b-8b22-385cf6929d64','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6c537fc3-a06d-5a7b-8b22-385cf6929d64' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4bf68cbf-9c7b-5bfc-a2be-78ec62833ed4','Dialogue-triggered unmasking','A dynamic mixing technique in which the presence of dialogue automatically reduces the level or spectral energy of competing music and effects (via sidechain ducking or frequency-selective processing) to unmask the voice, then restores them when the dialogue pauses. It applies auditory-masking principles so speech is revealed only as much as needed.','Loud music can hide, or mask, someone talking. This trick listens for the voice. When a line starts, it lowers the music and effects a little. That uncovers the words so you can hear them. When the line stops, the music comes back up.','It keeps dialogue intelligible against loud music and effects by automatically clearing masking energy only while someone is speaking, preserving impact the rest of the time.','A mixer sidechains the dialogue stem to duck the music bus, so lines cut through an action cue without permanently lowering the score.','Dialogue Mixing',ARRAY['Auditory masking','Ducking','Sidechain compression','Dialogue intelligibility management','Dialogue focus']::text[],ARRAY['Setting duck depth or timing too aggressively, so the music pumps audibly every time a line lands.','Using only broadband ducking when frequency-selective (dynamic EQ) unmasking would clear the voice band with less audible dip.','Triggering from a noisy dialogue track, so background sounds falsely duck the music.']::text[],ARRAY['Keeping lines clear over a driving action score.','Automatically dipping crowd and effects under key dialogue in a battle scene.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4bf68cbf-9c7b-5bfc-a2be-78ec62833ed4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue-triggered unmasking'),'[^a-z0-9]','','g'));
