INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8d28c81b-583d-54ac-bd49-e80e4eb96925','Diegetic voice treatment','Processing applied to a voice so it sounds as though it originates from a source within the story world (diegesis) such as a telephone, radio, PA system, intercom or television, typically using band-limiting EQ (a ''futz'' filter), controlled distortion and appropriate room or space, so the voice matches its on-screen source rather than sounding like clean narrative dialogue.','Diegetic means part of the story''s world. Sometimes a voice comes from a phone or radio in the scene. It should not sound like normal clear movie dialogue. So the mixer thins the tone and adds a little grit. Now the voice sounds like it comes from that device.','It tells the audience where a voice comes from inside the scene, making phone, radio or PA voices believable and separating them from ordinary narrative dialogue.','To make a phone-call voice, the mixer applies a band-limited ''futz'' EQ and light distortion so the line sounds like it comes through a handset.','Dialogue Mixing',ARRAY['Futz','Worldizing','Diegetic sound','Band-pass filter','Production dialogue']::text[],ARRAY['Over-futzing a source voice until it is hard to understand, hurting intelligibility for the sake of the effect.','Forgetting to place the treated voice in the scene''s space, so a ''radio'' voice sounds dry and detached.','Applying the same telephone preset to every device instead of matching the specific source, such as a cheap phone versus a PA.']::text[],ARRAY['Creating the far end of a phone conversation.','Making an announcement sound like it comes over a stadium PA system.','Treating a TV newscast heard in the background of a living-room scene.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8d28c81b-583d-54ac-bd49-e80e4eb96925' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Diegetic voice treatment'),'[^a-z0-9]','','g'));
