INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8624b02b-733f-5290-8c0f-97d87b15debe','Direct speech-to-speech translation','A speech-processing approach that translates spoken input in one language directly into spoken output in another using a single end-to-end model, without the intermediate text steps of the traditional cascade (speech recognition, then text translation, then speech synthesis). Direct systems map source speech to target speech or to intermediate discrete acoustic/spectrogram units, and can aim to preserve aspects of the speaker''s voice and prosody.','Normally, translating speech uses three steps. First it writes down the words. Then it translates the text. Then it reads the translation aloud. Direct speech-to-speech translation skips the writing step. One model turns speech in one language into speech in another.','It reduces the errors and delay that build up across the separate steps of a cascade, and can better keep the original voice and rhythm, useful for lower-latency and more natural automated translation or dubbing.','A post team may trial a direct speech-to-speech system to draft a foreign-language dub, then have linguists and mixers refine timing, performance, and blend.','Localization',ARRAY['Dubbing','Dubbing naturalness','Automatic dialogue replacement','Lip sync','Domestic dialogue stem']::text[],ARRAY['Assuming direct systems always beat the cascade; results depend heavily on training data and the language pair.','Expecting broadcast-ready dubs with no human pass for timing, lip sync, and performance.','Confusing direct speech-to-speech translation with plain voice cloning, which changes voice but not language.']::text[],ARRAY['Prototyping automated dubbing for a streaming title''s many languages.','Generating a quick translated voice track for review before formal ADR or dubbing.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8624b02b-733f-5290-8c0f-97d87b15debe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Direct speech-to-speech translation'),'[^a-z0-9]','','g'));
