INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '25c24480-5232-58be-9ebf-368978df5dab','Domestic dialogue stem','The dialogue stem containing the original-language (domestic) dialogue as mixed for the home-territory release, one of the discrete DME stems (dialogue, music, effects). It is kept separate so the domestic version uses this dialogue while foreign-language versions replace it with dubbed dialogue over the shared music-and-effects (M&E) stems.','A final mix is saved in separate groups called stems. The domestic dialogue stem holds the talking in the original language. Home-country releases use this stem. For other countries, it is swapped for dubbed lines. The music and effects stay the same underneath.','It isolates the original-language dialogue so the home version plays it while international versions can drop it and dub new dialogue over the same music and effects.','The mixer delivers the domestic dialogue stem alongside the M&E, letting the studio build the original release and hand foreign dub houses a clean bed.','Mix Stems',ARRAY['M&E (Music and Effects)','Dialogue master','Print master','DME stems','Dubbing']::text[],ARRAY['Leaving essential story sounds only in the dialogue stem, so the M&E-based foreign version loses them.','Confusing the domestic dialogue stem with the full mix; it is only the dialogue element, not dialogue plus music and effects.']::text[],ARRAY['Delivering DME stems where the domestic dialogue stem is the original-language element.','Building an international version by muting the domestic dialogue stem and adding dubbed dialogue over M&E.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='25c24480-5232-58be-9ebf-368978df5dab' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Domestic dialogue stem'),'[^a-z0-9]','','g'));
