WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='25c24480-5232-58be-9ebf-368978df5dab' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b350261d-f313-5eec-ab03-1f43db67eca2','Dubbing naturalness','The degree to which dubbed (foreign-language replacement) dialogue is perceived as natural and believable, spanning convincing vocal performance, accurate lip-sync and timing, realistic acoustic matching to the picture, and natural voice timbre, so the dubbed track does not draw attention to itself. Naturalness is a recognized perceptual attribute in subjective speech-quality assessment.','Dubbing replaces the original voices with a new language. Good dubbing should not feel fake. Naturalness is how real and believable it sounds. It covers the acting, the lip timing, and the room sound. High naturalness means you stop noticing it is dubbed.','It is the quality target for dubbing: making replacement dialogue believable and unobtrusive so viewers stay immersed rather than distracted by an artificial track.','A dubbing mixer adjusts timing, performance takes, and room matching, then judges naturalness so the localized track feels like the original.','Localization',ARRAY['Dubbing','Lip sync','Dialogue matching','Direct speech-to-speech translation','ADR']::text[],ARRAY['Prioritizing exact word timing over believable performance, producing stiff, unnatural line readings.','Recording clean dub lines without matching the scene''s room and background, so the voice floats above the picture.','Judging naturalness only in the studio and not against the picture on target playback systems.']::text[],ARRAY['Reviewing a foreign-language dub for a streaming release.','Comparing an automated dub against a human dub for believability.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b350261d-f313-5eec-ab03-1f43db67eca2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubbing naturalness'),'[^a-z0-9]','','g'));
