INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '60e003e9-2646-5c1f-b97a-b4bd8f024cfd','Dynamic dialogue carve','A mixing technique in which competing music and effects have specific frequency bands attenuated dynamically only while dialogue is present, carving out spectral space so speech stays intelligible without permanently dulling the other stems. It is commonly implemented with dynamic EQ or multiband compression keyed (sidechained) from the dialogue stem.','Dialogue carving lowers certain frequencies in the music and effects only while someone is talking. This clears a space for the voice so the words come through. When the talking stops, the music returns to full.','It keeps dialogue intelligible over loud music and effects without simply turning everything else down, preserving impact while protecting the words.','A mixer places a dynamic EQ or multiband compressor on the music and effects buses, keyed from the dialogue stem, so competing bands duck automatically whenever a line is spoken.','Dialogue Mixing',ARRAY['Dynamic-resonance control','Equalization','Sidechain','Ducking','Stems','Intelligibility']::text[],ARRAY['Carving too deeply or over too wide a band, which makes the music audibly pump or go dull whenever anyone speaks.','Relying on carving to rescue a bad balance instead of first setting a proper static level relationship between dialogue, music, and effects.','UNSAFE: Repeatedly soloing and boosting the carved bands at high monitor level, pushing dubbing-stage exposure past the OSHA 85 dBA action level over an all-day mix and risking hearing damage.']::text[],ARRAY['Keeping narration clear over a busy music cue.','Making sure a key line lands over a loud action sequence.','Balancing a dialogue-heavy scene against a dense sound-effects bed.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='60e003e9-2646-5c1f-b97a-b4bd8f024cfd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dynamic dialogue carve'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
