WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='60e003e9-2646-5c1f-b97a-b4bd8f024cfd' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f666e907-c068-5392-b05a-25408af5c545','Dynamic-resonance control','The automatic, level-dependent taming of narrow resonant peaks in a signal, frequencies that ring out or build up excessively, using dynamic or multiband EQ that attenuates each peak only when and as much as it exceeds a threshold. It reduces harsh or boomy resonances without the static, always-on cuts of fixed EQ.','Some frequencies in a voice or instrument can ring out too loud and sound harsh. Dynamic resonance control finds those peaks and turns them down only when they get too strong. The rest of the time it leaves the sound alone.','It smooths harsh or boomy resonances that come and go, keeping a natural tone while removing only the problem moments, which a fixed EQ cut cannot do cleanly.','A mixer uses a dynamic EQ or a dedicated resonance-suppression plugin on dialogue or music to catch ringing frequencies, such as a boxy room resonance or a harsh nasal peak, only when they spike.','Signal Processing',ARRAY['Dynamic dialogue carve','Equalization','De-esser','Resonance','Multiband compression']::text[],ARRAY['Setting the threshold so low that the processor acts constantly, dulling the natural tone instead of only catching peaks.','Confusing it with a static EQ notch; dynamic control acts only when the resonance exceeds the threshold, so it adapts to the material.','Chasing every tiny resonance until the sound is lifeless, rather than treating only the resonances that are audibly distracting.']::text[],ARRAY['Taming a harsh nasal or boxy peak in a dialogue recording.','Controlling a ringing room resonance in production sound.','Smoothing an aggressive resonance in a music stem during the final mix.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f666e907-c068-5392-b05a-25408af5c545' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dynamic-resonance control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
