WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f666e907-c068-5392-b05a-25408af5c545' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '98a0d64b-4804-5f12-8692-30cc760fbc65','Early-reflection matching','The practice of recreating the first, discrete reflections of a room, the early reflections that cue its size and surfaces, on a replacement or added recording such as ADR so it matches the acoustic space of the original production dialogue. It is usually done with convolution or algorithmic reverb whose early-reflection pattern and pre-delay are tuned to the on-screen environment.','When a line is re-recorded in a studio, it sounds too dry for the scene''s room. Early-reflection matching adds back the first echoes off the walls and floor. This makes the studio line sound like it fits the same space as the original.','It makes ADR and other studio recordings sit convincingly in the filmed environment, so the audience does not notice a change of acoustic between production and replacement lines.','A mixer or ADR editor uses convolution reverb, often from an impulse response of a similar space, and tunes its early reflections and pre-delay so a looped line matches the room tone and reflections of the surrounding production dialogue.','ADR & Reverb Matching',ARRAY['ADR','Convolution reverb','Reverberation','Pre-delay','Room tone','Worldizing']::text[],ARRAY['Adding only a long reverb tail while ignoring early reflections, so the ADR still does not match the room''s size and closeness.','Overdoing the reflections until the line sounds more reverberant than the surrounding production dialogue.','Forgetting to match microphone perspective and level first; reflections alone cannot fix a line recorded at the wrong distance.']::text[],ARRAY['Blending an ADR line into a scene shot in a tiled bathroom or stairwell.','Matching a studio-recorded pickup line to production dialogue in the same room.','Placing an added voice into the same acoustic space as the picture.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='98a0d64b-4804-5f12-8692-30cc760fbc65' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Early-reflection matching'),'[^a-z0-9]','','g'));
